window.__Q=window.__Q||{};window.__Q["tcm/1/A1"]=[{"q":"”乙癸同源“可归属于","o":["心和肝的关系","肺和脾的关系","肝和肾的关系","肺和肾的关系","心和肾的关系"],"a":2,"e":"肝属乙木，肾属癸水，肝肾精血同源、相互滋生，故称乙癸同源。"},{"q":"饮在肠间称为","o":["痰饮","悬饮","溢饮","支饮","留饮"],"a":0,"e":"饮邪停留于胃肠者称为痰饮，属四饮之一。悬饮为饮停胸胁，溢饮为饮溢四肢，支饮为饮停胸膈。"},{"q":"“痰阻于肺”可见的临床症状是","o":["喘咳咯痰","胸闷心悸","恶心呕吐","半身不遂","眩晕昏冒"],"a":0,"e":"痰阻于肺，肺失宣降，故见喘咳咯痰。胸闷心悸为痰阻于心，恶心呕吐为痰阻于胃，半身不遂为痰阻经络。"},{"q":"阳盛格阴的本质是","o":["虚寒证","实寒证","虚热证","实热证","虚证"],"a":3,"e":"阳盛格阴指阳热极盛深伏于里，格阴于外而现假寒象，其本质仍为实热证。"},{"q":"“阴阳二十五人”的体质分类方法出自","o":["《难经》","《伤寒论》","《金匮要略》","《黄帝内经·素问》","《黄帝内经·灵枢》"],"a":4,"e":"阴阳二十五人按五行将人分为二十五种体质类型，出自《黄帝内经·灵枢》。"},{"q":"“血府”是指","o":["心","肝","女子胞","脉","脾"],"a":3,"e":"脉为血之府，是血液运行的通道，故称血府。心主血脉，肝藏血，脾统血，女子胞为奇恒之腑。"},{"q":"卫外功能不固的脏腑病机定位是","o":["心","肺","脾","肝","肾"],"a":1,"e":"肺主气、司呼吸，外合皮毛，宣发卫气于肌表以固护外邪，故卫外功能不固的病机定位在肺。"},{"q":"大肠的主要生理功能是","o":["受盛","传化糟粕","化物","泌别清浊","通行元气"],"a":1,"e":"大肠主传化糟粕，吸收部分水液而成粪便排出。受盛化物、泌别清浊为小肠功能，通行元气为三焦功能。"},{"q":"一年季节中，“长夏”的五行归属是","o":["木","火","土","金","水"],"a":2,"e":"长夏属土。五行与四时相配，春属木、夏属火、长夏属土、秋属金、冬属水，长夏居夏秋之交，湿气主令，故归土。"},{"q":"中医治疗疾病的指导思想是","o":["治病求本","扶正祛邪","调整阴阳","三因制宜","标本缓急"],"a":0,"e":"治病求本是中医治疗疾病的指导思想，贯穿于扶正祛邪、调整阴阳、三因制宜等具体治则之中，为治则的总纲。"},{"q":"根据五行学说属于相克关系传变，错误的是","o":["木旺乘土","土旺乘水","水旺乘火","火旺乘金","土不生金"],"a":4,"e":"土不生金属五行相生关系失常的母子相及，不属相克传变。相克传变包括相乘与相侮，如木旺乘土、土旺乘水、水旺乘火、火旺乘金。"},{"q":"下列除哪项外，都体现了阴阳的互根关系","o":["阴在内，阳之守也","孤阴不生，独阳不长","阳在外，阴之使也","重阴必阳，重阳必阴","阴损及阳，阳损及阴"],"a":3,"e":"重阴必阳、重阳必阴体现阴阳在一定条件下相互转化，属阴阳转化而非互根。互根指阴阳互为存在前提，如孤阴不生、独阳不长及阴损及阳、阳损及阴。"},{"q":"元气生成的主要物质来源是","o":["肾中精气","水谷精气","清气","脏腑精气","经气"],"a":0,"e":"元气由肾中精气所化生，并赖后天水谷精气充养，其生成的主要物质来源为肾中精气，故元气根于肾。"},{"q":"根据五行学说，“肾”的“母”行的属性是","o":["金","木","土","火","水"],"a":0,"e":"五行相生中金生水，肾属水，生我者为母，故肾之母行为金。金生水，肺金为肾水之母。"},{"q":"根据情志致病理论，可引起二便失禁、遗精滑泄的是","o":["暴怒","忧思","喜乐","恐惧","思虑"],"a":3,"e":"恐伤肾，肾主藏精而司二便，恐惧伤肾则气下，可见二便失禁、遗精滑泄。怒则气上，思则气结，喜则气缓。"},{"q":"下列除哪项外，都不是暑邪的致病特点","o":["炎上","生风","易夹湿","易伤肺","阻遏气机"],"a":2,"e":"暑为阳邪，其性炎热升散，易夹湿，故“易夹湿”属暑邪致病特点。炎上、生风、伤肺、阻遏气机均非暑邪特点，分别关乎火、风、燥、湿。"},{"q":"对五时气候、物候运转规律的抽象得出的是","o":["五行相生","五行相克","五行制化","五行相乘","五行相侮"],"a":0,"e":"五行的相生次序是对五时气候、物候运转规律的抽象概括，故为五行相生。相克指五行间递相制约，制化指生克配合维持平衡。"},{"q":"行于脉外的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":3,"e":"卫气行于脉外，具有防御外邪、温养全身、调控腠理的作用。营气行于脉中，宗气聚于胸中，元气发于肾。"},{"q":"主司妇女带下的奇经脉是","o":["阳维脉","阳跷脉","带脉","任脉","督脉"],"a":2,"e":"带脉环腰一周，约束纵行诸经，主司妇女带下。任脉主胞胎，督脉总督诸阳。"},{"q":"阴阳互损的病理变化与何脏的关系密切","o":["心","肝","脾","肺","肾"],"a":4,"e":"肾为水火之宅，内寓真阴真阳，故阴阳互损的病理变化与肾关系最为密切。他脏阴阳互损最终亦多累及肾。"},{"q":"明清时期温病学家吴又可的代表作是","o":["《瘟疫论》","《温热论》","《湿热条辨》","《温病条辨》","《温热经纬》"],"a":0,"e":"吴又可为明代温病学家，其代表作是《瘟疫论》，创“戾气”学说。《温热论》为叶天士所著，《温病条辨》为吴鞠通所著。"},{"q":"人体生殖能力丧失提示","o":["心气衰竭","肝精衰竭","肺气衰竭","脾精衰竭","肾精衰竭"],"a":4,"e":"肾藏精，主生长发育与生殖，肾精亏耗则生殖能力丧失。肾精是生殖繁衍的物质基础。"},{"q":"饮食过饱，首先损伤的脏腑是","o":["心","肺","脾胃","肝胆","肾"],"a":2,"e":"饮食过饱首先损伤脾胃，导致食积、脾胃运化失常。脾胃为后天之本，主受纳腐熟水谷。"},{"q":"在下肢内侧内踝尖上8寸以下循行其前缘的经脉是","o":["足太阴脾经","足厥阴肝经","足少阴肾经","足少阳胆经","足阳明胃经"],"a":1,"e":"足厥阴肝经在下肢内侧内踝尖上8寸以下循行于前缘，8寸以上交出脾经之后。足太阴脾经行于中，足少阴肾经行于后。"},{"q":"共同参与后天之气生成的是","o":["肺、脾","肺、肝","心、肾","肝、脾","心、肺"],"a":0,"e":"后天之气由肺吸入的自然界清气与脾胃运化的水谷精气结合而成，故肺、脾共同参与其生成。脾为生气之源，肺为主气之枢。"},{"q":"患者受风后出现汗出、恶风，与风邪的何种特性有关","o":["风性数变","风性善行","风性主动","风性轻扬","风性开泄"],"a":4,"e":"风性开泄，指风邪侵袭肌表使腠理疏泄开张，故见汗出、恶风。风性善行、数变、主动分别指病位游走、发病急骤变化多端、肢体动摇。"},{"q":"导致虚热证的病理变化是","o":["阳偏衰","阴偏衰","阳偏盛","阴偏盛","阳盛格阴"],"a":1,"e":"阴偏衰即阴虚，阴不制阳而阳气相对偏亢，形成虚热证。阳偏衰则见虚寒证，阳偏盛见实热证。"},{"q":"“阴中求阳”是指","o":["在扶阳剂中适当佐以滋阴药","在滋阴剂中适当佐以扶阳药","在温阳散寒同时佐以扶阳","在清泻阳热同时佐以滋阴","以上皆是"],"a":0,"e":"“阴中求阳”指补阳时在扶阳剂中适当佐以滋阴药，使阳得阴助而生化无穷，体现阴阳互根。"},{"q":"《素问·生气通天论》中“使人薄厥”的病机是","o":["怒则气上","喜则气缓","思则气结","悲则气消","恐则气下"],"a":0,"e":"“阳气者，大怒则形气绝，而血菀于上，使人薄厥”，指大怒则气上逆，血随气升郁于头部而致昏厥。"},{"q":"下列各项可用阴阳对立制约解释的是","o":["物极必反","阴损及阳","阳盛伤阴","重阴必阳","阳生阴长"],"a":2,"e":"阳盛伤阴指阳热偏盛必然耗伤阴液，体现阴阳双方相互制约。物极必反、重阴必阳属阴阳转化，阴损及阳属阴阳互根。"},{"q":"《丹溪心法·痰》说：“善治痰者，不治痰而治气，气顺则一身之津液，亦随气而顺矣。”其理论依据是","o":["气能生津","气能行津","气能摄津","津能载气","津能养气"],"a":1,"e":"气能行津，指气是津液运行的动力，气行则津行、气顺则津液随之而顺，故治痰重在调气。"},{"q":"“水谷之海，六腑之大源也”是指","o":["胆","胃","大肠","小肠","膀胱"],"a":1,"e":"胃主受纳腐熟水谷，故称“水谷之海，六腑之大源也”。胃与脾同属后天之本，为气血生化之源。"},{"q":"心为五脏六腑之大主的理论依据是","o":["心主血","心主神志","心主思维","心总统魂魄","心总统意志"],"a":1,"e":"心主神志，心藏神而主宰人的精神意识思维活动，为五脏六腑之大主。心主血是心主神志的物质基础，非“大主”的直接依据。"},{"q":"足厥阴经行于头顶与督脉及足太阳经交于","o":["神庭穴","四神聪穴","百会穴","风府穴","风池穴"],"a":2,"e":"足厥阴肝经上达巅顶，与督脉交会于百会穴。百会位于头顶正中，为诸阳之会。"},{"q":"心血亏虚时会出现","o":["面色红润","面色萎黄","面色无华","面色晦暗","面色红赤"],"a":2,"e":"心其华在面，心血亏虚则面部失养，故见面色无华。面色萎黄多属脾虚，面色晦暗多属肾虚或血瘀。"},{"q":"主要循行于下肢的经脉是","o":["手经","足经","阴经","阳经","手三阴经"],"a":1,"e":"十二经脉中，足三阴、足三阳经主要循行于下肢，手经主要循行于上肢。"},{"q":"肺主治节主要是指肺气具有","o":["宣降体内的津液","与皮毛相合防御外邪","治理调节肺的呼吸和全身之气血津液的机能","促进宗气的形成","将脏腑代谢后的浊液下输于膀胱"],"a":2,"e":"肺主治节指肺气具有治理调节呼吸及全身气血津液的作用，是对肺主气、主宣降等功能的概括。"},{"q":"中医学认为，构成人体有机整体的中心是","o":["五脏","六腑","脑","命门","经络"],"a":0,"e":"五脏是人体生命活动的中心，通过经络与六腑、形体官窍联系，构成以五脏为中心的整体。"},{"q":"认识外感温热邪气的疾病发展规律的病机理论是","o":["六经病机","经络病机","卫气营血病机","脏腑病机","气血津液病机"],"a":2,"e":"卫气营血病机由叶天士创立，用以认识外感温热病由表入里、由浅入深的传变规律。六经病机则用于外感风寒。"},{"q":"“经络”一词首见于","o":["《黄帝内经》","《难经》","《伤寒论》","《针灸甲乙经》","《脉经》"],"a":0,"e":"“经络”一词首见于《黄帝内经》，如《素问·三部九候论》等篇已载经络之名。"},{"q":"行于脉内的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":2,"e":"正确答案是营气。营气行于脉中，具有营养周身和化生血液的作用；卫气行于脉外，二者运行部位不同。"},{"q":"人们对脏腑的最早的认识来源于","o":["哲学的推论","对人和动物的解剖观察","对人体功能的概括","对生命活动的观察","对疾病防治的总结"],"a":1,"e":"正确答案是对人和动物的解剖观察。古代医家通过解剖观察人体和动物，直接认识脏腑的部位与形态，这是脏腑概念的最早来源。"},{"q":"瘀血所致出血的特点是","o":["出血量多","出血色淡","出血紫黯或有血块","出血量小","血色鲜红"],"a":2,"e":"正确答案是出血紫黯或有血块。瘀血阻滞脉络，血行不畅而外溢，血色紫黯并常夹血块，是瘀血出血的典型特点。"},{"q":"“寒极生热”主要说明的阴阳关系是","o":["阴阳制约","阴阳对立","阴阳互根","阴阳消长","阴阳转化"],"a":4,"e":"正确答案是阴阳转化。寒极生热指寒证发展到极点可转化为热证，体现阴阳在一定条件下向对立面转化。"},{"q":"关于下法，下列说法错误的是","o":["邪在半表半里者可下","高龄津枯便秘不宜用峻下法","不可过量或久用，以防正气受损","脾胃虚弱者慎用","妇人行经期、妊娠期慎用"],"a":0,"e":"正确答案是邪在半表半里者可下。下法用于攻逐里实，邪在半表半里当以和解为主，误下易引邪入里。"},{"q":"属于五行“水”的特性，下列错误的是","o":["寒凉","流动","闭藏","向下","滋润"],"a":1,"e":"正确答案是流动。水具有寒凉、滋润、向下、闭藏的特性，流动并非水行的特性概括。"},{"q":"六淫中引起“行痹”的最主要邪气是","o":["风邪","寒邪","湿邪","暑邪","火邪"],"a":0,"e":"正确答案是风邪。风性善行而数变，风邪偏胜致痹痛游走不定，称为行痹。"},{"q":"“春夏养阳，秋冬养阴”的养生原则源于","o":["顺应自然","养性调神","护肾保精","调摄饮食","体魄锻炼"],"a":0,"e":"正确答案是顺应自然。春夏阳气生发宜养阳，秋冬阴气收藏宜养阴，体现顺应四时阴阳的养生原则。"},{"q":"“用温远温”此属于","o":["因人制宜","因地制宜","因时制宜","既病防变","未病先防"],"a":2,"e":"因时制宜指根据不同季节气候特点用药，“用温远温”即气候温热时慎用温热药，属因时制宜。因人制宜着眼于体质年龄，因地制宜着眼于地域差异。"},{"q":"《素问·五藏生成》说：“多食酸，则（ ）”","o":["骨痛而发落","脉凝泣而变色","筋急而爪枯","肉胝皱而唇揭","皮槁而毛拔"],"a":3,"e":"《素问·五藏生成》载“多食酸，则肉胝皱而唇揭”，酸味太过伤脾，脾主肌肉，故肌肉皱缩、口唇掀起。骨痛发落为多食甘之变，筋急爪枯为多食辛之变。"},{"q":"推拿相应的经络腧穴，可以调节脏腑气血，增强五脏生理功能，以下操作可以增强运化功能的是","o":["推拿内关","推脾经","推肝经","推拿劳宫","推拿神门"],"a":1,"e":"脾主运化，推脾经可健运脾胃、增强运化功能。内关、劳宫、神门分属心包与心经，主调心神，与运化无直接对应。"},{"q":"在六淫中，最易伤肺的邪气是","o":["风邪","寒邪","暑邪","湿邪","燥邪"],"a":4,"e":"燥邪干涩，易伤津液，肺为娇脏喜润恶燥，故燥邪最易伤肺，见口鼻干燥、干咳少痰。风为百病之长，寒、湿、暑伤肺均非最易。"},{"q":"“用寒远寒”是指","o":["阳虚之人，慎用寒凉","阴寒盛的体质，慎用寒凉","西北方天气寒冷，慎用寒凉","秋冬季节寒冷，慎用寒凉","老年人，慎用寒凉"],"a":3,"e":"“用寒远寒”指寒冷季节慎用寒凉药物，属因时制宜。阳虚、阴寒体质慎用寒凉属因人制宜，西北寒冷慎用寒凉属因地制宜。"},{"q":"下列表述中属于症的是","o":["肺痈","消渴","肝阳上亢","心血亏虚","恶寒"],"a":4,"e":"症是疾病过程中表现出的个别、孤立症状，恶寒为单一症状。肺痈、消渴为病名，肝阳上亢、心血亏虚为证候名称。"},{"q":"下列阳偏衰的病因有","o":["先天不足","后天失养","劳倦内伤","久病伤正","热病后期耗气"],"a":4,"e":"阳偏衰多由先天不足、后天失养、劳倦内伤、久病伤正等致阳气虚损；热病后期耗气伤阳，亦致阳气不足。前四项为阳气虚损的常见病因，本题所问阳偏衰病因中热病后期耗气属之。"},{"q":"与内湿形成密切相关的脏腑是","o":["脾","肾","肝","肺","心"],"a":0,"e":"脾主运化水湿，脾失健运则水湿内停，故内湿形成与脾关系最密切。肾主水、肺主通调水道亦参与水液代谢，但湿浊内生首责于脾。"},{"q":"人体生命活动的主宰是","o":["精","神","血","津液","痰"],"a":1,"e":"神是人体生命活动的主宰及其外在总体表现，精、气、血、津液是构成和维持生命活动的物质基础，神则统驭这些物质及其功能活动。"},{"q":"“梅核气”的病机描述最准确的是","o":["肝气郁结","脾虚生痰","痰气凝结","津伤化燥","痰火互结"],"a":2,"e":"梅核气以咽中如有物梗、吞之不下、吐之不出为特征，病机为肝气郁结、脾运失健、痰气交阻于咽喉，即痰气凝结。"},{"q":"根据五行学说，木之“所不胜”的“子”是","o":["木","水","金","火","土"],"a":1,"e":"木之所不胜为金，金之子为水，故木之“所不胜”的“子”是水。"},{"q":"下列各项，属于和法以外的是","o":["和解表里","调和肝脾","调和胆胃","调和胃肠","调和气机"],"a":4,"e":"和法包括和解表里、调和肝脾、调和胆胃、调和胃肠等具体治法，调和气机不属于和法的规范分类。"},{"q":"根据五行学说，土壅木郁属于","o":["母病及子","子病及母","相乘传变","相侮传变","母子同病"],"a":3,"e":"土壅木郁指土气壅滞而反侮木，属五行相侮传变，即所胜反侮所不胜。"},{"q":"少阳经病变常作为引经的药物是","o":["防风","柴胡","升麻","独活","川芎"],"a":1,"e":"柴胡归少阳经，为少阳经病变的引经药，能和解少阳、引药入少阳。"},{"q":"中医学理论体系发展最活跃的时期是","o":["先秦","两汉","魏晋隋唐","宋金元","明清"],"a":3,"e":"宋金元时期学派纷呈，刘完素、张从正、李杲、朱震亨等各创新说，是中医学理论体系发展最活跃的时期。"},{"q":"据五行学说，下列属于“虚则补其母”治法的是","o":["培土制水","佐金平木","滋水涵木","抑木扶土","泻火补水"],"a":2,"e":"“虚则补其母”指补益母脏以治子脏虚证，滋水涵木即补肾水以养肝木，属补母之法。"},{"q":"属于结石的多发部位，下列错误的那项是","o":["大肠","胃","胆","膀胱","肾"],"a":0,"e":"结石多发于空腔器官或管道，如胆、肾、膀胱、大肠，胃非结石好发部位。"},{"q":"和法，可以消除哪个部位之邪","o":["半表半里","表","里","上","下"],"a":0,"e":"和法通过和解或调和作用，祛除半表半里之邪，代表为小柴胡汤和解少阳。"},{"q":"下列关于经络在病理情况下的说法，错误的是","o":["内脏病变反映于五官九窍的途径","内脏病变相互影响的途径","内脏病变反映于体表一定部位的途径","外邪由表入里的途径","运行气血、感应传导的通道"],"a":4,"e":"运行气血、感应传导是经络的生理功能，非病理情况下的表现。"},{"q":"下列各项，属于补法适应证以外的是","o":["脏腑气虚","脏腑血虚","脏腑阴虚","脏腑阳虚","脏腑气滞"],"a":4,"e":"补法用于补益人体气血阴阳之虚，气滞属实证，当用疏泄行气而非补益。"},{"q":"卫气的分布特点是","o":["上出息道，下走气街","熏于肓膜，散于胸腹","通过三焦，流行全身","上荣头目，达于周身","与血同行，环周不休"],"a":1,"e":"卫气运行于脉外，熏于肓膜，散于胸腹，温养脏腑肌肉皮毛。"},{"q":"具有“藏而不泻”特点的是","o":["五脏","六腑","脏腑","五脏六腑","以上均非"],"a":0,"e":"五脏主藏精气而不泻，故满而不能实；六腑传化物而不藏。"},{"q":"下列属于汗法范畴以外的是","o":["解表","透疹","导滞","祛湿","消肿"],"a":2,"e":"汗法通过发汗解表、透疹、祛湿、消肿以祛邪，导滞属消法或下法范畴。"},{"q":"在男子，若元气亏虚，可见到滑精的症状其病机是","o":["气不行精","气不生精","气不摄精","精不化气","精气互化"],"a":2,"e":"气能摄精，元气亏虚则固摄无力，精关不固而见滑精，故为气不摄精。"},{"q":"临床上血虚日久的患者往往兼有气虚，是因为","o":["气能生血","气能行血","气能摄血","血能养气","血能载气"],"a":3,"e":"血虚日久兼气虚，因血能养气，血虚则气失所养而虚衰。气能生血说明气虚可致血虚，与题干血虚致气虚的因果方向相反。"},{"q":"人的生命活动具有生、长、壮、老的自然规律，在整个生命过程中具有决定性作用的是","o":["肾中精气盛衰","心脏的搏动","脏腑经络功能","气血津液的生成输布","阴阳的动静相召"],"a":0,"e":"肾中精气盛衰决定机体生、长、壮、老、已的全过程，是生命活动的根本。肾精化气，推动和调控各脏腑功能活动。"},{"q":"男子以肾为先天，以精、气为本，性格多为","o":["内向","喜静","细腻","多愁善感","外向"],"a":4,"e":"男子以肾为先天，肾阳主温煦推动，故男子性格多外向、好动。女子以肝为先天，阴血为主，性格多内向、喜静。"},{"q":"皮肤感受邪气常传于","o":["肺","心","肝","脾","肾"],"a":0,"e":"肺主皮毛，皮肤为肺之合，外邪袭表首先犯肺，故皮肤感受邪气常内传于肺。"},{"q":"头痛痛在巅顶，病变多属于","o":["太阳经","阳明经","少阳经","厥阴经","太阴经"],"a":3,"e":"巅顶为足厥阴肝经与督脉交会之处，头痛痛在巅顶多属厥阴经病变。太阳经头痛多在头后部，阳明经在前额。"},{"q":"用下列哪种药物可预防菌痢","o":["贯众","板蓝根","大青叶","茵陈","马齿苋"],"a":4,"e":"马齿苋清热解毒、凉血止痢，对痢疾杆菌有抑制作用，可用于预防菌痢。贯众、板蓝根、大青叶长于抗病毒，茵陈主清利湿热退黄。"},{"q":"阴偏衰所形成的病理变化是","o":["实热","实寒","虚热","虚寒","真寒假热"],"a":2,"e":"阴偏衰即阴虚，阴不制阳而阳气相对偏亢，形成虚热证。实热由阳偏盛所致，虚寒由阳偏衰所致。"},{"q":"发病的重要条件是","o":["正气不足","邪盛而正未衰","邪气","正气与邪气的斗争","正衰邪盛"],"a":2,"e":"邪气是发病的重要条件，正气不足是发病的内在根据。邪气侵袭是疾病发生的外在因素，正邪相争决定发病与否。"},{"q":"阴阳交感是指","o":["阴阳二气的运动","阴阳二气的和谐状态","阴阳二气相互对立的状态","阴阳二气相互感应","阴阳二气在运动中相互感应而交合的过程"],"a":4,"e":"阴阳交感指阴阳二气在运动中相互感应而交合的过程，是阴阳对立统一运动的表现形式。阴阳二气的运动是交感的前提，相互感应交合才是其确切含义。"},{"q":"我国第一部药物学专著是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《本草纲目》"],"a":3,"e":"《神农本草经》是我国现存最早的药物学专著，系统总结了汉代以前的药物知识，载药365种。"},{"q":"五脏病机的基本病理变化是","o":["五脏津液运行的失常","五脏阴阳气血失调","五脏精气运行失调","五脏寒热失调","五脏血液运行失调"],"a":1,"e":"五脏病机的基本病理变化是五脏阴阳气血失调，脏腑病变虽表现多样，总不离阴阳气血的失常。"},{"q":"肾其华在","o":["面","爪","毛","唇","发"],"a":4,"e":"肾藏精，精生髓，髓养骨，其华在发，发的生长与肾精盛衰密切相关。"},{"q":"以下均属于造成“津液不足”病机，错误的是","o":["燥热之邪","发热","五志之火","吐泻","伤湿"],"a":4,"e":"伤湿属湿邪为患，湿性黏滞，易困脾阳而致水湿停聚，并非津液不足的成因。燥热、发热、五志之火及吐泻耗液均可致津液不足。"},{"q":"循行于四肢外侧面的经脉是","o":["手经","足经","阴经","阳经","奇经"],"a":3,"e":"四肢外侧属阳，循行于四肢外侧面的经脉为阳经，阴经则分布于四肢内侧面。"},{"q":"心主神志最主要的物质基础是","o":["津液","精液","血液","宗气","营气"],"a":2,"e":"心主血脉而藏神，血液是神志活动最主要的物质基础，血充则神旺，血虚则神衰。"},{"q":"《脉经》的作者是","o":["张仲景","王叔和","皇甫谧","孙思邈","陈无择"],"a":1,"e":"《脉经》为西晋王叔和所著，是我国现存最早的脉学专著，系统归纳了24种脉象。"},{"q":"脾的升清作用的确切内涵是","o":["脾的阳气主升","脾以升为健","脾气散精，上归于肺","与胃的降浊相对而言","输布津液，防止水湿内生"],"a":2,"e":"脾主升清，即脾气散精，将水谷精微上输于肺，故内涵为“脾气散精，上归于肺”。脾以升为健是对升清特性的概括，非确切内涵。"},{"q":"下列五行生克规律的表述，错误的是","o":["木为水之子","火为土之母","水为火之所不胜","木为土之所不胜","金为木之所胜"],"a":4,"e":"五行相克为木克土、金克木，故金为木之所不胜而非所胜，该表述错误。木为水之子、火为土之母、水为火之所不胜、木为土之所不胜均合生克规律。"},{"q":"根据五行学说，肝病而致肾病属于","o":["母病及子","子病及母","传其所胜","传其所不胜","相克"],"a":1,"e":"肝属木、肾属水，水生木，肝为肾之子。肝病传肾即子病犯母，属子病及母。"},{"q":"适用“急则治标”治则的是","o":["阴虚咳嗽","持续低热","大出血","慢性胃痛","下肢水肿"],"a":2,"e":"急则治标指病标危急时先治其标。大出血来势急暴，危及生命，当先止血治标。阴虚咳嗽、持续低热、慢性胃痛、下肢水肿均属病缓图本之证。"},{"q":"膀胱的生理功能，依赖哪脏之气与膀胱之气的协调","o":["心气","肾气","肝气","肺气","脾气"],"a":1,"e":"膀胱贮尿排尿依赖肾的气化与固摄，故其生理功能依赖肾气与膀胱之气的协调。"},{"q":"根据五行学说，金水相生是指","o":["肺肾关系","肺脾关系","肺心关系","肺肝关系","肺胃关系"],"a":0,"e":"五行中金生水，肺属金、肾属水，故金水相生指肺肾之间的资生关系。"},{"q":"捕捉信息、传递信息的能力所指的经络功能是","o":["运行气血作用","联络沟通作用","感应传导作用","调节平衡作用","指导养生康复"],"a":2,"e":"经络感应传导作用指经络系统对刺激的感应和信息的传递，即捕捉信息、传递信息的能力。运行气血、联络沟通、调节平衡各指其他功能。"},{"q":"金元四大家中倡导“火热论”的是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素主张“六气皆从火化”，倡导火热论，为金元四大家中寒凉派代表。张从正主攻邪，朱丹溪主相火，李东垣主脾胃。"},{"q":"十二经脉气血流注形式为","o":["手足贯注","直线贯注","循环贯注","左右贯注","上下贯注"],"a":2,"e":"十二经脉气血流注始于肺经，依次流注十二经，至肝经复注于肺经，首尾相贯、如环无端，故为循环贯注。"},{"q":"机体在不同年龄阶段会呈现的不同体质特点，这体现了体质的","o":["个体差异性","群体趋同性","相对稳定性","特征连续性","动态可变性"],"a":4,"e":"体质随年龄阶段而变化的特性属体质的动态可变性，即不同年龄阶段呈现不同体质特点。"},{"q":"与心相表里的是","o":["胆","胃","大肠","小肠","三焦"],"a":3,"e":"心与小肠通过经脉相互络属构成表里关系，心经属心络小肠，小肠经属小肠络心。"},{"q":"下利适用于“热结旁流”的治则是","o":["热因热用","寒者热之","热者寒之","通因通用","塞因塞用"],"a":3,"e":"热结旁流为燥屎内结而泻下稀水，本质为实邪内结，治当因势利导、通下泻实，属通因通用。"},{"q":"肺与哪个季节相通应","o":["春","夏","长夏","秋","冬"],"a":3,"e":"肺属金，与秋气相通应，故肺应秋。"},{"q":"根据五行学说，属“相侮”传变的是","o":["心病及肝","心病及肺","心病及脾","心病及肾","肾病及心"],"a":3,"e":"相侮为反克，即所不胜之行反向克制所胜之行；心病及肾为心火反侮肾水，属相侮传变。"},{"q":"五脏阴阳失调病变的根本是","o":["心的阴阳失调","肺的阴阳失调","脾的阴阳失调","肝的阴阳失调","肾的阴阳失调"],"a":4,"e":"肾藏精，为五脏阴阳之本，肾阴肾阳为一身阴阳之根本，故五脏阴阳失调病变的根本在肾。"},{"q":"金元时期，在治疗上主张“滋阴降火”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":3,"e":"朱丹溪倡“阳常有余，阴常不足”，治疗上主张滋阴降火。"},{"q":"《素问》：“四变之动，脉与之上下”，所体现的是","o":["恒动观念","辨证论治","形神一体观","整体观念","辨证观念"],"a":3,"e":"“四变之动，脉与之上下”指四时气候变动与脉象上下相应，体现人体与自然环境的统一，属整体观念。"},{"q":"感邪后缓慢发病，这种发病形式称之为","o":["复发","继发","合病","并病","徐发"],"a":4,"e":"徐发指感邪后缓慢发病，与感邪即发的卒发相对。"},{"q":"下列各项，为疾病发生的内在原因是","o":["正气与邪气的斗争","邪盛而正未衰","邪气","正气不足","正衰邪盛"],"a":3,"e":"正气不足是疾病发生的内在原因，“正气存内，邪不可干”。邪气是发病的重要条件。"},{"q":"大肠功能失常可直接影响","o":["肾失气化","肝失疏泄","肺失肃降","脾失健运","脾失升清"],"a":2,"e":"肺与大肠相表里，大肠传导失常可影响肺气肃降，出现咳喘等症。"},{"q":"同病异治的实质是","o":["证同治异","证异治异","病同治异","证异治同","病同治同"],"a":1,"e":"同病异治指同一疾病因证候不同而治法不同，实质是证异治异。"},{"q":"根据五行学说，下列符合相克关系的是","o":["木克金","火克土","土克水","水克木","金克火"],"a":2,"e":"五行相克次序为木克土、土克水、水克火、火克金、金克木，土克水符合相克关系。"},{"q":"心神清明通畅是心哪个生理特性的体现","o":["心气下降","心主血","心藏神","心主通明","心主脉"],"a":3,"e":"心主通明指心脉以通畅为本、心神以清明为要，心神清明通畅即其体现。"},{"q":"经络学说在中医学中的应用，错误的是","o":["阐释病理变化","指导临床诊断","指导手术治疗","指导养生","指导保健"],"a":2,"e":"经络学说用于阐释病理、指导诊断与养生保健，不指导手术治疗。"},{"q":"“阴根于阳，阳根于阴”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":1,"e":"“阴根于阳，阳根于阴”指阴阳互为存在的前提，体现阴阳互根。互根即阴阳相互依存、互为根本，任何一方都不能脱离另一方而单独存在。"},{"q":"饮在胸胁称为","o":["痰饮","悬饮","溢饮","支饮","留饮"],"a":3,"e":"官方答案为支饮，但依据教材，正确答案为悬饮。饮邪停留于胸胁者为悬饮，饮停胸胁、阻滞气机而见咳唾引痛。支饮为饮停胸膈、咳逆倚息不得卧，与胸胁停饮部位不同。"},{"q":"当人处于安静状态时，血主要归藏于","o":["心","脾","肾","肺","肝"],"a":4,"e":"肝藏血，人安静时血液归藏于肝，活动时则输布于诸经。此即肝主藏血、调节血量的生理功能。"},{"q":"具有推动和调控各脏腑、经络、形体和官窍生理活动的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":0,"e":"元气由肾精化生，是人体最根本、最重要的气，能推动和调控各脏腑、经络、形体、官窍的生理活动。宗气主司呼吸行气血，营卫之气各有专司。"},{"q":"下列除哪项外，均属于结石的致病特点","o":["多发于六腑","阻滞气机，损伤脉络","在体内形成瘕块","病程较长，症状不固定","可发生绞痛"],"a":0,"e":"结石多发于肝、胆、肾、膀胱等脏腑，并非多发于六腑。结石阻滞气机、损伤脉络，可形成瘕块，病程较长而症状不固定，并可发生绞痛。"},{"q":"五音中属于五行之“木”的是","o":["宫音","角音","商音","徵音","羽音"],"a":1,"e":"五音配五行，角音属木，为木之音。宫音属土，商音属金，徵音属火，羽音属水。"},{"q":"据中医治则中标本的划分，下列错误的是","o":["正气为本，邪气为标","症状为本，病机为标","先病为本，后病为标","原发病为本，继发病为标","医生为标，患者为本"],"a":1,"e":"标本划分中，病机为本、症状为标，故“症状为本，病机为标”错误。正气为本、邪气为标，先病为本、后病为标，原发病为本、继发病为标，医生为标、患者为本。"},{"q":"联结心之搏动和肺之呼吸的中心环节是","o":["元气","宗气","心气","肺气","肝气"],"a":1,"e":"宗气积于胸中，走息道以行呼吸，贯心脉以行气血，是联结心之搏动与肺之呼吸的中心环节。元气为生命活动原动力，不直接联结心肺。"},{"q":"中医治疗疾病的根本原则是","o":["调整阴阳","治病求本","扶正祛邪","调理脏腑","三因制宜"],"a":1,"e":"治病求本是中医治疗疾病的根本原则，即探求疾病本质而针对根本原因治疗。调整阴阳、扶正祛邪、调理脏腑、三因制宜均为治病求本指导下的具体治则。"},{"q":"脾在液为","o":["涎","泪","汗","涕","唾"],"a":0,"e":"脾在液为涎，涎为口津，由脾气化生并输布，具有润泽口腔、助食物吞咽和消化的作用。泪为肝之液，汗为心之液，涕为肺之液，唾为肾之液。"},{"q":"提出“阳常有余，阴常不足”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":3,"e":"朱丹溪提出“阳常有余，阴常不足”，强调阴精易亏，主张滋阴降火。刘完素主火热论，张从正主攻邪，李东垣重脾胃，张元素重脏腑辨证。"},{"q":"“太仓”指的是","o":["三焦","胃","小肠","脾","大肠"],"a":1,"e":"胃又称“太仓”，因其受纳水谷、容量广大而得名，为“水谷之海”。三焦为决渎之官，小肠为受盛之官，脾主运化，大肠为传导之官。"},{"q":"下列关于邪正斗争决定疾病转归的说法中，错误的是","o":["邪盛正衰则病进","正盛邪衰则病退","正虚邪衰则病危","邪盛而正未衰则病为实证","正衰邪盛，阴阳离决则死亡"],"a":2,"e":"正虚邪衰时正气虽虚而邪气亦退，病情趋于缓解，并非病危。邪盛正衰则病进，正盛邪衰则病退，邪盛正未衰形成实证，正衰邪盛致阴阳离决则死亡。"},{"q":"具有“实而不满”特点的是","o":["五脏","六腑","脏腑","奇恒之腑","以上均非"],"a":1,"e":"六腑传化水谷、泻而不藏，具有“实而不满”的特点，即充实水谷而不能久藏。五脏藏精气而不泻，为“满而不实”；奇恒之腑形似腑而功能似脏。"},{"q":"属于系统病机，下列错误的是","o":["内生五邪病机","外感病机","脏腑病机","经络病机","阴阳病机"],"a":4,"e":"系统病机包括外感病机、内生五邪病机、脏腑病机、经络病机等，阴阳病机属于基本病机，不属于系统病机。"},{"q":"明清时期温病学家叶天士的代表作是","o":["《瘟疫论》","《温热论》","《湿热条辨》","《温病条辨》","《温热经纬》"],"a":1,"e":"叶天士著《温热论》，创立卫气营血辨证，为温病学派代表著作。《瘟疫论》为吴又可所著，《温病条辨》为吴鞠通所著，《湿热条辨》为薛生白所著。"},{"q":"下列属于《灵枢·营卫生会》老年人“昼不精，夜不瞑”原因错误的是","o":["气血衰","气道涩","营气衰少","心神失养","卫气内伐"],"a":3,"e":"《灵枢·营卫生会》指出老年人“气血衰，其肌肉枯，气道涩，五脏之气相搏，其营气衰少而卫气内伐”，故昼不精、夜不瞑。心神失养不属原文所述原因。"},{"q":"下列病症宜采用治其标方法的是","o":["脾虚泄泻","阴虚内热","吐血","食积泄泻","气虚感冒"],"a":2,"e":"标本缓急以急者为先，吐血来势急迫，血出不止可致气随血脱，故宜先治其标以止血。脾虚泄泻、阴虚内热、气虚感冒均以正虚为本，当缓图治本。"},{"q":"异名手足阴经交接的部位是","o":["腹","足","胸","头","手"],"a":2,"e":"十二经脉交接规律中，同名手足阳经交接于头面部，异名手足阴经交接于胸部。手三阴经从胸走手，足三阴经从足走腹胸，故异名手足阴经在胸中交接。"},{"q":"与情志抑郁最为相关的是","o":["髓海空虚","心神不守","肝失疏泄","心神不足","肝气升发太过"],"a":2,"e":"肝主疏泄，调畅气机与情志，肝失疏泄则气机郁滞，情志抑郁不舒。髓海空虚、心神不守、心神不足主司神志失常，肝气升发太过则见急躁易怒。"},{"q":"以下哪种说法是错误的","o":["舌为心之苗","汗为心之液","心为血之府","心为神之舍","心其华在面"],"a":2,"e":"“血之府”指脉，脉为血之府，心主血脉而脉为血府，故“心为血之府”表述有误。舌为心之苗、汗为心之液、心为神之舍、心其华在面均属心的生理联系。"},{"q":"体胖之人，饮食宜","o":["清淡","多食甘润生津之品","多食辛辣燥烈之品","多食碱性食物","多食酸性食物"],"a":0,"e":"体胖之人多痰湿内盛，饮食宜清淡，忌肥甘厚味以助湿生痰。甘润生津之品滋腻碍脾，辛辣燥烈之品助热伤津，均非所宜。"},{"q":"“邪之所凑，其气必虚”，主要是指","o":["邪气是发病的重要条件","邪气伤人，必伤人体的正气","正气不足，邪气易于侵犯人体","正气不足，邪气亢盛","正气虚弱，邪气不足"],"a":2,"e":"“邪之所凑，其气必虚”指正气不足则邪气易于侵犯人体，强调正气虚是发病的内在根据。邪气是发病的重要条件，但此语重心在正虚受邪。"},{"q":"治疗血虚病证时，常以补气药配合补血药使用，其理论依据是","o":["气能生血","气能行血","气能摄血","血能养气","血能载气"],"a":0,"e":"气能生血，气化是血液生成的动力，补气可助生血，故治疗血虚常补气药与补血药同用。气能行血、气能摄血分别关乎血行与血不溢脉外，与生血无直接关联。"},{"q":"“大怒则形气绝，而血菀于上”的病机是","o":["气不摄血","气机逆乱","血随气脱","血随气逆","气随血脱"],"a":3,"e":"正确答案为血随气逆。大怒伤肝，肝气上逆，血随气逆而上壅于头面，故见“血菀于上”。气机逆乱是病机总括，血随气逆才是“血菀于上”的直接机制。"},{"q":"《灵枢·本神》中提到“肝气虚则恐，实则（ ）”","o":["惊","忧","怒","喜","悲"],"a":2,"e":"正确答案为怒。肝在志为怒，肝气虚则恐，肝气实则怒，出自《灵枢·本神》。"},{"q":"阴阳互损最易发生在何脏","o":["心","肝","脾","肺","肾"],"a":4,"e":"正确答案为肾。肾为水火之宅，内寓真阴真阳，为五脏阴阳之本，故阴阳互损最易发生在肾。"},{"q":"明清时期，首创“卫气营血”辨证理论的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":2,"e":"正确答案为叶天士。叶天士创卫气营血辨证，吴鞠通创三焦辨证，吴又可著《温疫论》倡戾气学说。"},{"q":"幼儿出现五迟、五软，可能由以下哪个原因导致","o":["外感风寒","禀赋不足","饮食过饱","七情内伤","过逸"],"a":1,"e":"正确答案为禀赋不足。肾精亏虚、禀赋不足则生长发育迟缓，故见五迟、五软。"},{"q":"推动血液运行的基本动力是","o":["心的功能","脾的功能","肝的功能","肺的功能","肾的功能"],"a":0,"e":"正确答案为心的功能。心主血脉，心气推动血液在脉中运行，是推动血液运行的基本动力。"},{"q":"下列哪项不属于肺气宣发的生理作用","o":["排出体内浊气","宣散卫气","将津液输布全身，外达皮毛","将代谢后的津液化为汗液排出体外","使全身的血液会聚于肺"],"a":4,"e":"正确答案为使全身的血液会聚于肺。肺朝百脉、助心行血属肺主气功能，非宣发作用；宣发主司浊气排出、卫气与津液布散及汗液排泄。"},{"q":"亡阳的主要原因是机体内的阳气大量亡失，治宜","o":["滋阴制阳","扶阳消阴","回阳救逆","救阴固脱","阴中求阳"],"a":2,"e":"正确答案为回阳救逆。亡阳为阳气大量亡失，治当回阳救逆以挽回欲脱之阳。救阴固脱针对亡阴。"},{"q":"根据五行学说，怒“所胜”的情志是","o":["喜","思","悲","恐","惊"],"a":1,"e":"怒属木，木所胜为土，土在志为思，故怒“所胜”的情志是思。五行相克以“所胜”“所不胜”表述，木克土即木胜土。"},{"q":"关于“阴阳转化”，下列说法不确切的是","o":["寒极生热，热极生寒","重阴必阳，重阳必阴","物之生从于化，物之极由乎变","阴胜则阳病，阳胜则阴病","动复则静，阳极反阴"],"a":3,"e":"“阴胜则阳病，阳胜则阴病”说明阴阳偏胜导致对方虚损，属阴阳对立制约失常，而非转化。阴阳转化指在一定条件下向对立面转变，如寒极生热、重阴必阳。"},{"q":"使津液变成汗、尿是气的","o":["推动","温煦","固摄","气化","中介"],"a":3,"e":"气化是指气的运动产生的各种变化，津液化为汗、尿属气化作用。推动主激发促进，温煦主产热，固摄主统摄津液防流失。"},{"q":"被称为“决渎之官”的是","o":["胆","胃","三焦","小肠","膀胱"],"a":2,"e":"三焦主通行元气、运行水液，为水液运行之道路，故称“决渎之官”。决渎即疏通水道之意。"},{"q":"我国第一部临床学专著是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《医宗金鉴》"],"a":2,"e":"《伤寒杂病论》由张仲景所著，创立辨证论治体系，是我国第一部临床学专著。《黄帝内经》为理论奠基之作，《神农本草经》为药学专著。"},{"q":"七情内伤首先伤及","o":["肝魂","心神","脾意","肺魄","肾志"],"a":1,"e":"心主神明，为五脏六腑之大主，七情内伤首先伤及心神，而后影响相应脏腑。故情志所伤首伤心神。"},{"q":"可随气升降，无处不到，或在脏腑经络，或滞留于机体某些部位的是","o":["水饮","湿气","痰","瘀血","败精"],"a":2,"e":"痰随气升降流行，无处不到，可停于脏腑经络或滞留机体某些部位，致病广泛。饮多停于局部，湿性黏滞重浊，均无此特性。"},{"q":"饮食的消化吸收需要五脏协同完成，特别是","o":["肝、胆","心、小肠","肺、大肠","肾、膀胱","脾、胃"],"a":4,"e":"脾主运化水谷，胃主受纳腐熟，脾胃相合完成饮食的消化吸收，为后天之本、气血生化之源。故饮食消化吸收尤赖脾胃协同。"},{"q":"六淫中引起“着痹”的最主要邪气是","o":["风邪","寒邪","湿邪","热邪","燥邪"],"a":2,"e":"湿邪重浊黏滞，易阻遏气血、留着关节，故所致痹证以关节重着、固定不移为特点，称着痹。风邪偏胜为行痹，寒邪偏胜为痛痹。"},{"q":"下列哪一项与肝的疏泄功能关系最不密切","o":["情志的舒畅","脾胃的运纳","血液的循行","津液的输布","呼吸运动的正常"],"a":4,"e":"肝主疏泄，调畅情志、促进脾胃运化、调畅气血与津液输布。呼吸运动由肺所主，与肝疏泄关系最不密切。"},{"q":"提出“先安未受邪之地”防治原则的是","o":["王孟英","叶天士","张仲景","张景岳","张从正"],"a":1,"e":"叶天士提出“先安未受邪之地”，体现既病防变、治未病思想，即在邪气尚未传入之处预先固护。"},{"q":"胃的生理功能是","o":["受纳熟腐","受盛化物","传导变化","形成尿液","运行津液"],"a":0,"e":"胃主受纳、腐熟水谷，故其生理功能为受纳熟腐。受盛化物、传导变化为小肠、大肠功能。"},{"q":"营气的作用主要是","o":["润泽肌肤","化生血液","温煦内脏","充养脑髓","化生神志"],"a":1,"e":"营气行于脉中，化生血液并营养全身，故其主要作用是化生血液。润泽肌肤、温煦内脏偏于卫气与阳气之功。"},{"q":"内伤病因中易导致郁证、癫、狂、消渴、瘿病的是","o":["过劳","过逸","饮食不节","七情内伤","饮食偏嗜"],"a":3,"e":"七情内伤致气机失调，气滞气郁可发为郁证，气逆痰火可致癫狂，气郁化火伤阴可致消渴、瘿病。"},{"q":"津液亏虚可以导致气的衰少，其主要原因是","o":["气能生津","气能行津","气能摄津","津能载气","津能生气"],"a":4,"e":"津能生气，津液亏虚则化气乏源，故可致气虚。津能载气亦相关，但津亏致气衰主要责之津能生气。"},{"q":"以下哪项属于六腑","o":["肝","心","脾","三焦","脑"],"a":3,"e":"六腑为胆、胃、小肠、大肠、膀胱、三焦，三焦属六腑。肝、心、脾为五脏，脑为奇恒之腑。"},{"q":"与调节情志有密切关系的脏是","o":["心","脾","肝","肾","肺"],"a":2,"e":"肝主疏泄，调畅气机与情志，情志活动以气血为物质基础，肝气条达则情志舒畅。心主神明虽总司精神活动，但调节情志之畅达主要责之于肝。"},{"q":"古人对黄河中下游流域的气候变化及其与物候变化之间的相互联系的自然规律进行总结，抽象生化而形成的是","o":["阴阳学说","精气学说","元气说","五行学说","水地说"],"a":3,"e":"五行学说源于古人对黄河中下游流域气候变化与物候关系的长期观察，将木火土金水五类特性抽象为归纳自然万物的规律。阴阳学说则是对事物对立统一属性的概括。"},{"q":"下列脏腑中具有喜润恶燥特点是","o":["肺","脾","心","肝","肾"],"a":0,"e":"肺为娇脏，喜润恶燥，燥邪易伤肺津而致干咳少痰。脾喜燥恶湿，与肺之喜润恶燥相对。"},{"q":"灌注于骨节、脏腑、脑髓的是","o":["精","气","血","津","液"],"a":4,"e":"液质地稠厚，流动性小，灌注于骨节、脏腑、脑髓，起濡养作用。津则质地清稀，布散于体表肌肤孔窍。"},{"q":"魄门是指","o":["肛门","飞门","户门","吸门","贲门"],"a":0,"e":"魄门即肛门，为七冲门之末，因肺藏魄且肺与大肠相表里而得名。飞门指唇，户门指齿，吸门指会厌，贲门指胃上口。"},{"q":"五脏主五志，则忧属","o":["心","肾","肝","肺","脾"],"a":3,"e":"五脏分主五志，肺在志为忧（悲），故忧属肺。心在志为喜，肝在志为怒，脾在志为思，肾在志为恐。"},{"q":"《灵枢·天年》提到二十岁的运动特征为","o":["好趋","好走","好步","好坐","好卧"],"a":0,"e":"《灵枢·天年》述人体生长过程，二十岁血气始盛、肌肉方长，故好趋。十岁好走，三十岁好步，四十岁好坐，六十岁好卧。"},{"q":"《老子·二十五章》所说：“人法地，地法天，天法道，道法自然。”此段文字体现的思维方式是","o":["整体宏观","天人合一","天人同气","天人同构","天人同律"],"a":1,"e":"“人法地，地法天，天法道，道法自然”强调人顺应天地自然规律，体现天人合一的整体思维方式。天人同构指人体结构与天地相应，与此段文义不同。"},{"q":"与水湿痰饮形成关系密切的是","o":["心、肺、脾功能障碍","肺、脾、肝功能障碍","脾、肝、肾功能障碍","肺、脾、肾功能障碍","心、脾、肾功能障碍"],"a":3,"e":"水湿痰饮的形成主要责之肺、脾、肾三脏功能失调：肺失宣降则水津不布，脾失健运则水湿内停，肾失气化则水液泛滥。"},{"q":"感受寒邪而致“伤寒”的机理是","o":["寒邪伤于肌腠","寒邪入侵脏腑","寒邪自内而生","寒邪直中脏腑","寒邪侵及血分"],"a":0,"e":"寒邪外袭肌表，伤于肌腠，属“伤寒”；寒邪直中脏腑则为“中寒”。"},{"q":"气与血的关系主要表现在","o":["来源与分布方面","生化与运行方面","功能与结构方面","先天与后天方面","调节与统摄方面"],"a":1,"e":"气能生血、行血、摄血，血能载气、养气，故气血关系主要体现于生化与运行方面。"},{"q":"根据五行学说，五行相侮的基本概念是","o":["某行之气亢盛传及母脏","某行之气亢盛传及子脏","某行之气虚衰传及“所胜”","某行之气亢盛侵及“所不胜”","某行之气亢盛传及“所胜”"],"a":3,"e":"相侮是反克，即某行之气亢盛而侵及“所不胜”之行，属逆向克制。"},{"q":"具有生殖功能和繁衍生命的精微物质是","o":["水谷之精","广义之精","气","生殖之精","脏腑之精"],"a":3,"e":"生殖之精是禀受于父母、具有生殖功能并繁衍生命的精微物质，藏于肾。"},{"q":"“阴在内，阳之守也；阳在外，阴之使也”，说明了","o":["阴阳的相互对立","阴阳的相互消长","阴阳的相互转化","阴阳的互根互用","阴阳的相互制约"],"a":3,"e":"阴为阳之守、阳为阴之使，说明阴阳双方互为根本、相互为用，即互根互用。"},{"q":"精血津液的生成及其相互转化依靠气的","o":["推动作用","温煦作用","防御作用","固摄作用","气化作用"],"a":4,"e":"气化作用指精、血、津液等精微物质的生成及其相互转化，均依赖气化活动完成。"},{"q":"下列何项属反治治则","o":["塞因塞用","实则泻之","虚则补之","损益兼用","寒者热之"],"a":0,"e":"反治是顺从假象而治，塞因塞用即以补开塞，属反治；实则泻之、虚则补之、寒者热之均为正治。"},{"q":"据五行学说，心火亢盛致肺阴不足属于","o":["金克火","火侮金","火克金","金生火","火乘金"],"a":4,"e":"心属火，肺属金，火克金为正常制约；心火亢盛反克肺金，属相乘，即火乘金。火侮金为金气偏盛或火气偏衰时金反侮火，与此病机相反。"},{"q":"下列各项，与肾中精气生理功能关系不密切的是","o":["促进机体的生长发育","促进水液代谢","促进生殖功能的成熟","主生长发育和生殖","人体生命活动的根本"],"a":4,"e":"肾中精气主生长发育与生殖，并主水液代谢，故促进生长发育、生殖成熟及水液代谢均与其密切相关。人体生命活动的根本归于元气，非肾中精气的直接功能表述。"},{"q":"脾统血的主要作用机理是","o":["控制血液的流速","控制内脏的血液容量","控制外周血液容量","控制血液在脉道内的运行","控制血液上荣头目"],"a":3,"e":"脾统血指脾气统摄血液，使血循行于脉道之内而不外溢，故其机理是控制血液在脉道内的运行。脾不统血则见出血，与血液流速、容量无关。"},{"q":"“痰阻于心”可见的临床症状是","o":["喘咳咯痰","胸闷心悸","恶心呕吐","半身不遂","眩晕昏冒"],"a":1,"e":"痰阻于心，阻滞心脉、蒙蔽心神，可见胸闷心悸。喘咳咯痰为痰阻于肺，恶心呕吐为痰阻于胃，半身不遂为痰阻经络，眩晕昏冒为痰蒙清窍。"},{"q":"精、气、血、津、液是构成人体和维持人体的物质基础，其中属于阳的是","o":["精","气","血","津","液"],"a":1,"e":"精、血、津、液属有形阴液，气无形而主动，属阳，故精气血津液中属阳者为气。气具有推动、温煦作用，是生命活动的动力。"},{"q":"根据五行学说，“泻南补北法”的理论基础是","o":["五行相生","五行相克","五行制化","五行胜复","五行相侮"],"a":1,"e":"泻南补北法即泻心火、补肾水，用于肾阴不足、心火偏旺之证。其理论依据是五行相克中的水火相克，通过泻火补水恢复制约平衡。"},{"q":"梅核气为痰气结于","o":["心","咽喉","肠胃","肺","皮肤"],"a":1,"e":"梅核气指痰气交阻结于咽喉，症见咽中如有物梗阻、吐之不出、咽之不下。其病位在咽喉，与心、肺、肠胃、皮肤无关。"},{"q":"虚实病机中“实”的内涵是","o":["正气充实","邪气亢盛","邪盛正衰","正胜邪却","正气有余"],"a":1,"e":"实指邪气亢盛而正气未衰，正邪交争剧烈，属实证病机。正气充实、正气有余均指正气而言，不属“实”的内涵。"},{"q":"用下列哪种药可以预防细菌病","o":["贯众","板蓝根","大青叶","茵陈","马齿苋"],"a":4,"e":"马齿苋能清热解毒、凉血止痢，对细菌性痢疾等细菌病有预防作用。贯众、板蓝根、大青叶偏于抗病毒或清热解毒，茵陈主清利湿热退黄。"},{"q":"促进机体生殖机能成熟的物质是","o":["气血","元气","肾气","天癸","肾精"],"a":3,"e":"天癸是肾精充盛到一定程度产生的促进生殖机能成熟的物质，使女子月事以时下、男子精气溢泻。肾精是化生天癸的物质基础，肾气主生长发育。"},{"q":"根据五行学说，肝病而致肺病属于","o":["母病及子","相乘","子病及母","相侮","相克"],"a":3,"e":"肝属木、肺属金，金本克木，肝病及肺为反向克制，属相侮。母病及子为母脏病传子脏，相乘为过度克制所胜之脏。"},{"q":"统摄感觉功能的是","o":["脾意","肾志","心神","肺魄","肝魂"],"a":2,"e":"心藏神，神为生命活动的主宰，统摄感觉、意识与思维活动。肝藏魂、肺藏魄、脾藏意、肾藏志，分主不同精神活动。"},{"q":"下列关于五脏所藏的叙述，错误的是","o":["心藏神","肝藏魂","肺藏魄","脾藏意","肾藏智"],"a":4,"e":"肾藏志，而非藏智，故“肾藏智”表述错误。心藏神、肝藏魂、肺藏魄、脾藏意均合五脏所藏之论。"},{"q":"小儿发育迟缓，骨骼不坚的主要病机是","o":["肾精亏虚","肾阴不足","肾阳亏虚","脾气虚弱","肝血不足"],"a":0,"e":"肾精主生长发育、生髓充骨，肾精亏虚则小儿发育迟缓、骨骼不坚。肾阴肾阳偏虚各见虚热虚寒之象，脾虚主运化失职。"},{"q":"劳力过度主要伤及","o":["气","血","精","神","津液"],"a":0,"e":"劳力过度耗伤正气，积劳成疾，故主要伤气。劳神过度伤心脾、耗血，房劳过度伤肾精。"},{"q":"阴阳的征兆是","o":["寒热","上下","水火","晦明","动静"],"a":2,"e":"水火为阴阳的征兆，水属阴、火属阳，为阴阳之象的集中体现。寒热为阴阳偏盛偏衰的表现，上下、动静为阴阳属性划分。"},{"q":"经络系统中，与脏腑有直接络属关系者为","o":["经脉","络脉","十五别络","十二经脉","奇经八脉"],"a":3,"e":"十二经脉与脏腑有直接络属关系，故为正确答案。经脉中十二经脉各属一脏或一腑，并与其相表里之脏腑相互络属；奇经八脉不直接络属脏腑。"},{"q":"六淫中引起“痛痹”的最主要邪气是","o":["风邪","热邪","湿邪","寒邪","燥邪"],"a":3,"e":"寒邪为引起痛痹的最主要邪气。寒性凝滞，使气血凝滞不通，不通则痛，故寒邪偏胜致痛痹。"},{"q":"少腹疼痛，痛经闭经，经血紫色成块，或见崩漏，为瘀血阻于","o":["肝","三焦","胃肠","冲任","胞宫"],"a":4,"e":"瘀血阻于胞宫可见少腹疼痛、痛经闭经、经血紫暗成块或崩漏。胞宫为女子行经和孕育之所，瘀阻胞宫则经行异常。"},{"q":"亡血家不可发汗，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","血能载气"],"a":0,"e":"血可化津，血与津液同源互化，亡血者津液已亏，再发汗更伤津液，故不可发汗。"},{"q":"下列属于提高正气，增强抗病能力具体措施，错误的是","o":["早期诊断","药物预防及人工免疫","锻炼身体","生活起居有规律","调摄精神"],"a":0,"e":"早期诊断属于既病防变，是发病后的早期诊治措施，不属于提高正气、增强抗病能力的未病先防措施。"},{"q":"机体阳气的不足与下列哪两个脏的关系最密切","o":["心与肾","肺与脾","脾与肾","肝与脾","心与脾"],"a":2,"e":"脾为后天之本、气血生化之源，肾为先天之本、一身阳气之根，故阳气不足与脾、肾关系最密切。"},{"q":"血和津液生成的共同物质来源是","o":["水谷精微","宗气","精","元气","营气"],"a":0,"e":"血和津液均以水谷精微为共同物质来源。水谷精微经脾胃运化，化生营气与津液，奉心化赤而为血。"},{"q":"肺被称为水上之源的原因是","o":["宣发水谷精微至头面","宣发卫气于皮毛腠理","肃降宗气至脐下以资元气","呼出体内浊气","肃降水液，通调水道"],"a":4,"e":"肺主宣发肃降、通调水道，为水液代谢之上源，故称水上之源。肺通过肃降水液、通调水道使水液下输膀胱。"},{"q":"长期过度安逸，养尊处优，四体不勤，多易形成","o":["阴虚体质","痰瘀体质","阳虚体质","痰湿体质","气郁体质"],"a":1,"e":"长期过度安逸、四体不勤，气血运行不畅，脾运不健，易致痰湿内停、血行瘀滞，形成痰瘀体质。"},{"q":"目的视觉功能主要取决于","o":["肾中精气的充盈","肝血的充足","脾气的健运","肾阳的蒸化","肾阴的滋养"],"a":1,"e":"肝开窍于目，肝血充足则目得所养而能视，故目的视觉功能主要取决于肝血的充足。"},{"q":"扶正祛邪兼用的基本原则是","o":["先扶正后祛邪","先祛邪后扶正","扶正为主，兼以祛邪","扶正不留邪，祛邪不伤正","祛邪为主，兼以扶正"],"a":3,"e":"扶正与祛邪兼用须做到扶正不留邪、祛邪不伤正，使补虚与祛邪并行而不相害。"},{"q":"属于既病防变方法，下列错误的是","o":["人工免疫","早期诊断","早期治疗","先安未受邪之地","阻截病传途径"],"a":0,"e":"既病防变包括早期诊断、早期治疗、先安未受邪之地及阻截病传途径；人工免疫属于未病先防。"},{"q":"禀赋强弱的决定因素是","o":["天时地理","后天补充","父母体质","母体孕期调养","家族遗传疾病"],"a":2,"e":"禀赋强弱取决于父母体质，父母精气盛衰直接决定子代先天禀赋的强弱。"},{"q":"下列病证宜采用“通因通用”治法的是","o":["脾虚泄泻","肾虚便秘","伤风汗出","心虚多汗","肾虚尿频"],"a":2,"e":"通因通用指以通利之法治疗通泄假象之证，伤风汗出属表邪所致汗出，当用疏散通利以祛邪。"},{"q":"主要表现为血液的生成和运行关系的两脏是","o":["肺、肾","肺、肝","心、肾","心、脾","心、肺"],"a":3,"e":"心主血脉、脾主统血，血液的生成依赖脾运化水谷，运行依赖心气推动，故为心与脾。"},{"q":"属于阳的事物或现象是","o":["下降","静止","涩脉","洪脉","面色晦暗"],"a":3,"e":"阳主躁动、亢奋、明亮，洪脉脉体宽大、来势汹涌，属阳；下降、静止、涩脉、面色晦暗皆属阴。"},{"q":"饮在肌肤称为","o":["痰饮","悬饮","溢饮","支饮","留饮"],"a":2,"e":"溢饮指水饮溢于肌肤，症见肢体沉重疼痛、水肿。饮停胸胁为悬饮，饮停胸膈为支饮，饮留胃肠为痰饮。"},{"q":"“形盛则神旺，形衰则神疲，形谢则神灭”说明","o":["形神是相辅相成，密不可分的","形神是对立的","形神可以转化","形神是运动的","形神是相对的"],"a":0,"e":"形体是神的物质基础，神是形的主宰，形盛则神旺、形谢则神灭，说明形与神相辅相成、密不可分。"},{"q":"下列各项，既属病因，又属病理产物的是","o":["寒邪","热邪","燥邪","瘀血","七情"],"a":3,"e":"瘀血既是多种病因所致的病理产物，又可作为致病因素引起新的病证。寒、热、燥、七情均属病因，不属病理产物。"},{"q":"六淫中可致“首如裹”的邪气是","o":["风邪","湿邪","寒邪","燥邪","热邪"],"a":1,"e":"湿性重浊，湿邪困遏清阳，清阳不升则头目沉重如裹，故称“首如裹”。风、寒、燥、热之邪无此特征。"},{"q":"七情内伤可影响脏腑气机，其中恐则","o":["气上","气下","气缓","气结","气消"],"a":1,"e":"七情内伤影响脏腑气机，恐则气下，指恐惧使肾气不固、气陷于下。怒则气上，喜则气缓，思则气结，悲则气消。"},{"q":"金之“母”的“所胜”是","o":["木","水","金","火","土"],"a":1,"e":"金之母为土，土之所胜为水，故金之母的所胜为水。五行相克次序为木克土、土克水、水克火、火克金、金克木。"},{"q":"下列属于调理脏腑治则以外的是","o":["用寒远寒，用热远热","实则泻腑，虚则补脏","脏病治腑","虚则补其母，实则泻其子","腑病治脏"],"a":0,"e":"“用寒远寒，用热远热”属因时制宜的治则，不属调理脏腑治则。实则泻腑、虚则补脏、脏病治腑、腑病治脏及虚补母实泻子均属调理脏腑治则。"},{"q":"下列哪项是引起阳偏胜盛的机理","o":["阳邪入侵，内合人身之阳","气郁化火","五志化火，耗伤阴血","感受阴邪，从阳化热","血瘀、食积化热化火"],"a":2,"e":"阳偏胜多由感受阳邪，或五志化火、耗伤阴血而阳热亢盛。气郁化火、阴邪从阳化热、瘀血食积化热亦属阳偏胜成因，但题干所问机理以五志化火、耗伤阴血为是。"},{"q":"根据经络的循行分布路线和联系范围来取穴，称为","o":["表里配穴","阴阳取穴","循经取穴","前后配穴","整体取穴"],"a":2,"e":"循经取穴是依据经络循行分布路线及联系范围选取穴位，即“经脉所过，主治所及”。表里配穴、前后配穴属配穴方法，不以经络循行路线为取穴依据。"},{"q":"汗法用于透疹时，一般选用具有透疹功能的","o":["益气解表药","燥湿健脾药","苦寒沉降药","辛热解表药","辛凉解表药"],"a":4,"e":"透疹宜用辛凉解表药，因其辛散凉透，能疏风清热、透邪外出以助疹毒外达。辛热解表药易助热伤津，不利于疹毒透发。"},{"q":"大怒主要影响机体的","o":["呼吸功能","疏泄功能","藏精功能","气化功能","运化功能"],"a":1,"e":"大怒伤肝，肝主疏泄，怒则气上，肝气升发太过而疏泄失常。怒志所伤在肝，故主要影响肝的疏泄功能。"},{"q":"明清时期，提出“温邪上受，首先犯肺，逆传心包”的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":2,"e":"叶天士《温热论》提出“温邪上受，首先犯肺，逆传心包”，阐明温病由口鼻而入、先犯肺卫的传变规律。吴鞠通著《温病条辨》，吴又可著《温疫论》。"},{"q":"“重阴必阳”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":4,"e":"“重阴必阳”指阴发展到极盛可转化为阳，体现阴阳在一定条件下相互转化。阴阳消长是量的变化，转化是质的改变。"},{"q":"五脏分阴阳，其中属于阳中之阳的是","o":["肝","心","脾","肺","肾"],"a":1,"e":"五脏分阴阳，心肺居上属阳，心为阳中之阳，肺为阳中之阴；肝为阴中之阳，肾为阴中之阴，脾为阴中之至阴。"},{"q":"情志活动与五脏相关，其中起着主导作用的是","o":["肝","心","脾","肺","肾"],"a":1,"e":"心藏神，为五脏六腑之大主，主宰人的精神意识思维活动，故情志活动以心为主导。肝主疏泄调畅情志，但居从属地位。"},{"q":"两经或三经同时发病，这种情况是","o":["循经传","越经传","并病","直中","合病"],"a":4,"e":"合病指两经或三经同时受邪发病。并病指一经病证未罢又见另一经病证，属先后相传。"},{"q":"症见胸闷呕恶，脘腹痞满，头身困重，口腻不渴，腹泻便溏等，其病机最可能是","o":["湿浊困阻","肝郁脾虚","阳不化气","暑热内蕴","湿热下注"],"a":0,"e":"湿浊困阻中焦，气机不畅则胸闷脘痞、呕恶；湿性重浊黏滞，故头身困重、口腻不渴、便溏。肝郁脾虚以情志不遂、胁胀为主，无此湿象。"},{"q":"金元四大家中“攻邪派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":2,"e":"张从正力主祛邪，善用汗、吐、下三法，为攻邪派代表。刘完素主寒凉，李东垣重补脾，朱丹溪主滋阴，张元素为脏腑辨证代表。"},{"q":"“阴平阳秘，精神乃治”属于","o":["志健康的标志","生理健康的标","心理健康的标志","理想体质的标志","体质评价的标志"],"a":3,"e":"“阴平阳秘，精神乃治”指阴阳协调平衡，是理想体质即平和质的标志。阴阳失衡则疾病由生，此语强调平衡状态而非单一心理健康。"},{"q":"影响宗气盛衰的脏腑是","o":["心与肺","肝与肾","肺与肾","肺与脾","肝与脾"],"a":3,"e":"宗气由肺吸入的清气和脾运化的水谷精气结合而成，故其盛衰取决于肺与脾两脏。肾主纳气、心主血脉，均非宗气生成之源。"},{"q":"清气与水谷之气结合，称为","o":["元气","宗气","营气","卫气","中气"],"a":1,"e":"宗气由肺吸入的自然界清气与脾胃化生的水谷精气相合而成，聚于胸中。元气源于肾精，营卫之气源于水谷精微。"},{"q":"根据五行学说，火不暖土实际是指","o":["心阳不温脾土","肝阳不温脾土","肾阳不温脾土","肺阳不温脾土","脾阳自身不足"],"a":2,"e":"五行中火生土，火对应心，土对应脾，故火不暖土指心阳不能温煦脾土。肾阳温脾属水不暖土，须与火不暖土相区别。"},{"q":"可用阴阳对立制约解释的是","o":["寒极生热","阴损及阳","寒者热之","重阴必阳","阴中求阳"],"a":2,"e":"寒者热之是以热治寒，体现阴阳对立制约。寒极生热、重阴必阳属阴阳转化，阴损及阳、阴中求阳属阴阳互根。"},{"q":"《灵枢·本神》中提到“心气虚则悲”，病机是因为","o":["心藏神","心为君主之官","心在志为喜","心主血","心主脉"],"a":2,"e":"心在志为喜，心气虚则喜志不足而悲，故“心气虚则悲”。心藏神、主血脉为心之功能，非悲志所由生。"},{"q":"在肾的闭藏功能中，最具有生理意义的是","o":["纳气归肾，促进元气的生成","固摄二便，防止二便失禁","固摄水液，防止水液无故流失","固摄精气，防止精气无故散失","摄纳阳气，防止阳气浮越于上"],"a":3,"e":"肾藏精，闭藏功能的核心是固摄精气，防止精气无故散失，以保证肾精充盈、主生长发育与生殖。纳气归肾、固摄二便与水液均为闭藏功能的具体体现，但生理意义次于藏精。"},{"q":"精、气、神的综合表现是","o":["思维","生命","呼吸","运动","睡眠"],"a":1,"e":"精、气、神为人身三宝，精化气、气生神，三者相互为用，其综合表现即是生命活动。精、气、神盛衰直接反映生命力的强弱。"},{"q":"调神必须以下列哪项为首务","o":["健脑","补脾","养心","调肝","益肾"],"a":2,"e":"心主藏神，为五脏六腑之大主，调神以养心为首务，心神安定则脏腑功能协调。健脑、补脾、调肝、益肾虽与神相关，但非调神首务。"},{"q":"产生“薄厥”的病因，多是","o":["悲伤","过喜","大怒","惊恐","思虑"],"a":2,"e":"大怒则气上，血随气逆，郁积于上而发为薄厥，即《素问》所言“大怒则形气绝，而血菀于上，使人薄厥”。悲伤、过喜、惊恐、思虑所致气机变化与此不同。"},{"q":"与心火不能下滋于肾的病变相关的是","o":["心主通明","心主血脉","心气下降","心主藏神","心为生之本"],"a":2,"e":"心火下降以温肾水，有赖心气下降；心气不能下降则心火不能下滋于肾，致心肾不交。心主通明、主血脉、藏神均不直接说明心火下交于肾。"},{"q":"盛夏时节，患者伤暑后症见气短乏力，口渴欲饮，合理的病机解释是","o":["暑热炽盛","扰及心神","耗气伤津","暑湿夹杂","热极生风"],"a":2,"e":"暑为阳邪，其性升散，易耗气伤津，故伤暑后见气短乏力、口渴欲饮。暑热炽盛、扰及心神、暑湿夹杂、热极生风均不能解释气虚津伤之象。"},{"q":"全身气机调畅最重要的环节是","o":["肺主呼气，肾主纳气","心火下降，肾水上升","肝气主升，肺气主降","脾气主升，胃气主降","肺气宣发，亦主肃降"],"a":2,"e":"肝主升发、肺主肃降，一升一降协调，是全身气机调畅最重要的环节。脾胃升降、心肾相交、肺宣降亦参与气机调节，但以肝升肺降为关键。"},{"q":"下列阴和阳的概念中，最确切的是","o":["阴和阳是中国古代的两点论","阴和阳即是矛盾","阴和阳代表对立的事物","阴和阳代表对立又相互关联的事物属性","阴和阳说明相互关联着的事件"],"a":3,"e":"阴阳是对自然界相互关联的事物或现象对立双方属性的概括，既对立又相互关联。仅言对立或等同于矛盾，均未体现其相互关联的属性概括。"},{"q":"“泌别清浊”属于","o":["胃的功能","小肠的功能","三焦的功能","膀胱的功能","胆的功能"],"a":1,"e":"泌别清浊指小肠在受盛化物之后，将水谷分为精微与糟粕，清者上输于脾，浊者下传大肠、渗入膀胱。此为小肠主液、参与水液代谢的功能环节。"},{"q":"中医病因学将病因分为四类，其中一类为其他致病因素。下列病因属于其他致病因素的是","o":["寒邪","暑邪","寄生虫","瘀血","燥邪"],"a":2,"e":"中医病因分外感六淫、内伤七情、病理产物及其他致病因素四类。寄生虫不属六淫与情志所伤，也非痰饮瘀血结石，归入其他致病因素。"},{"q":"属于中医学基本特点的是","o":["同病异治","异病同治","审因论治","辨证论治","标本同治"],"a":3,"e":"整体观念与辨证论治是中医学两大基本特点。辨证论治以证候为施治依据，同病异治、异病同治皆其具体运用。"},{"q":"根据五行学说，面见赤色，脉见洪象的病证是","o":["肝病","心病","脾病","肺病","肾病"],"a":1,"e":"五行配属中赤色属火应心，洪脉为心之常脉，色脉俱现火象即提示病位在心，临床可见面赤、舌尖红、心胸烦热。"},{"q":"新感外邪较盛所易出现的发病形式是","o":["并病","继发","顿发","复发","徐发"],"a":2,"e":"新感外邪较盛而正气不虚，邪正交争激烈，发病急骤、症状明显，称为顿发。徐发多见于正气渐虚、邪气轻缓者。"},{"q":"六腑的共性病机特点是","o":["藏精功能失常","通降功能失常","受纳功能失常","藏泄功能失常","气化功能失常"],"a":1,"e":"六腑以传化水谷、泻而不藏为用，其气以降为顺，故共性病机为通降失常，临床多见胀满、疼痛、便秘、呕逆。"},{"q":"脘腹重坠、便意频数、久泻久利、肛门重坠的病机定位是","o":["心","肺","脾","肝","肾"],"a":2,"e":"脘腹重坠、便意频数、久泻久利、肛门重坠属中气下陷之象。脾主升清并升举内脏，故病机定位在脾。"},{"q":"五脏生理功能的特点是","o":["传化物而不藏，实而不能满","藏精气而不泻，实而不能满","传化物而不藏，满而不能实","藏精气而不泻，满而不能实","虚实交替，泻而不藏"],"a":3,"e":"五脏主藏精气而不外泻，精气宜充满而不宜壅实，故其生理特点为藏精气而不泻、满而不能实；传化物而不藏、实而不能满者为六腑。"},{"q":"属于治未病的内容，以下错误的那项是","o":["调摄精神","加强锻炼","审因论治","人工免疫","起居有常"],"a":2,"e":"治未病含未病先防与既病防变，调摄精神、加强锻炼、人工免疫、起居有常均属未病先防。审因论治是辨证求因的治则，不属治未病范畴。"},{"q":"下列选项中，不属于气机失调的是","o":["气滞","气逆","气陷","气闭","气虚"],"a":4,"e":"气机失调指气的升降出入运行失常，包括气滞、气逆、气陷、气闭、气脱。气虚属气的虚损病机，并非气机运行失常。"},{"q":"《素问·疏五过论》所说“尝贵后贱”可致“脱营”病，体现的是","o":["人体自身的完整性","自然环境对人体生理的影响","社会环境对人体生理的影响","自然环境对人体病理的影响","社会环境对人体病理的影响"],"a":4,"e":"尝贵后贱指社会地位骤降，情志抑郁不舒，日久营血暗耗而成脱营。此属社会环境变动引起的病理改变。"},{"q":"主运化水液的脏是","o":["心","肾","肺","脾","肝"],"a":3,"e":"脾主运化，既化水谷为精微，又运化水液、转输上下，为水液代谢的中枢，故主运化水液之脏为脾。"},{"q":"根据五行学说，治疗肝肾阴亏，肝阳上亢之证，应选用的是","o":["滋水涵木法","益火补土法","培土制水法","泻南补北法","金水相生法"],"a":0,"e":"肝肾阴亏、肝阳上亢属肾水不足、不能涵养肝木，治宜滋补肾阴以潜降肝阳，即滋水涵木法。"},{"q":"明清时期，提出“阳非有余”、“真阴不足”的医学家是","o":["张介宾","赵献可","叶天士","薛雪","吴又可"],"a":0,"e":"张介宾号景岳，倡阳非有余、真阴不足之说，重视温补阳气与填补真阴，为温补学派代表医家。"},{"q":"按照“穿着衣服必须不失四时之节”的原则，早春宜","o":["减裤不减衣","减衣不减裤","减衣减裤","加衣加裤","加衣减裤"],"a":1,"e":"早春阳气初升而未盛，衣着宜上薄下厚，渐减上衣以应春阳生发，下体保暖以护初生之阳，故减衣不减裤。"},{"q":"劳力过度，易损伤的脏腑是","o":["脾、肺","心、脾","心、肺","心、肝","肝、脾"],"a":0,"e":"劳则气耗，劳力过度易耗伤正气，以脾肺气虚为主，症见少气懒言、体倦乏力、动则汗出，故所伤之脏为脾肺。"},{"q":"由于心主宰整个人体的生命活动，故称心为","o":["相傅之官","将军之官","君主之官","受盛之官","传道之官"],"a":2,"e":"心主血脉而藏神，为五脏六腑之大主，主宰全身生命活动，故《素问·灵兰秘典论》称心为君主之官。"},{"q":"具有化生和贮藏精气特点的是","o":["五脏","六腑","脏腑","五脏六腑","奇经八脉"],"a":0,"e":"五脏主藏精气而不泻，能化生和贮藏精气；六腑主受盛传化水谷。故具备化生贮藏精气特点者为五脏。"},{"q":"五脏分阴阳，其中属于阴中之至阴的是","o":["肝","心","脾","肺","肾"],"a":2,"e":"五脏分阴阳：心为阳中之太阳，肺为阳中之少阴，肝为阴中之少阳，肾为阴中之太阴，脾为阴中之至阴。"},{"q":"肝火上炎和肝阳上亢均可见到的症状是","o":["胸胁刺痛","急躁易怒","两目干涩","肢体麻木","腰膝酸软"],"a":1,"e":"肝火上炎与肝阳上亢同属肝之阳热偏亢，皆可见急躁易怒、头胀痛、眩晕；两目干涩属肝阴不足，腰膝酸软属肾虚。"},{"q":"《难经经释》说：“邪扶生气而来，虽进而易退”，是指","o":["母病及子","子病犯母","相乘传变","相侮传变","表里传变"],"a":0,"e":"邪扶生气而来指母脏之邪依相生次序传于子脏，母子相生，故虽传而易于消退，属母病及子。"},{"q":"具有“阳脉之海”之称的经脉是","o":["阳维脉","阳跷脉","阴跷脉","阴维脉","督脉"],"a":4,"e":"督脉行于背部正中，总督一身之阳经，与手足三阳经及阳维脉交会于大椎，故称阳脉之海，为阳经之总纲。"},{"q":"“至虚有盛候”指的是","o":["真虚假实证","真实假虚证","真寒假热证","真热假寒证","虚实转化证"],"a":0,"e":"至虚有盛候指正气极虚而反见胀满、烦躁、脉大等盛实假象，本质仍为虚，故属真虚假实证，治当补虚。"},{"q":"明清时期，首创三焦辨证理论的医家是","o":["吴又可","赵献可","叶天士","薛雪","吴鞠通"],"a":4,"e":"吴鞠通著《温病条辨》，首创三焦辨证，以上焦、中焦、下焦为纲辨析温病的传变规律与证治方药。"},{"q":"明确提出“三因学说”的医学家是","o":["王叔和","皇甫谧","孙思邈","巢元方","陈言"],"a":4,"e":"陈言著《三因极一病证方论》，明确提出内因、外因、不内外因的三因学说，为宋代病因学代表。"},{"q":"六淫邪气中，具有伤津而不耗气致病特征的是","o":["风邪","火邪","暑邪","燥邪","湿邪"],"a":3,"e":"燥性干涩，易伤津液而见口鼻干燥、肤燥便结，然燥为秋令清肃之气，一般不耗气；暑、火之邪才既伤津又耗气。"},{"q":"从经脉分出的最大络脉分支是","o":["经别","络穴","孙络","浮络","别络"],"a":4,"e":"别络是从经脉分出的较大络脉，共十五支，具有沟通表里两经、加强经脉联系的作用；孙络、浮络为其细小分支。"},{"q":"“肾为气之根”主要是指","o":["肾阳","肾为先天之本","肾藏精","肾主纳气","肾主水液"],"a":3,"e":"肾摄纳肺所吸入之清气，使呼吸深沉有根、不致浮浅表浅，故称肾为气之根，其要在肾主纳气。"},{"q":"气化功能失常而出现小便异常的病机定位是","o":["大肠","小肠","膀胱","胃","胆"],"a":2,"e":"膀胱主贮尿排尿，全赖肾阳温煦与肾气固摄，即气化作用。气化失常则见尿频、尿闭或小便失禁，病位在膀胱。"},{"q":"二便与五脏密切相关，关系最为密切的是","o":["肝","心","脾","肺","肾"],"a":4,"e":"肾开窍于二阴，主司二便：肾阳温煦推动大肠传导，肾之气化主膀胱开合，故二便与肾关系最为密切。"},{"q":"称为“罢极之本”的脏是","o":["心","肝","脾","肾","肺"],"a":1,"e":"肝主筋，筋膜有赖肝血濡养方能运动有力、耐于疲劳，故《素问·六节藏象论》称肝为罢极之本。"},{"q":"以下属于奇恒之腑的是","o":["胆","胃","三焦","小肠","大肠"],"a":0,"e":"奇恒之腑包括脑、髓、骨、脉、胆、女子胞。胆虽属六腑，却贮藏精汁而不传化水谷，故兼列其中。"},{"q":"膻中又称作","o":["气海","血海","髓海","水谷之海","经脉之海"],"a":0,"e":"膻中位于胸中，为宗气汇聚之所，宗气积于此而贯心脉、行呼吸，故膻中又称气海，为八会穴之气会。"},{"q":"根据五行学说，下列属“相侮”传变的是","o":["火传木","火传金","火传土","火传水","水传火"],"a":3,"e":"相侮即反克。火本受水制，火气过盛反而侮其所不胜之水而传及肾，故火传水属相侮传变。"},{"q":"观察“虚里”变化，以了解其盛衰的是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"虚里为左乳下心尖搏动处，宗气聚于胸中、贯心脉以行气血，故察虚里之动势可测知宗气盛衰。"},{"q":"足三阴经的走向是","o":["从胸走手","从手走头","从头走足","从足走腹胸","从足走手"],"a":3,"e":"十二经脉走向为手三阴从胸走手、手三阳从手走头、足三阳从头走足、足三阴从足走腹胸，交接于胸腹头手足。"},{"q":"水精四布，五经并行是指肺哪两个功能的协调","o":["肺朝百脉和主治节","肺主气和司呼吸","宣发与肃降","肺主行水","肺主皮毛"],"a":2,"e":"肺宣发津液于肌腠皮毛，肃降水液下输膀胱，水精四布、五经并行正是宣发与肃降协调的结果。"},{"q":"人体精神活动的物质基础是","o":["精","肝","血","神","津液"],"a":2,"e":"血含神气，为神志活动的物质基础，血气充盈则精神充沛、思维清晰，故《素问》言血气者人之神。"},{"q":"“大实有羸状”指的是","o":["真虚假实证","真实假虚证","真寒假热证","真热假寒证","虚实夹杂证"],"a":1,"e":"大实有羸状指邪气亢盛、结聚于内，反见倦怠少气、脉细等虚羸假象，本质为实，属真实假虚证。"},{"q":"生命的基本特征为","o":["气化作用","气机升降","气血充盈","脏腑功能正常","经络功能正常"],"a":0,"e":"气化指气的运动所引起的精气血津液代谢及其相互转化，是生命活动的基本特征，气化息则生命止。"},{"q":"肺之窍是指","o":["鼻","舌","耳","目","口"],"a":0,"e":"肺开窍于鼻，鼻为肺之外窍，司嗅觉并为呼吸之气出入的门户。肺气和利则鼻窍通利，肺病多见鼻塞流涕。"},{"q":"下列不属于　“七冲门”的是","o":["气门","吸门","贲门","飞门","户门"],"a":0,"e":"七冲门指飞门、户门、吸门、贲门、幽门、阑门、魄门，为水谷通行之要冲。气门指汗孔，不属七冲门。"},{"q":"属于“证候”选项，下列错误的是","o":["四诊检查所得","内外致病因素","疾病的特征","疾病的性质","疾病的全过程"],"a":4,"e":"证候是疾病过程中某一阶段的病理概括，含病因、病位、病性、病势及机体反应状态，反映阶段而非疾病全过程。"},{"q":"明清时期，提出“凡温病者，始于上焦”、“上焦不治则传中焦”、“中焦不治即传下焦”的医家是","o":["吴又可","赵献可","叶天士","薛雪","吴鞠通"],"a":4,"e":"此语出自《温病条辨》。吴鞠通以三焦为纲辨治温病，指出上焦不治传中焦、中焦不治传下焦的传变规律。"},{"q":"金元四大家中，“养阴派”的代表人物是","o":["刘完素","李杲","张从正","朱震亨","张元素"],"a":3,"e":"朱震亨号丹溪，倡阳常有余、阴常不足之说，主张滋阴降火、保护阴精，后世称为养阴派。"},{"q":"下列各项，决定疾病是否发生的是","o":["饮食情志","居住环境","正邪斗争的胜负","六淫性质","体质强弱"],"a":2,"e":"正气存内、邪不可干，邪之所凑、其气必虚。发病与否取决于正气强弱与邪气盛衰的对比，即正邪斗争的胜负。"},{"q":"“动极者镇之以静”主要说明的阴阳关系是","o":["阴阳相互转化","阴阳互根互用","阴阳相互消长","阴阳对立制约","阴阳动态平衡"],"a":3,"e":"动极者镇之以静，指以静制动、以寒制热，体现阴阳双方相互制约、以平为期的对立制约关系。"},{"q":"根据五行学说，属五行相乘传变的是","o":["肝病及心","肝病及肾","肝病及肺","肝病及脾","脾病及心"],"a":3,"e":"相乘为太过之克。肝属木、脾属土，肝气亢盛过度克制脾土，即木乘土，故肝病及脾属相乘传变。"},{"q":"主要起维系全身经脉作用的经脉是","o":["正经","奇经","阳跷脉、阴跷脉","阳维脉、阴维脉","督脉"],"a":3,"e":"阳维脉维于阳、阴维脉维于阴，二者交会联系诸阴诸阳经，共同维系全身经脉，主一身之表里。"},{"q":"与气的生成密切相关的脏是","o":["心肝脾","肺肝肾","肺脾肾","心肺肾","肝脾肾"],"a":2,"e":"气由肾中精气、脾胃化生水谷精微与肺吸入清气相合而成，故气的生成与肺、脾、肾三脏关系最为密切。"},{"q":"治疗血虚证时，常在补血药中配用益气之品的理论依据是","o":["血能生气","气能行血","气能摄血","血能载气","气能生血"],"a":4,"e":"气为血之帅，气旺则血充。补血剂中佐以益气药，可助气血生化、提高补血疗效，其依据为气能生血。"},{"q":"根据五行学说，面见青色，脉见弦象的病证是","o":["肝病","心病","脾病","肺病","肾病"],"a":0,"e":"五行配属中青色属木应肝，弦脉为肝之常脉，色脉俱见木象，提示病位在肝，常见胁痛、易怒、目赤。"},{"q":"分布在人体皮肤表面的络脉是","o":["浮络","孙络","太阴别络","厥阴别络","少阳别络"],"a":0,"e":"络脉自别络层层细分，浮行于皮肤表面者称浮络，其最细小者称孙络，二者均为络脉的分支。"},{"q":"空腹进食大量未成熟的柿子或黑枣，易形成","o":["肝结石","胃结石","胆结石","肾结石","膀胱结石"],"a":1,"e":"未成熟柿子、黑枣含大量鞣质，空腹时在胃酸作用下凝结成块，滞积胃中，日久形成胃结石。"},{"q":"既属于六腑，又属于奇恒之腑的是","o":["三焦","脑","胆","髓","胃"],"a":2,"e":"胆属六腑，又因形态中空而贮藏精汁、不传化水谷，兼列奇恒之腑，为六腑中唯一两属者。"},{"q":"先哲对脏腑功能的认识最早来自","o":["解剖观察","哲学推论","对疾病的总结","对人体功能的概括","对生命活动的观察"],"a":0,"e":"古人对脏腑功能的最早认识来自解剖观察，《灵枢·经水》即载有脏腑大小、坚脆、容量等实测记录。"},{"q":"头痛痛在后头及项部，病变多在","o":["阳明经","太阳经","厥阴经","少阳经","任脉"],"a":1,"e":"后头及项部为足太阳膀胱经循行所过，故该处头痛多属太阳经病变，常伴项强、恶风寒、脉浮。"},{"q":"上达头部巅顶的经脉是","o":["手太阴肺经","足阳明胃经","足厥阴肝经","足太阳膀胱经","足少阴肾经"],"a":2,"e":"足厥阴肝经沿喉咙之后上入颃颡，连目系，上出额，与督脉会于巅顶，故巅顶头痛多责之肝经。"},{"q":"蛔虫致病，临床常见","o":["发热恶寒","腹痛腹泻","脐周疼痛","口渴神昏","胁下癥积"],"a":2,"e":"蛔虫寄居小肠，扰动气机，临床以脐周阵发性疼痛、时作时止为特征，可伴吐蛔、面黄肌瘦。"},{"q":"人体气虚可见自汗的症状，其理论依据是","o":["气能生津","气能行津","气能摄津","津能载气","津能养气"],"a":2,"e":"气对津液具有固摄作用，使津液循常道而不妄泄。气虚固摄无权则津液外泄而自汗，其依据为气能摄津。"},{"q":"具有“满而不实”特点的是","o":["五脏","六腑","脏腑","五脏六腑","以上均非"],"a":0,"e":"五脏藏精气而不泻，精气宜充满而不宜壅实，故其特点为满而不实；实而不能满者指六腑。"},{"q":"中医学的学科属性是","o":["属于自然科学的范畴","属于人文社会科学的范畴","属于中国古代哲学的范畴","属于自然哲学的范畴","以自然科学为主体，与人文社会科学多学科相交融的医学科学"],"a":4,"e":"中医学以自然科学为主体，同时与人文社会科学多学科相交融，属具有双重属性的医学科学体系。"},{"q":"房劳过度易损伤的脏腑是","o":["肝","心","脾","肺","肾"],"a":4,"e":"肾藏精，主生殖与生长发育。房劳过度直接耗损肾精肾气，见腰膝酸软、眩晕耳鸣、性功能减退，故伤肾。"},{"q":"《素问·五脏别论》称为“实而不能满”者，指的是","o":["五脏","六腑","奇恒之腑","脏腑","脑髓"],"a":1,"e":"六腑受盛传化水谷、泻而不藏，故实而不能满；五脏藏精气而不泻，精气宜充满而不宜壅实，故满而不能实。"},{"q":"暑季常感四肢困倦、胸闷呕吐、大便溏泄，是由于","o":["暑性炎热","扰乱心神","暑湿夹杂","热极生风","耗气伤津"],"a":2,"e":"暑季湿气偏盛，暑邪常夹湿为患。湿困脾胃、阻滞气机，故见四肢困倦、胸闷呕吐、大便溏泄。"},{"q":"五行学说中“金”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":2,"e":"金曰从革，指金性刚柔相济，可随人意变革成形，引申为清肃、收敛、肃杀之性，对应肺与秋。"},{"q":"下列除哪项外都是结石形成的常见原因","o":["情志不遂","体质因素","喜欢甜食","服药不当","空腹食柿"],"a":2,"e":"结石多因情志不遂、体质偏颇、服药不当、空腹食柿等致湿热蕴结、浊质沉积而成。嗜食甜食不属其常见成因。"},{"q":"狭义之精指的是","o":["津液","生殖之精","血","水谷之精","脏腑之精"],"a":1,"e":"狭义之精专指肾所藏、主生殖的生殖之精；广义之精则包括水谷之精、脏腑之精及血、津液等。"},{"q":"下列哪种情况不能构成阴阳关系","o":["寒与热","动与静","上升和外出","表与里","水与火"],"a":2,"e":"阴阳须为同一事物相互对立的两方面。上升与外出同属阳的特性，方向一致而无对立，故不构成阴阳关系。"},{"q":"与生长发育、生殖关系最密切的脏腑是","o":["心","脾","肺","肾","肝"],"a":3,"e":"肾藏精，精能化气生血，主生长发育与生殖，齿更发长、天癸至竭皆由肾精充盛与否决定，故关系最密切。"},{"q":"以下除哪项外均属于内生五邪","o":["内风","内寒","内暑","内湿","内燥"],"a":2,"e":"内生五邪指内风、内寒、内湿、内燥、内火，由脏腑气血失调而生。暑为外感时令之邪，并无内暑之说。"},{"q":"夺血者无汗，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","血能载气"],"a":0,"e":"血与津液同源互化，血可化津以补充津液。失血者津液已亏，故不可再发其汗，以免津血两伤。"},{"q":"昼夜分阴阳，上午为","o":["阴中之阳","阳中之阳","阳中之阴","阴中之阴","阴中之至阴"],"a":1,"e":"昼为阳，夜为阴。上午阳气渐盛属阳中之阳，下午阳气渐衰属阳中之阴；前半夜阴中之阴，后半夜阴中之阳。"},{"q":"疾病的发生是因为","o":["阴偏盛","阳偏衰","阴阳失调","阴阳互损","阴阳转化"],"a":2,"e":"疾病发生的总病机是阴阳失调，即阴阳偏盛偏衰、互损、格拒、亡失等导致阴阳相对平衡破坏。"},{"q":"与宗气生成关系密切的是肺的哪项功能","o":["肺主一身之气","肺主行水","肺气宣发","肺朝百脉","肺主治节"],"a":0,"e":"宗气由肺吸入自然清气与脾胃上输水谷之气相合而成，聚于胸中，故其生成与肺主一身之气密切相关。"},{"q":"脾统血的作用机制是","o":["气的固摄作用","气的温煦作用","气的气化作用","气的卫外作用","气的防御作用"],"a":0,"e":"脾统血指脾气使血行脉中而不外溢，其机制在于气对血液的固摄，故临床以益气摄血治脾不统血。"},{"q":"养生首见于","o":["《黄帝内经》","《庄子·内篇》","《类经》","《摄生消息论》","《寿世保元》"],"a":1,"e":"养生一词最早见于《庄子·内篇·养生主》，指顺应自然、护养生命之法，后为中医养生学所沿用。"},{"q":"根据五行学说，心病及肝属于","o":["母病及子","相乘","子病及母","相侮","制化"],"a":2,"e":"心属火、肝属木，木生火，心为肝之子。心病传肝是子脏之病累及母脏，故属子病及母，其传变较母病及子为重。"},{"q":"春季多风病，夏季多暑病，秋季多燥病，说明六淫致病具有何种特性","o":["外感性","季节性","地域性","相兼性","转化性"],"a":1,"e":"六淫致病与时令气候相应，春多风病、夏多暑病、长夏多湿病、秋多燥病、冬多寒病，体现季节性。"},{"q":"关于“火热内生”的形成，说法错误的是","o":["阳气过盛可化火","邪郁可化火","五志过极可化火","阴虚可致火旺","阴盛可致阴火"],"a":4,"e":"火热内生可因阳气过盛、邪郁化火、五志过极及阴虚火旺。阴盛则寒，其病机为阴寒内盛或格阳，不能化火。"},{"q":"《素问·八正神明论》说：“月生无泻，月满无补，月郭空无治，是谓得时而调之。”此段文字体现的思维方式是","o":["整体宏观","辨证唯物","恒动变化","天人合一","动静相召"],"a":3,"e":"月之盈亏影响人体气血虚实，故针刺补泻须待月生、月满、月郭空之时而调，体现人与天地相应的天人合一思想。"},{"q":"《素问·气交变大论》说：“善言天者，必应于人；善言古者，必验于今；善言气者，必彰于物；善言应者，同天地之化；善言化言变者，通神明之理。”此段文字体现的思维方式是","o":["形象思维","意象思维","应象思维","整体宏观","恒动变化"],"a":3,"e":"言天必应于人、言古必验于今、言气必彰于物，主张从天地人物气的整体联系把握规律，属整体宏观的思维方式。"},{"q":"华佗创立的健身方法是","o":["八段锦","五禽戏","太极拳","舞蹈","按摩"],"a":1,"e":"华佗模仿虎、鹿、熊、猿、鸟五种禽兽动作创立五禽戏，为导引健身、动摇肢体的传统健身法。"},{"q":"“见微知著，弥患于未萌，是为上工”之语出自","o":["《医学源流论·防微论》","《医学心悟》","《金匮要略》","《素问·玉机真脏论》","《素问·上古天真论》"],"a":1,"e":"此语出自程国彭《医学心悟》，强调察微知著、防患于未萌，与治未病之未病先防一脉相承。"},{"q":"以阴阳失调来阐释真寒假热或真热假寒，其病机是","o":["阴阳偏盛","阳偏衰","阴阳格拒","阴阳互损","阴阳离决"],"a":2,"e":"真寒假热为阴寒内盛、格阳于外，真热假寒为热邪深伏、格阴于外，二者病机均属阴阳格拒。"},{"q":"中医学整体观念形成的哲学基础是","o":["天人一体观","气一元论","形神一体观","五脏一体观","阴阳对立统一"],"a":1,"e":"气一元论以气为宇宙万物本原，人与天地万物同源于气，为整体观念中天人一体观提供了哲学基础。"},{"q":"五脏中，具有“以升为健”特点的脏是","o":["心","肝","脾","肾","肺"],"a":2,"e":"脾主升清，上输水谷精微以养心肺头目，并升举内脏，其气以升为顺、以降为逆，故称以升为健。"},{"q":"根据五行学说，按相克规律确定的治法是","o":["益火补土法","培土生金法","佐金平木法","金水相生法","滋水涵木法"],"a":2,"e":"按相克规律所立治法为抑强扶弱。佐金平木即清肃肺金以抑制肝木之亢，用于肝火犯肺之证。"},{"q":"能调节十二经脉气血，主要与奇恒之腑有较密切关系者为","o":["浮络","十二经筋","十五别络","奇经八脉","十二经别"],"a":3,"e":"奇经八脉不直接隶属脏腑、无表里配属，能蓄溢调节十二经脉气血，且与脑、髓、女子胞等奇恒之腑关系密切。"},{"q":"关于既病防变，下列叙述错误的是","o":["早期诊断","早期治疗","防止疾病发展","防止病邪侵害","防止疾病传变"],"a":3,"e":"既病防变包括早期诊断、早期治疗、防止疾病发展与传变。防止病邪侵害属未病先防，不属既病防变。"},{"q":"下列除哪项外均可归属于五行之“水”","o":["五色之黑","六腑之膀胱","五脏之肾","五体之筋","五味之咸"],"a":3,"e":"五行之水配五色之黑、五味之咸、五脏之肾、六腑之膀胱、五体之骨。筋属木，为肝所主，故不属水。"},{"q":"下列属于治法的是","o":["正治","扶正","祛邪","泻下","调整阴阳"],"a":3,"e":"治法指具体治疗方法，如汗、吐、下、和、温、清、补、消八法。正治、扶正、祛邪、调整阴阳均属治则层次。"},{"q":"患者高热、面红、咳喘、脉数有力。对于这种实热证可以依据阴阳的何种关系进行治疗","o":["阴阳互根互用","阴阳转化","阴阳对立","阴阳交感","阴阳平衡"],"a":2,"e":"实热证治以热者寒之，用寒凉药制约亢盛之阳热，使阴阳复归平衡，正是阴阳对立制约关系的运用。"},{"q":"喉为何脏之门户","o":["脾","肺","肾","心","肝"],"a":1,"e":"肺主气、司呼吸，喉为呼吸之气出入的通道与发音之器，故称喉为肺之门户，肺病常见喉痛声嘶。"},{"q":"提出“灵机记性在脑而不在心”的医家是","o":["李时珍","王清任","汪昂","张景岳","张仲景"],"a":1,"e":"王清任著《医林改错》，基于尸体解剖实践提出灵机记性在脑不在心，纠正了心主神明之说的偏颇。"},{"q":"中医学整体观念的内涵是","o":["人体是一个有机的整体","自然界是一个统一的整体","昼夜晨昏对人体的影响","人是一个有机整体，人和自然、社会环境的统一性","脏腑肢体官窍联结成一个整体"],"a":3,"e":"整体观念包括人体自身是一个有机整体，以及人与自然、社会环境具有统一性两方面，后者又称天人一体。"},{"q":"排精不畅，伴精道疼痛，睾丸胀痛，小腹胀满，其最直接的病机描述是","o":["精亏","精少","精热","精瘀","精凝"],"a":3,"e":"排精不畅、精道疼痛、睾丸胀痛、小腹胀满，为精液瘀阻精道、排泄受阻之象，病机属精瘀。"},{"q":"感受寒邪而致“中寒”的机理是","o":["寒邪伤于肌表","寒邪入侵经脉","寒邪自内而生","寒邪直中脏腑","寒邪侵及血分"],"a":3,"e":"中寒指寒邪直中脏腑，损伤脏腑阳气，骤见脘腹冷痛、呕吐泄泻、脉沉紧，与外寒伤表之证不同。"},{"q":"阴阳转化的内在根据是","o":["交合感应","对立制约","消长平衡","互根互用","无限可分"],"a":3,"e":"阴阳转化以互根互用为内在根据，双方互藏互生、各含对立之机，故盛极可衰、物极必反，转化方能发生。"},{"q":"主运化的脏是","o":["心","脾","肺","肝","肾"],"a":1,"e":"脾主运化水谷精微，化生气血津液，为气血生化之源、后天之本；脾运健则纳化正常，失健则腹胀便溏。"},{"q":"下列属于奇恒之腑的是","o":["胃","小肠","三焦","胆","膀胱"],"a":3,"e":"奇恒之腑为脑、髓、骨、脉、胆、女子胞。六腑之中唯胆形态似腑而功能似脏，故属奇恒之腑。"},{"q":"根据五行学说，脾病传肾的机理是","o":["相克","相侮","母病及子","相乘","子病犯母"],"a":3,"e":"脾属土、肾属水，土克水。脾病传肾为土气偏盛而过度克制肾水，属相乘；肾水反侮脾土者才属相侮。"},{"q":"下列哪项属于寒邪的性质","o":["轻扬开泄","重浊","凝滞","黏滞","干涩"],"a":2,"e":"寒性凝滞，使气血津液凝结、经脉收引，故寒邪致病以疼痛为主。轻扬开泄属风，重浊黏滞属湿，干涩属燥。"},{"q":"在父母生殖之精的基础上及胎孕期间内外环境的影响下，子代所形成的相对稳定个体固有特性指的是","o":["禀赋","后天因素","体质","环境因素","地理因素"],"a":0,"e":"禀赋指子代在父母生殖之精基础上，受胎孕期间内外环境影响而形成的相对稳定的个体固有特性。"},{"q":"胆汁的分泌与排泄，主要取决于","o":["肝主疏泄的功能","胆贮藏胆汁的功能","胆排泄胆汁的功能","脾主运化的功能","小肠泌别清浊的功能"],"a":0,"e":"肝主疏泄，能分泌胆汁并调节其排泄，助脾胃运化。肝失疏泄则胆汁分泌排泄失常，见口苦、黄疸、胁痛。"},{"q":"脏与脏之间主要是先后天互相资生关系的是","o":["心与肾","心与脾","心与肺","脾与肾","心与肝"],"a":3,"e":"脾为后天之本、气血生化之源，肾为先天之本、藏精主水。脾阳赖肾阳温煦，肾精赖脾运化充养，故为先后天互资。"},{"q":"下列哪项是瘀血致病的特征","o":["腹痛，泻后痛减","形成肿胀，时聚时减","胁痛且胀，随情绪波动而增减","胸闷咳嗽，不能平卧","疼痛如针刺，位置不移"],"a":4,"e":"瘀血致病以痛如针刺、痛处固定不移、拒按、夜间加重为特点，兼见舌紫暗、有瘀点瘀斑、脉涩。"},{"q":"患者急性发病，壮热，烦渴，面红目赤，尿黄，便干，舌苔黄。其病机是","o":["阳盛格阴","阳损及阴","阳热偏盛","阳盛伤阴","阴盛格阳"],"a":2,"e":"壮热、面红目赤、烦渴、尿黄便干、苔黄，为阳热亢盛之实热证，病机属阳偏盛，治宜清热泻火。"},{"q":"形体消瘦，便溏，舌红少苔，多见于","o":["心阴虚","肝阴虚","脾阴虚","肺阴虚","肾阴虚"],"a":2,"e":"大便溏泄示病位在脾，形体消瘦、舌红少苔为阴液亏虚之象，口中不燥、无咳逆之肺征，合参即为脾阴虚。"},{"q":"用下列哪种药可以预防肝炎","o":["贯众","板蓝根","大青叶","茵陈","马齿苋"],"a":3,"e":"茵陈苦泄下降，善清利肝胆湿热、利胆退黄，为预防肝炎尤其是黄疸型肝炎的常用药物，可单味煎服。"},{"q":"“春夏养阳，秋冬养阴”是遵循养生基本原则中的","o":["延缓衰老","顺应自然","预防疾病","形神兼养","动静结合"],"a":1,"e":"春夏阳气生长，宜养阳以从其生；秋冬阴气收藏，宜养阴以从其藏。此随四时阴阳消长而调养，属顺应自然。"},{"q":"与思维的产生关系最为密切的是","o":["肝","心","脾","肺","肾"],"a":1,"e":"心藏神，为五脏六腑之大主，人的精神、意识、思维活动皆由心主宰，故与思维关系最密切者为心。"},{"q":"注于脉中，化生血液的是","o":["元气","宗气","营气","心气","卫气"],"a":2,"e":"营气由水谷精微中的精华部分化生，行于脉中，化生血液并营养全身，故有营血同源之说。"},{"q":"五行调节事物整体动态平衡的机制是","o":["制化","我生","克我","我克","生我"],"a":0,"e":"五行制化为生中有克、克中有生，通过生克制约使整体恢复动态平衡，即亢则害、承乃制。"},{"q":"情志刺激可引起下列哪个病证","o":["伤寒","中暑","虫证","胸痹","食积"],"a":3,"e":"情志刺激致气机郁滞、心脉瘀阻，可发为胸痹，见胸闷心痛、心悸气短，常因情绪波动而诱发加重。"},{"q":"以下均属于肾的系统，错误的是","o":["二阴","女子胞","发","膀胱","耳"],"a":1,"e":"肾系统包括耳、二阴、发、骨、膀胱及唾、恐等。女子胞为奇恒之腑，主月经胎孕，不属肾系统所辖。"},{"q":"“乙癸同源”是指哪两脏的关系","o":["心与肾","肺与肾","脾与肾","肝与肾","肝与肺"],"a":3,"e":"天干配五行，乙属木应肝、癸属水应肾。肝肾同居下焦，精血互生、同源互化，故称乙癸同源。"},{"q":"胆经的名称是","o":["足少阳胆经","足阳明胆经","足太阳胆经","足少阴胆经","足太阴胆经"],"a":0,"e":"足少阳胆经起于目外眦，循头角、耳后、胁肋下行至足第四趾，属胆络肝，与足厥阴肝经相表里。"},{"q":"胃的生理特性是","o":["喜润恶燥主降","喜燥恶湿主降","喜润恶燥主升","喜燥恶湿主","主宣降"],"a":0,"e":"胃为阳腑，喜润恶燥，主受纳腐熟水谷，其气以降为和，故胃的生理特性是喜润恶燥主降。"},{"q":"下列选项中不属于经络学说在诊断中的具体运用的是","o":["望小儿指纹","耳壳视诊","腧穴诊断","分经诊断","望体态"],"a":4,"e":"经络学说用于诊断的有望小儿指纹、耳壳视诊、腧穴诊断与分经诊断。望体态属一般望诊内容，不属经络诊断。"},{"q":"与血液生成关系最密切的脏腑是","o":["心","肺","肝","脾","肾"],"a":3,"e":"脾运化水谷精微，化生营气与津液，再经心肺作用化赤为血，为气血生化之源，故与血液生成最密切。"},{"q":"根据五行学说，调节事物整体动态平衡的是","o":["相生","相克","相乘","相侮","制化"],"a":4,"e":"五行制化以相生相克为基础，生中有克、克中有生，使亢盛得制、虚衰得助，从而维持整体的动态平衡。"},{"q":"人身之阳气在正常情况下有养神柔筋、温煦脏腑的作用，为生理之火，中医还称之为","o":["君火","相火","少火","壮火","阴火"],"a":2,"e":"少火为生理之火，能温煦脏腑、养神柔筋；壮火为病理之火，耗气伤津，故有少火生气、壮火食气之说。"},{"q":"基于推演络绎，以下除了哪项外，均属于火","o":["小肠","筋","脉","面","舌"],"a":1,"e":"五行之火配小肠、脉、面、舌、苦、喜、汗、心，皆由心火推演而来。筋属木，为肝所主，故不属火。"},{"q":"脾经的终端与何经的起点相接","o":["肺经","胃经","肝经","心经","肾经"],"a":3,"e":"足太阴脾经起于足大趾，上行入腹属脾络胃，其支者上膈注心中，与手少阴心经相接，构成流注循环。"},{"q":"阴偏盛所形成的病理变化是","o":["实热","实寒","虚热","虚寒","真寒假热"],"a":1,"e":"阴偏盛则寒，阴寒内盛而阳气未虚，邪正交争剧烈，形成实寒证，见形寒肢冷、腹痛拒按、脉沉实。"},{"q":"心神的物质基础是","o":["血","气","精","津","营气"],"a":0,"e":"心主血脉而藏神，血为神志活动的物质基础。心血充盈则神志清晰、思维敏捷，故心神的物质基础是血。"},{"q":"“膏粱之变，足生大丁”是指","o":["饮食过饱","饮食过饥","饮食不洁","进食大量高粱","嗜食辛辣"],"a":0,"e":"膏粱指肥甘厚味。过食肥甘，蕴生湿热火毒，易生疔疮，即膏粱之变、足生大丁，属饮食过饱所伤。"},{"q":"下列各项中的医学思想错误的是","o":["伤寒早治重太阳病阶段","温病早治重在卫分证阶段","先安未受邪之地属于预见性治疗","早期治疗的前提是早期的正确诊断","疾病做到早治就一定不会发生传变"],"a":4,"e":"早期诊治可阻断病邪传变，但不能绝对保证不再传变。此说把或然当必然，过于绝对，故为错误之论。"},{"q":"长期饮食过饥，气血生化减少，正气不足，容易导致","o":["外邪入侵","湿热内生","痰湿内停","肝气郁结","食滞胃肠"],"a":0,"e":"长期饮食过饥则水谷精微乏源，气血生化不足，正气亏虚、卫外不固，故易招致外邪入侵。"},{"q":"经络的调节平衡作用是","o":["单向的","正向的","逆向的","垂直的","良性双向的"],"a":4,"e":"经络能根据气血盛衰进行双向调节，虚则补之、实则泻之，使偏盛偏衰复归平衡，故其调节为良性双向。"},{"q":"瘀血在舌质上表现为","o":["舌质紫暗","舌质淡红","舌质淡白","舌质鲜红","舌质红绛"],"a":0,"e":"瘀血内阻、血行不畅，故舌质紫暗，或见瘀点瘀斑，舌下脉络迂曲，为瘀血辨证的重要舌象。"},{"q":"六腑的生理特点是","o":["贮藏精气","化生精气","传导精气","传化水谷","运化水液"],"a":3,"e":"六腑主受盛传化水谷、泻而不藏，以通降为顺，其生理特点为传化水谷，故六腑为病多从通降论治。"},{"q":"与内脏下垂有关的脏是","o":["脾","肺","肾","肝","心"],"a":0,"e":"脾气主升，能升清并维系内脏位置。脾气下陷则升举无力，故见内脏下垂、久泻脱肛，其责在脾。"},{"q":"膀胱的贮尿和排尿功能主要依赖于","o":["肺的通调水道","肾的气化功能","肝的疏泄","三焦决渎","脾的运化水液"],"a":1,"e":"膀胱贮尿排尿依赖肾阳温煦与肾气固摄，即肾的气化作用；气化失司则见尿频、尿少或癃闭、失禁。"},{"q":"有主水和纳气功能的脏是","o":["肝","心","脾","肺","肾"],"a":4,"e":"肾主水，主持全身水液代谢；肾主纳气，摄纳肺吸入之清气。二功能同属肾，故具此二者之脏为肾。"},{"q":"开创了中医“预防为主”思想的先河，首次明确提出“治未病”一词典籍是","o":["《黄帝内经》","《医学源流论》","《医学启蒙》","《金匮要略》","《诸病源候论》"],"a":0,"e":"《素问·四气调神大论》提出圣人不治已病治未病，首开中医预防为主思想之先河，为治未病的最早出处。"},{"q":"下列哪项是火邪、燥邪、暑邪共同的致病特点","o":["耗气","上炎","伤津","动血","生风"],"a":2,"e":"火、燥、暑三邪皆易伤津液，故口干、尿少、舌燥为其共有致病表现；耗气主要见于暑与火，动血生风主要责之火。"},{"q":"最易导致病位游移不定的外邪是","o":["风邪","暑邪","湿邪","火邪","寒邪"],"a":0,"e":"风性善行而数变，致病部位游移不定、症状变幻迅速，故最易导致病位游走的外邪为风邪。"},{"q":"下列各项，属于消法范畴以外的是","o":["消食导滞","行气活血","化痰利水","驱虫","健脾"],"a":4,"e":"消法指消散有形之邪，含消食导滞、行气活血、化痰利水、驱虫等。健脾属补法范畴，不属消法。"},{"q":"《饮膳正要》一书中说：“春气温，宜食（）以凉之。”","o":["菽","麻","麦","黍","苦"],"a":2,"e":"《饮膳正要》主张四时食养各有宜忌，春气温则宜食麦以凉之，夏气热宜食菽，秋气燥宜食麻，冬气寒宜食黍。"},{"q":"水湿痰饮多从何脏论治","o":["心、肾","肺、脾、肾","心、脾、肝、肾","肺、肝、脾、肾","心、肝、脾、肺、肾"],"a":1,"e":"水液代谢由肺通调水道、脾运化转输、肾蒸腾气化共同完成，故水湿痰饮为病多从肺、脾、肾三脏论治。"},{"q":"阴阳的相互转化是","o":["绝对的","有条件的","必然的","偶然的","量变的"],"a":1,"e":"阴阳转化须在一定条件下才发生，条件是转化的内在依据，故其转化是有条件的，而非无条件的必然。"},{"q":"由水谷精微中的精华部分所化生的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":2,"e":"营气由水谷精微中精华部分化生，行于脉中，化生血液并营养周身，与卫气一内一外、营卫相偕。"},{"q":"与津液代谢关系最密切的脏腑有","o":["肝、脾、肾","脾、肺、肾","心、肝、脾","脾、肺、心","肝、肺、肾"],"a":1,"e":"津液代谢依赖脾之运化、肺之通调、肾之主水及三焦气化，其中脾肺肾三脏关系最为密切。"},{"q":"最早提出“七情和合”药物配伍理论的是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《本草纲目》"],"a":3,"e":"《神农本草经》序例载药有七情和合，提出单行、相须、相使、相畏、相杀、相恶、相反，为最早的配伍理论。"},{"q":"容易导致脾气耗损、心血不足的病因是","o":["风寒","温燥","饮食过饱","大怒","思虑过度"],"a":4,"e":"思则气结，思虑过度伤脾，脾失健运则纳少、气血生化不足，日久心血亏虚，见心悸、失眠、健忘。"},{"q":"下列属于五行之“火”，错误的是","o":["心","笑","汗","苦","魄"],"a":4,"e":"五行之火配心、笑、汗、苦、喜、脉、舌，皆属火之系统。魄为肺所藏，属金，故不属火。"},{"q":"中医学认为，构成人体这个有机整体的中心是","o":["五脏","六腑","脑","命门","经络系统"],"a":0,"e":"五脏为人体生命活动的中心，通过经络联系六腑、形体、官窍，构成以五脏为核心的有机整体。"},{"q":"六淫中易侵犯人体上部和肌腠的外邪是","o":["风邪","寒邪","湿邪","燥邪","暑邪"],"a":0,"e":"风为阳邪，其性轻扬开泄，易袭阳位，故多侵犯人体上部、肌表与肌腠，见头痛、汗出、恶风。"},{"q":"下列名称错误的是","o":["手太阴肺经","足阳明胃经","手厥阴心包经","手太阳膀胱经","足少阴肾经"],"a":3,"e":"经脉命名以手足、阴阳、脏腑三者相合，膀胱经循行于背属足太阳经，应称足太阳膀胱经；其余四经名称均与命名规范相符。"},{"q":"下列关于劳逸损伤与疾病发生关系的叙述，错误的是","o":["久视伤血","久坐伤肉","久立伤骨","久卧伤心","久行伤筋"],"a":3,"e":"五劳所伤出自《素问·宣明五气》，久卧则阳气不伸、气机弛缓，所伤在气而不在心，心伤多由思虑劳神所致。"},{"q":"中医学理论体系确立的时期为","o":["春秋战国","战国至秦汉","两晋隋唐","宋金元","明清"],"a":1,"e":"中医学理论体系形成于战国至秦汉时期，《黄帝内经》问世标志其确立，《伤寒杂病论》《神农本草经》继之充实发展。"},{"q":"金元时期，倡导“百病皆由脾胃衰而生”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":4,"e":"李东垣为补土派代表，提出内伤脾胃、百病由生，认为脾胃衰则元气不足而诸病蜂起，治重补中益气、升阳举陷。"},{"q":"由于精神情志的刺激，影响机体阴阳气血和脏腑的生理平和，造成气机郁结，气郁日久则从阳化热，对这一过程最准确的描述是","o":["邪郁化火","气郁化火","五志过极化火","内伤化火","邪盛化火"],"a":2,"e":"情志刺激致气机郁结，气郁日久则从阳化热，属五志过极化火，因其起于五志过极而非外邪侵袭。"},{"q":"临床上治疗多汗、漏汗时，可采用补气之法，其理论依据是","o":["气能行津","气能摄津","气能生津","津能载气","津能生气"],"a":1,"e":"气能摄津指气对津液有固摄统束作用，气虚则固摄无权、津液外泄而为多汗漏汗，故治以补气摄津。"},{"q":"肝主疏泄的基本生理功能是","o":["调畅情志活动","调畅全身气机","促进脾胃运化","推动血行津布","促进男女生殖"],"a":1,"e":"肝主疏泄的核心是调畅全身气机，情志活动、脾胃运化、血行津布及生殖功能皆以气机畅达为前提。"},{"q":"载有“络之别者为孙”的著作是","o":["《灵枢·经脉》","《灵枢·经别》","《灵枢·经筋》","《灵枢·经水》","《灵枢·脉度》"],"a":4,"e":"络之别者为孙出自《灵枢·脉度》，论述经脉别出之络再分细支而为孙络，络脉由大至小层层细分。"},{"q":"小肠“泌别清浊”的功能，下列哪项是错误的","o":["分为水谷精微和食物残渣","吸收水谷精微和津液","对食物残渣和废水的处理","既能传导，又吸收水液","是脾的升清和胃的降浊功能的具体体现"],"a":3,"e":"小肠泌别清浊，分清别浊并吸收水谷精微与津液，是脾升清、胃降浊的具体体现；既能传导又吸收水液者是大肠。"},{"q":"气机升降之“枢”是指","o":["肺主呼气，肾主纳气","心火下降，肾水上升","脾主升清，肺主肃降","脾气主升，胃气主降","肝主升发，肺主肃降"],"a":3,"e":"脾胃同居中焦，脾气主升、胃气主降，升降相因而为气机升降之枢，枢机通利则清升浊降。"},{"q":"认为“六气皆从火化”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素主火论，认为六气皆从火化，治病多用寒凉，为寒凉派代表，著《素问玄机原病式》。"},{"q":"“塞因塞用”不适用于下列哪种病证","o":["脾虚腹胀","血枯经闭","肾虚尿闭","气郁腹胀","阴虚便秘"],"a":3,"e":"塞因塞用以补开塞，适于因虚致塞之证，如脾虚腹胀、血枯经闭；气郁腹胀为气机壅实，当行气开郁。"},{"q":"大肠的病机特点是","o":["受纳功能失常","运化功能失常","传导功能失常","调节功能失常","腐熟功能失常"],"a":2,"e":"大肠为传导之官，主传化糟粕、主津，故其病机特点为传导功能失常，临床可见便秘或泄泻。"},{"q":"主张命门为人身之主的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":1,"e":"赵献可著《医贯》，倡命门学说，提出命门为人身之主，为五脏六腑之本、十二经之根，主一身之阳气。"},{"q":"某些远离海洋的山区，人群中易患地方性甲状腺肿，其发病因素是","o":["地域因素","气候因素","先天禀赋，体质较弱","工作环境","精神状态"],"a":0,"e":"远离海洋的山区水土缺碘，人群易患地方性甲状腺肿，属地域水土因素致病，为典型地方病。"},{"q":"小肠“泌别清浊”的功能，下列错误的是","o":["分为水谷精微和食物残渣","吸收水谷精微和津液","对食物残渣和废水的处理","排泄尿液","是脾的升清和胃的降浊功能的具体体现"],"a":3,"e":"泌别清浊由小肠完成，清者上输于脾、浊者下传大肠；尿液的生成与排泄由膀胱气化所司，非小肠之职。"},{"q":"脾在志为","o":["怒","思","喜","悲","恐"],"a":1,"e":"脾在志为思，思虑过度则伤脾，致脾气郁结、运化无力，故见纳呆腹胀、倦怠少食、形体消瘦。"},{"q":"金元四大家中“滋阴派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":3,"e":"朱丹溪倡阳常有余、阴常不足，主张滋阴降火，为滋阴派代表，著《格致余论》《丹溪心法》。"},{"q":"五脏生理特性中，“以升为健”的脏为","o":["肾","肺","脾","肝","心"],"a":2,"e":"脾主升清，以升为健，将水谷精微上输心肺头目；胃主降浊，二者升降相因，共同维系中焦气机。"},{"q":"具有“喜燥恶湿”特性的脏腑是","o":["肝","脾","胃","肾","肺"],"a":1,"e":"脾喜燥恶湿，脾运水湿而恶湿邪困阻，湿盛则脾运失健，故治脾常佐苍术、厚朴等燥湿之品。"},{"q":"脾之大络散布的部位是","o":["上肢部","下肢部","背部","胸胁部","腹部"],"a":3,"e":"脾之大络名大包，出渊腋下三寸，散布于胸胁，网罗一身之气血，为十五别络中分布最广者。"},{"q":"以下哪种疾病在气候转变的季节或寒冬易复发","o":["失眠","脏躁","哮病","某些月经不调病证","癫狂"],"a":2,"e":"哮病有宿痰伏肺之根，遇气候骤变或寒冬寒邪引动伏痰而发，故在季节转换时易于复发，缠绵难愈。"},{"q":"虚损病证表现虚候，用补益方药来治疗它，此被概括为下列中哪一项","o":["逆者正治","从者反治","实者泻之","虚者补之","塞因塞用"],"a":3,"e":"虚损病证见虚候而以补益方药治之，即虚者补之，属逆其证候而治的正治之法，为八法中之补法。"},{"q":"水不涵木是指","o":["肾阳虚不能煦肝阳","肝阴虚不能充养肾阴","肾阴虚不能滋养肝阴","肝火太旺下劫肾阴","肝阴不足导致肾阴亦虚"],"a":2,"e":"水不涵木指肾阴亏虚不能滋养肝阴，肝阴不足而肝阳偏亢，属肾肝母子相生的病理传变，治宜滋水涵木。"},{"q":"病机之名，首先见于","o":["《黄帝内经》","《伤寒论》","《金匮要略》","《难经》","《中藏经》"],"a":0,"e":"病机一词首见于《素问·至真要大论》，提出谨守病机、各司其属，为中医病机学说之滥觞。"},{"q":"属于五行之“金”，下列错误的那项是","o":["大肠","湿","西","毛","咳"],"a":1,"e":"五行金对应大肠、西方、皮毛与咳；湿由水液停聚而生，其性黏滞而类土，故属土而不属金。"},{"q":"体质偏阳的患者，不宜采用的治法是","o":["甘寒","酸寒","咸寒","清润","温补"],"a":4,"e":"体质偏阳者阳气偏亢、易化热伤阴，治宜甘寒、酸寒、咸寒及清润，温补则助热伤阴而增病。"},{"q":"五脏中，与血液运行最不密切的是","o":["心","肝","脾","肺","肾"],"a":4,"e":"血行赖心气推动、肺朝百脉、肝主疏泄与藏血、脾主统血，肾主藏精化血，直接参与运行最少。"},{"q":"“木火刑金”在五行学说中属于","o":["相乘","相侮","相生","子病及母","母病及子"],"a":1,"e":"肝火亢盛上逆灼肺，金本克木而反被木侮，故木火刑金为相侮传变，属反克之常例，与相乘不同。"},{"q":"下列属相侮的是","o":["心病及脾","脾病及肾","脾病及肝","肾病及肺","脾病及心"],"a":2,"e":"相侮为反克，土本受木克，今脾土壅盛反侮肝木，即所谓土壅木郁，故脾病及肝属相侮之变。"},{"q":"可直接伤及心神的病因是","o":["风寒","温燥","七情内伤","饮食不洁","房劳过度"],"a":2,"e":"七情内伤直伤内脏，首先影响心神而致神志失常；六淫、饮食、房劳多先伤形体，再由形及神。"},{"q":"六淫中引起筋脉拘挛、屈伸不利、腠理闭塞、气机收敛的邪气是","o":["风邪","寒邪","湿邪","暑邪","火邪"],"a":1,"e":"寒性收引凝滞，客于筋脉则拘挛屈伸不利，客于肌表则毛窍闭塞、气机收敛，故见无汗而痛。"},{"q":"奇恒之腑的生理特点是","o":["受盛水谷","传化水谷","排泄糟粕","其气象地","其气象天"],"a":4,"e":"官方答案为其气象天，但依据教材，正确答案为其气象地。《素问·五脏别论》谓脑髓骨脉胆女子胞皆藏于阴而象于地，故藏而不泻；六腑为天气所生，方其气象天。"},{"q":"五心烦热、潮热盗汗、口燥咽干可见于下列何证","o":["邪郁化火","气郁化火","五志过极化火","阴虚火旺","阴火证"],"a":3,"e":"五心烦热、潮热盗汗、口燥咽干为阴虚内热、虚火内扰之象，舌红少苔、脉细数，故属阴虚火旺。"},{"q":"下列表述中属于证的是","o":["水痘","麻疹","风寒感冒","头痛","恶寒"],"a":2,"e":"证是对疾病某一阶段病机的概括，风寒感冒含病因、病位与病性；水痘麻疹为病名，头痛恶寒为症状。"},{"q":"根据五行学说，下列符合相生关系的是","o":["木生金","火生木","土生水","水生火","金生水"],"a":4,"e":"五行相生次序为木生火、火生土、土生金、金生水、水生木，故金生水成立，余四者皆属逆次。"},{"q":"与语言、声音、呼吸关系最为密切的是","o":["元气","肺气","宗气","中气","心气"],"a":2,"e":"宗气积于胸中，走息道以司呼吸、发声音，贯心脉以行气血，故与语言、声音、呼吸关系最密切。"},{"q":"中医学关于“证”的高度概括是","o":["临床症状","疾病原因","病机本质","疾病部位","疾病性质"],"a":2,"e":"证是对疾病过程中某一阶段病机本质的概括，反映病位、病性与病势，症状与病名均不足以当之。"},{"q":"下利治法符合“实则泻其子”治则思想的是","o":["肝火旺泻心火","脾火旺泻胆火","肝火旺泻脾","肝火旺泻肺","肺热泻大肠"],"a":0,"e":"实则泻其子，肝木之子为心火，故肝火旺者泻心火，使邪有出路而肝火自平，属五行相生治则。"},{"q":"肾在液为","o":["唾","泪","汗","涕","涎"],"a":0,"e":"肾在液为唾，唾为肾精所化，出于舌下，咽之可回滋肾精，故肾精充足则唾液分泌有常，咽唾可以养肾。"},{"q":"补气药与利水药配合治疗水肿病，依据的理论是","o":["气能生津","气能行津","气能摄津","津能载气","津能生气"],"a":1,"e":"气能行津，气虚推动无力则津液输布不利、停聚而为水肿，故补气与利水同用以消肿，即气行则水行。"},{"q":"《素问·五藏生成篇》说：“多食咸，则（ ）”","o":["脉凝泣而变色","皮槁而毛拔","筋急而爪枯","肉胝皱而唇揭","骨痛而发落"],"a":0,"e":"多食咸则咸味入肾，水盛克火，致血脉凝涩、颜色改变，故云脉凝泣而变色，为五味偏嗜所伤。"},{"q":"脾主升清的内涵是","o":["脾之阳气上升心肺","脾气以升为健","脾气将水谷精微上输头面心肺","脾气输布水液于全身","脾气上升防止下出血"],"a":2,"e":"脾主升清，指脾气将水谷精微上输头面心肺，化生气血以濡养周身，并维系内脏位置不致下垂。"},{"q":"下列选项中，属于瘀血导致出血特点的是","o":["出血多见于身体的下部","血色淡，质清稀","伴有气虚症状","出血伴有刺痛拒按","出血时间较长"],"a":3,"e":"瘀血内阻，血不循经而出血，血色紫暗有块，且瘀阻不通故伴刺痛拒按，与气虚出血不同。"},{"q":"肺吸入自然界的清气主要依靠","o":["肺气宣发","肺气肃降","肺朝百脉","肺治理调节血液运行","肺治理调节津液代谢"],"a":1,"e":"肺司呼吸，吸入自然界清气赖肺气肃降下行，纳于肾而敷布全身，故主要依靠肃降作用而非宣发。"},{"q":"具有受盛和传化水谷的是","o":["五脏","六腑","脏腑","奇恒之腑","以上均非"],"a":1,"e":"六腑主受盛和传化水谷，泻而不藏、实而不满，与五脏藏精气而不泻、满而不实相对而言。"},{"q":"与肾的功能有关的是","o":["主神志","开窍于口","其华在发","在时为春","在体合脉"],"a":2,"e":"肾藏精，精能化血，发为血之余，肾精充足则毛发茂密润泽，故其华在发，精亏则发脱早白。"},{"q":"厥阴经病变，多选择的引经药物是","o":["藁本","葛根","川芎","柴胡","独活"],"a":2,"e":"川芎辛温上行入血分，为厥阴经引经药，能引诸药直达厥阴肝经病所，为血中之气药、头痛要药。"},{"q":"气的运行受阻而不畅通，称为","o":["气机失调","气滞","气机不畅","气逆","气闭"],"a":2,"e":"气机不畅指气的运行受阻而不畅通，程度较轻；气滞则为气机郁滞不通，气逆、气闭病势更甚。"},{"q":"胆汁的正常分泌和排泄主要依赖的是","o":["肝主疏泄","脾主运化","胃主通降","肺主宣降","肾的气化"],"a":0,"e":"肝主疏泄，能疏利胆汁并促其下泄肠道以助消化，故胆汁的分泌与排泄主要依赖肝的疏泄。"},{"q":"确立辨证论治理论体系的典籍是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《医宗金鉴》"],"a":2,"e":"《伤寒杂病论》以六经辨外感、以脏腑辨杂病，理法方药俱全，确立辨证论治理论体系，为临床医学之基。"},{"q":"创立六经辨证方法的医家是","o":["朱丹溪","张机","张元素","李杲","叶天士"],"a":1,"e":"张机即张仲景，著《伤寒杂病论》，以六经辨外感病而创辨证论治，被后世尊为医圣、方书之祖。"},{"q":"《灵枢•五癃津液别》所说“天寒衣薄则为溺与气，天热衣厚则为汗”，说明了","o":["人体自身的完整性","自然环境对人体生理的影响","社会环境对人体生理的影响","自然环境对人体病理的影响","社会环境对人体病理的影响"],"a":1,"e":"天寒衣薄则多尿与气、天热衣厚则多汗，说明气候环境直接影响津液代谢等生理活动，为天人相应之征。"},{"q":"观察心主血脉的功能是否正常时，与哪一项关系较小","o":["面色","舌色","脉象","心胸部的感觉","爪色"],"a":4,"e":"心主血脉，其华在面、开窍于舌，故察面色、舌色、脉象与心胸感觉可辨其功能；爪为筋之余，属肝。"},{"q":"临床上利小便实大便的理论依据为","o":["小肠的泌别清浊功能","脾的运化功能","肺的通调水道功能","小肠主液功能","小肠的主受盛功能"],"a":0,"e":"小肠泌别清浊，清者上输于脾、浊者下传大肠，利小便则水从前阴而去，大便因而自实，即利小便实大便。"},{"q":"根据五行学说，心病及肺属于","o":["母病及子","子病及母","相乘传变","相侮传变","母子同病"],"a":2,"e":"心属火、肺属金，火克金，心病及肺为心火太过而乘肺金，属相乘传变，为相乘之常例而非相侮。"},{"q":"膀胱生理功能的实现依赖以下哪项与膀胱之气的协调","o":["心气","肾气","肝气","肺气","脾气"],"a":1,"e":"膀胱贮尿排尿，其开合赖肾气的蒸腾气化与固摄，肾气不足则膀胱开合失司，见尿频或癃闭。"},{"q":"“正气存内，邪不可干”，主要是指","o":["邪气是发病的重要条件","邪气伤人，正气必然受损","正气充足，与邪相争，驱邪外出","正气旺盛，邪气难以入侵","正气虚弱，邪气不足"],"a":3,"e":"正气存内指正气充盛、抗邪有力，邪气难以入侵，强调正气在发病中居于主导地位，即正能御邪。"},{"q":"易患咳嗽、腹泻、食积等证的是","o":["老人","小儿","男性","女性","更年期妇女"],"a":1,"e":"小儿脏腑娇嫩、形气未充，肺脾常不足，故易患咳嗽、腹泻、食积等证，调护尤当谨慎小心。"},{"q":"气机升降之“枢”是指哪一种升降关系","o":["肺主呼气，肾主纳气","肝主升，肺主降","脾主升，胃主降","心火下降，肾水上承","脾之主升，肺之主降"],"a":2,"e":"脾主升清、胃主降浊，同居中焦而升降相因，为气机升降之枢，枢机不利则清浊相干、升降失序。"},{"q":"真虚假实证的治疗原则应是","o":["单独祛邪","单独扶正","先扶正后祛邪","扶正兼祛邪","祛邪扶正并重"],"a":1,"e":"真虚假实本质为正气虚衰，治当单独扶正，正气回复则假实之象自消，不可误用攻伐伤正。"},{"q":"心气推动和调控血液在脉道中运行的功能概括为","o":["心生血","心主血脉","心主藏神","心为生之本","心主通明"],"a":1,"e":"心气推动血液在脉道中运行，使脉道通利、血运不息，概括为心主血脉，为心之首要功能。"},{"q":"只有外感而无内生的邪气是","o":["风邪","寒邪","湿邪","暑邪","燥邪"],"a":3,"e":"暑为夏季火热之气所化，独见于夏季而只有外感，其余五邪皆有内外之分，故暑无内生之说。"},{"q":"下列病因中，最有可能导致气脱的是","o":["伤寒","失血","饱食","痰饮","疠气"],"a":1,"e":"血为气之母，血能载气，大量失血则气无所附而随血外脱，故失血最易致气脱之证，治当急固其气。"},{"q":"下列哪种说法与三焦有关","o":["太仓","五脏之本","中精之腑","孤府","中正之官"],"a":3,"e":"三焦为六腑之一，主持诸气、通调水道，无表里配偶，故称孤府，号决渎之官，为水液运行之通道。"},{"q":"金元四大家中，倡导疾病多与脾胃内伤有关的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":4,"e":"李东垣为补土派代表，强调脾胃内伤、元气不足则百病由生，治重补中益气、升阳举陷，方如补中益气汤。"},{"q":"大肠为","o":["元神之府","玄府","血府","孤府","传导之府"],"a":4,"e":"大肠为六腑之一，主传化糟粕、主津，泻而不藏，故称之为传导之府，与肺相表里而共司气机。"},{"q":"五行学说中“土”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":4,"e":"土爰稼穑，指土有播种与收获、生化万物的特性；曲直属木、炎上属火、从革属金、润下属水。"},{"q":"中医学象思维的特征是","o":["形象思维","意象思维","应象思维","抽象思维","逻辑思维"],"a":1,"e":"中医学象思维以意象思维为特征，取象比类，由外在之象推求脏腑生理病理，为其特有思维方式。"},{"q":"六淫中易袭阳位，具有轻扬开泄特性的外邪是","o":["风邪","寒邪","湿邪","暑邪","火邪"],"a":0,"e":"风为阳邪，其性轻扬开泄，易袭阳位，故伤人多在头面肌表等上部，症见汗出恶风、鼻塞咽痒。"},{"q":"气机升降出入的枢纽是","o":["肝、肺","肺、肾","脾、胃","肝、胆","心、肾"],"a":2,"e":"脾胃同居中焦，脾升胃降，为一身气机升降出入之枢纽，枢机通利则脏腑之气升降有序而不乱。"},{"q":"中医认识发病原理，主要从以下哪个角度来认识","o":["正邪相搏","阴阳失调","饮食失调","气血失常","脏腑功能失调"],"a":0,"e":"发病取决于正气与邪气双方力量对比，正不胜邪则发病，故中医从正邪相搏认识发病原理。"},{"q":"关于湿浊内生的论述错误的是","o":["与肺、脾、肾等脏腑调节水液代谢功能失调有关","与脾的关系最为密切","脾肾阳虚会导致湿浊内生","临床可见头重如裹、肢体重浊等表现","不会引起痉病"],"a":4,"e":"湿浊内生郁久可化热，湿热浸淫筋脉或蒙蔽清窍可致痉病，故不会引起痉病之说有误，当予纠正。"},{"q":"中医学认为人类寿命的自然限度是","o":["80岁","90岁","100岁","110岁","120岁"],"a":4,"e":"《素问·上古天真论》言尽终其天年、度百岁乃去，故人类自然寿命限度约为120岁，称为天年。"},{"q":"天癸的产生主要取决于","o":["肾中精气的充盈","脾气的健运","肾阳的蒸腾气化","肝血的充足","肾阴的濡润滋养"],"a":0,"e":"天癸是肾精充盛到一定阶段所化生的精微物质，能促生殖功能成熟，故取决于肾中精气充盈。"},{"q":"下列各项，属阳的是","o":["地","水","静","气","形"],"a":3,"e":"阳主动、主无形，气无形而主动，故属阳；地、水、静、形皆主静而有形，故属阴，此阴阳之定性。"},{"q":"患者，男，56岁。因情急恼怒而突发头痛而胀，继则昏厥仆倒，呕血，不省人事，肢体强痉，舌红苔黄，脉弦。其病机是","o":["气郁","气逆","气脱","气陷","气结"],"a":1,"e":"情志恼怒致肝气上逆，血随气升，蒙蔽清窍，故见头痛昏厥、呕血，其病机为气逆而非气郁。"},{"q":"与精神意识思维活动关系最密切的是","o":["心主血脉的生理功能","肝主疏泄的生理功能","脾主运化的生理功能","肺主治节的生理功能","肾主藏精的生理功能"],"a":0,"e":"心主血脉，血液是神志活动的物质基础，心气充沛则神明得养，故与精神思维活动最密切。"},{"q":"相为表里的手经交接的部位是","o":["腹","足","胸","头","手"],"a":4,"e":"十二经脉中相为表里的阴阳两经在四肢末端交接，手经表里相接于手，足经表里相接于足。"},{"q":"《灵枢·营卫生会》谓年轻人“昼精夜瞑”的原因，错误的是","o":["营卫调和","气血充盛","脾胃健运","肌肉滑利","气道通畅"],"a":2,"e":"原文谓壮者气血盛、肌肉滑、气道通、营卫之行不失其常，故昼精夜瞑，并未言及脾胃健运。"},{"q":"《针灸甲乙经》的作者是","o":["张仲景","王叔和","皇甫谧","孙思邈","陈无择"],"a":2,"e":"《针灸甲乙经》为西晋皇甫谧所撰，汇集针经与明堂孔穴，为现存最早的针灸学专著，后世奉为圭臬。"},{"q":"循行分布特点可用“离、合、出、入”加以概括的是","o":["正经","奇经","十五别络","十二皮部","十二经别"],"a":4,"e":"十二经别从十二正经别出，循行有离、合、出、入的特点，深入体腔后复合于正经，以加强表里联系。"},{"q":"与肺相表里的是","o":["大肠","小肠","胃","三焦","胆"],"a":0,"e":"肺与大肠通过经脉相互络属构成表里关系，手太阴肺经属肺络大肠，手阳明大肠经属大肠络肺。"},{"q":"下列各项，适合用温法的是","o":["素体阴虚","素体血虚","孕妇","虚寒证","神昏"],"a":3,"e":"温法以温热药温补阳气、散寒通脉，适用于虚寒证；阴虚、血虚及孕妇用之易伤阴动血，当属禁忌。"},{"q":"肝主藏","o":["魂","神","魄","志","意"],"a":0,"e":"肝藏魂，魂为随神往来的精神活动，肝血充足则魂有所舍，故寐安而梦少，虚则惊骇多梦。"},{"q":"中医养生学认为探索衰老机制的中心环节是","o":["肾中精气的盛衰","心肺的功能状态","脾胃运化功能的强弱","肝肾精血互化的状态","肾中精气的盛衰和脾的功能状态"],"a":4,"e":"中医养生学以肾中精气盛衰为衰老之根本，以脾的运化功能为后天保证，二者共为衰老机制的中心环节。"},{"q":"“中焦如沤”是描绘","o":["胃的受纳功能","脾的散精功能","小肠泌别清浊功能","脾胃、肝胆等脏腑的消化饮食物的生理过程","心、肺输布气血的作用"],"a":3,"e":"中焦如沤，形容脾胃肝胆等脏腑腐熟水谷、泌糟粕蒸津液以化生气血的生理过程，如沤渍之物。"},{"q":"全身的气机主要靠哪两脏调节","o":["心与肝","心与肺","肝与脾","肝与肺","肝与肾"],"a":3,"e":"肝主升发、肺主肃降，一升一降相反相成，共同调节全身气机的升降平衡，故为气机调节之主。"},{"q":"“脾为气血生化之源”主要的理论依据是","o":["脾主升","脾主统血","朝百脉","脾恶湿","脾主运化"],"a":4,"e":"脾主运化水谷精微，化生营卫气血以充养全身，故称脾为气血生化之源、后天之本，为生血之根。"},{"q":"脾为气血生化之源的理论依据是","o":["气能生血","人以水谷为本","脾主升清","脾能运化水谷精微","脾胃为后天之本"],"a":3,"e":"脾能运化水谷精微，水谷精微是化生气血的物质基础，故脾为气血生化之源，其要在运化之力。"},{"q":"在五行学说中，五气中的“风”归属于","o":["木","火","土","金","水"],"a":0,"e":"五气中风善动不居、升发舒展，与木之曲直生长之性相合，故风归属于木，为木之风气所在。"},{"q":"治疗阴虚证时，在滋阴剂中适当佐用扶阳药，使“阴得阳升而泉源不竭”，这可概括为","o":["阴阳并补","阴中求阳","阳中求阴","扶阳抑阴","阴病治阳"],"a":2,"e":"滋阴剂中佐用扶阳药，取阳生阴长之义，使阴得阳升而泉源不竭，属阳中求阴之法，与阴中求阳相对。"},{"q":"中焦的功能实际是指","o":["脾主运化的功能","胃的受纳功能","脾、胃受纳腐熟水谷，化生气血的功能","化生血液","输布水谷精微"],"a":2,"e":"中焦指脾胃，主受纳腐熟水谷、化生精微气血，故其功能实为脾胃消化转输之功，非独指一脏。"},{"q":"瘀血所致疼痛的特点是","o":["胀痛","窜痛","灼痛","刺痛","冷痛"],"a":3,"e":"瘀血阻滞、气血不通，不通则痛，故其痛如针刺，痛处固定不移而拒按，入夜则疼痛尤甚。"},{"q":"《灵枢·本脏》所说“分肉解利，皮肤润柔，腠理致密”，主要取决于","o":["营卫和调","卫气和利","营气和利","宗气充盛","元气充盛"],"a":1,"e":"卫气温分肉、充皮肤、肥腠理、司开合，卫气和利则分肉解利、皮肤润柔、腠理致密，外邪难侵。"},{"q":"肺气中具有凉润、沉降作用的部分称为","o":["肺气","肺阳","肺精","肺阴","肺津"],"a":3,"e":"肺气中主凉润、沉降的部分称肺阴，主滋润肺金、肃降下行；主温煦宣发者为肺阳，二者相制相用。"},{"q":"中医学“治未病”的预防思想，最早见于","o":["《内经》","《难经》","《中藏经》","《伤寒杂病论》","《诸病源候论》"],"a":0,"e":"治未病首见于《素问·四气调神大论》，包括未病先防与既病防变，为中医预防思想之源。"},{"q":"“大法春宜吐”所体现的思想是","o":["因病制宜","因地制宜","因人制宜","因时制宜","因证制宜"],"a":3,"e":"春季阳气升发、病邪在表在上，故宜用吐法因势利导，体现因时制宜的治则，此即大法春宜吐。"},{"q":"脾虚所致的出血，可以通过健脾益气的方法来治疗，其理论依据是","o":["气能生血","气能行血","气能摄血","血能养气","血能载气"],"a":2,"e":"气能摄血，脾气健旺则统摄血液循行脉中而不外溢，脾虚气弱则血不循经而出血，故治以健脾益气。"},{"q":"以下不属于广义之精的是","o":["精","津","血","液","气"],"a":4,"e":"广义之精泛指精、血、津、液等一切构成人体并维持生命活动的精微物质，气属无形之活力，不在其中。"},{"q":"津液化为汗液排出体外，主要靠哪脏功能","o":["心主血脉","肺主宣发","肾主气化","肝主疏泄","脾主统摄"],"a":1,"e":"肺主宣发，宣发卫气于肌表、调节汗孔开合，津液借此化为汗液排出体外，故汗多汗少责之于肺。"},{"q":"体现事物阴阳属性的相对性的是","o":["对立制约","互根互用","互为消长","平衡协调","互相转化"],"a":4,"e":"阴阳属性相对性表现于阴阳之中复有阴阳，并在一定条件下可向其对立面转化，非一成不变。"},{"q":"五脏中称为“刚脏”的是","o":["心","脾","肺","肝","肾"],"a":3,"e":"肝为刚脏，其气主升主动，体阴而用阳，性刚烈而易亢逆，故有刚脏之称，病则易见阳亢。"},{"q":"体质的可变性与什么有关","o":["先天禀赋","后天因素","思维改变","智慧","阴虚体质"],"a":1,"e":"体质虽秉受于先天，但可随后天饮食起居、情志劳逸、锻炼与疾病等因素而改变，故体质可调。"},{"q":"肺与脾的关系，主要表现于","o":["气的生成和津液的输布代谢","气的生成","津液的输布代谢","血的生成","血的生成和津液的输布代谢"],"a":0,"e":"肺主气司呼吸，脾主运化而为气血生化之源，二者在气的生成与津液输布代谢上密切相关。"},{"q":"经络之间联系最主体的联系方式是","o":["十二经脉首尾衔接环周无端的联系","十二经脉相互间的交叉交会联系","奇经八脉自身之间的联系","十二经脉与奇经八脉之间的联系","经别、别络、浮络、孙络之间的联系"],"a":0,"e":"十二经脉首尾衔接、循环往复、环周无端，是经络系统联系最主体、最基本的方式，为气血运行之环。"},{"q":"认识外感寒邪的疾病发展规律的病机理论是","o":["六经病机","三焦病机","卫气营血病机","脏腑病机","气血津液病机"],"a":0,"e":"六经病机以六经概括外感寒邪由表入里、由阳转阴的传变规律，为外感病的辨证纲领与辨治基础。"},{"q":"生长发育迟缓、生殖功能减退的病机定位是","o":["心","肺","脾","肝","肾"],"a":4,"e":"肾藏精，主生长发育与生殖，肾精不足则生长发育迟缓、生殖功能减退，故病位在肾，为先天之本。"},{"q":"寒邪、湿邪的共同致病特点是","o":["损伤阳气","阻遏气机","病程缠绵","黏腻重浊","凝滞收引"],"a":0,"e":"寒为阴邪易伤阳气，湿为阴邪亦损脾阳，故二者共同点为损伤阳气；阻遏气机与凝滞收引则各有所主。"},{"q":"除哪项外均属于疠气性质及致病特点","o":["传染性强","致病性强","气候反常","流行性强","病情危笃"],"a":2,"e":"疠气性质与致病特点为传染性强、流行性强、致病性强、病情危笃，气候反常是其产生条件而非性质。"},{"q":"关于清法，下列说法错误的是","o":["温者清之","具有泻火、解毒、凉血作用","适用于脏腑诸火","适用于里热证、火证、热毒证","一般可以久用"],"a":4,"e":"清法以寒凉药泻火解毒凉血，适用于里热证、火证与热毒证，寒凉久用易伤阳败胃，故不可久用。"},{"q":"在水液代谢、呼吸运动及阴阳互资等方面密切相关的两脏是","o":["心与肺","脾与肾","肾与肝","肝与肺","肺与肾"],"a":4,"e":"肺主通调水道、肾主蒸腾气化，肺主呼气、肾主纳气，肺肾金水相生而阴阳互资，共主水液与呼吸。"},{"q":"按五行属性分类，五化中属土者是","o":["生","长","化","收","藏"],"a":2,"e":"五化生长化收藏分属五行，土居中而主化，故属土者为化，主万物成熟变化，为稼穑之能。"},{"q":"内湿的形成与何脏关系最为密切","o":["心","肝","脾","肺","肾"],"a":2,"e":"内湿由脾失健运、水液不化而停聚内生，故与脾关系最为密切，肺肾失司次之，脾健则湿自化。"},{"q":"上出息道的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"宗气积于胸中，上出息道以行呼吸、下走气街以贯心脉，故为上出息道之气，又称胸中之气。"},{"q":"心气不足时会出现","o":["心脏搏动有力","脉象和缓有力","心脏搏动无力","面色红赤","精神恍惚"],"a":2,"e":"心气不足则推动无力，心脏搏动无力，脉来细弱，可见心悸气短、面色淡白、动则尤甚，舌淡。"},{"q":"肾在志为","o":["怒","思","喜","恐","悲"],"a":3,"e":"肾在志为恐，恐为肾之志，恐惧过度则伤肾，使肾气不固、气机下陷而二便失禁、遗精滑泄。"},{"q":"心的病机特点是","o":["血脉运行失常和神志意识改变","神志意识改变和呼吸功能失常","主气功能失常和血液运行不畅","血液统摄失常和神志意识改变","气血运行失和和神志意识改变"],"a":0,"e":"心主血脉而藏神，故心病机特点为血脉运行失常与神志意识改变两方面，二者常相互影响。"},{"q":"悲伤过度主要损伤的脏腑是","o":["肝","心","脾","肺","肾"],"a":3,"e":"悲为肺之志，悲伤过度则耗伤肺气，致气短乏力、精神不振、声低懒言，甚则气短不足以息。"},{"q":"人的精神思维活动与哪个脏腑的功能最为密切","o":["心主神志","肺朝百脉","脾主统血","肝主藏血","肾主藏精"],"a":0,"e":"心藏神，为五脏六腑之大主，人的精神意识思维活动由心所主，故关系最为密切，主宰一身。"},{"q":"下列哪项不是脾的生理功能","o":["水谷的受纳和腐熟","水谷的精微的传输","水液的吸收和转输","脏器位置的维系","血液的统摄"],"a":0,"e":"水谷受纳腐熟为胃之功能，脾主运化、主升清、主统血，并维系内脏位置，二者分工不同。"},{"q":"“利小便而实大便”的理论依据是","o":["脾主运化","肺主通调水道","小肠主受盛","小肠主化物","小肠主泌别清浊"],"a":4,"e":"小肠泌别清浊，使水液下输膀胱、糟粕归于大肠，故利小便可使水走前阴而大便自实，此为分利之法。"},{"q":"温燥病的发病季节是","o":["夏末初秋","近冬深秋","长夏季节","冬末春初","春末夏初"],"a":0,"e":"温燥由初秋久晴无雨、燥而偏热所致，凉燥则见于深秋近冬，二者以秋分为界，性质有温凉之别。"},{"q":"痰与饮的主要区别是","o":["热者为痰，寒者为饮","在体内为痰，在体表为饮","黏稠者为痰，清稀者为饮","色黄者为痰，色白者为饮","量多者为痰，量少者为饮"],"a":2,"e":"痰与饮皆为水液停聚所化，稠浊黏稠者为痰，清稀者为饮，以性状相别，此为其主要区分点。"},{"q":"根据五行学说，未按五行相生顺序排列的是","o":["青、赤、黄、白、黑","筋、脉、肉、皮、骨","呼、笑、歌、哭、呻","酸、苦、甘、辛、咸","角、徵、商、宫、羽"],"a":4,"e":"五音配五行相生应为角、徵、宫、商、羽，题中商与宫次序颠倒，故不合相生顺序，当以角徵宫商羽为序。"},{"q":"防止食复不包括","o":["饮食宜有营养","饮食应清淡","饮食宜易消化","饮食宜以温热性的食品为主","饮食应注意护养胃气"],"a":3,"e":"食复指病后饮食失节致复发，调护宜清淡、易消化、富营养并顾护胃气，非以温热食品为主。"},{"q":"肺宣发功能异常时会出现","o":["尿量增多","汗量异常","食量正常","月经量异常","大便量异常"],"a":1,"e":"肺主宣发，宣发卫气与津液于体表、调控汗孔开合，宣发失常则汗出异常，或自汗或无汗。"},{"q":"气之本是","o":["肝","心","脾","肺","肾"],"a":3,"e":"肺主气司呼吸，主一身之气的生成与运行，故称气之本；肾为气之根而主纳气，肺肾共司呼吸。"},{"q":"与睡眠有密切关系的是","o":["元气","宗气","脏腑之气","经络之气","卫气"],"a":4,"e":"卫气昼行于阳分、夜行于阴分，随昼夜而出入，故与睡眠节律关系最为密切，卫气入阴则寐。"},{"q":"下列各项，消法适用的病证是","o":["气滞中满之鼓胀","脾虚而腹胀","妇人血枯经闭","饮食停滞","阴虚热病"],"a":3,"e":"消法以消食导滞、行气散结为用，适用于饮食停滞、癥瘕积聚；脾虚腹胀、血枯经闭当用补法。"},{"q":"下列说法正确的是","o":["女子以肝为先天，属阴，以血为用","女子以肾为先天，属阴，以气为用","男子以肝为先天，属阳，以血为用","男子以肝为先天，属阳，以气为用","男子以肾为先天，属阳，以血为用"],"a":0,"e":"女子以肝为先天，属阴，以血为用，肝藏血、主疏泄，冲任气血调和则经孕有常，故调经重肝。"},{"q":"患者年高体衰，病属虚寒，久已卧床不起。今日晨起突然面色泛红，烦热不宁，语言增多，并觉口渴，舌淡，脉大而无根。其病机是","o":["阴盛格阳","阳虚阴盛","阳损及阴","阳气亡失","阴阳离决"],"a":0,"e":"久病虚寒之体突见面红烦热、脉大无根，为阴寒内盛、逼迫虚阳浮越于外，属阴盛格阳，为真寒假热。"},{"q":"素体津亏血耗者，易致邪从","o":["寒化","热化","燥化","湿化","火化"],"a":2,"e":"津亏血耗者阴液本虚，感邪后易从燥化，见口燥咽干、皮肤干燥、便结等燥象，治宜润燥养阴。"},{"q":"十二经脉之气结、聚、散、络于关节的体系者为","o":["浮络","十二经筋","十五别络","孙络","十二经别"],"a":1,"e":"十二经筋是经脉之气结、聚、散、络于筋肉关节的体系，主束骨而利关节，为十二经筋之属。"},{"q":"瘀血最常见最特异性的指征为","o":["舌质紫暗，有瘀点瘀斑","疼痛","出血","肿块","失眠"],"a":0,"e":"舌质紫暗或有瘀点瘀斑为瘀血最常见、最特异的指征，疼痛、出血、肿块特异性均不及舌象。"},{"q":"肺主通调水道的功能主要依赖于","o":["肺主一身之气","肺司呼吸","肺输精于皮毛","肺朝百脉","肺主宣发与肃降"],"a":4,"e":"肺主宣发与肃降，宣发使津液外达皮毛，肃降使水液下输膀胱，二者协同通调水道，为水之上源。"},{"q":"属于病理产物类致病因素的是","o":["湿邪","火邪","药误","结石","胎毒"],"a":3,"e":"结石由湿热蕴结、杂质凝结而成，继发于他病，属病理产物类致病因素，与六淫之邪不同。"},{"q":"关于阳盛格阴，下列论述错误的是","o":["也叫真热假寒","邪热极盛，深伏于里，阳热被郁不能通达四肢","多见于外感热病的极期","临床表现为热象与寒象并见","本质上是本虚标实证"],"a":4,"e":"阳盛格阴为邪热深伏、阳气郁闭不能外达，属真热假寒的真实证，本质并非本虚标实，治当清泻里热。"},{"q":"称为“元神之府”的是","o":["髓","脑","骨","脉","胆"],"a":1,"e":"脑为髓海，由肾精化髓汇聚而成，藏元神而主精神活动，故称元神之府，为神明之所出也。"},{"q":"关于气虚的论述错误的是","o":["先天不足、后天失养均会导致气虚","临床可见到少气懒言、疲倦乏力等症状","气虚会影响血、津液的生化和运行","五脏皆有气虚证","易汗出者必然有气虚的原因"],"a":4,"e":"汗出可由阳虚、阴虚、湿热、营卫不和等所致，气虚固摄无权仅为其一，并非必然，不可一概补气。"},{"q":"六淫中其性趋下的邪气是","o":["风邪","寒邪","湿邪","燥邪","火邪"],"a":2,"e":"湿性重浊而趋下，易袭人体下部及阴位，症见下肢水肿、小便浑浊、带下等，故其性趋下。"},{"q":"阴损及阳发展到后期的结果是","o":["阴阳两虚","阴偏盛","阳偏盛","阴转化为阳","阳转化为阴"],"a":0,"e":"阴损及阳指阴虚日久不能化生阳气，阳亦不足，发展至后期即为阴阳两虚，为虚损之重候。"},{"q":"营气的分布特点是","o":["上出息道，下走气街","熏于肓膜，散于胸腹","通过三焦，流行全身","上荣头目，达于周身","与血同行，环周不休"],"a":4,"e":"营气由水谷精微化生，行于脉中，与血同行而环周不休，故常营血并称，实为脉中之精气。"},{"q":"劳神过度，又被称为","o":["体劳","心劳","肾劳","肝劳","房劳"],"a":1,"e":"劳神过度耗伤心血、暗耗脾气，故又称心劳，可见心悸失眠、纳呆倦怠诸症，为五劳之一。"},{"q":"明清时期，提出“卫之后方言气，营之后方言血”的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":2,"e":"叶天士创卫气营血辨证，指出温邪由卫入气、入营、入血，故卫之后方言气，营之后方言血。"},{"q":"下列哪项是形容肺的生理特性的","o":["生之本","后天之本","脏之长也","先天之本","封藏之本"],"a":2,"e":"肺位最高，覆压五脏，故《素问》称其为脏之长也；心为生之本、脾为后天之本、肾为先天之本。"},{"q":"根据五行学说，脾病传心属于","o":["母病及子","相乘","子病及母","相侮","制化"],"a":2,"e":"脾属土，心属火，火生土而脾为心之子，故脾病传心属子病及母，治当补母泻子，即补心以安脾。"},{"q":"主持诸气，总司人体气化的脏腑是","o":["三焦","脾","肾","肺","膀胱"],"a":0,"e":"三焦为六腑之一，主持诸气、总司人体气化，为水液与元气运行的通道，故称决渎之官，为孤府。"},{"q":"心与哪个季节相通应","o":["春","夏","秋","冬","长夏"],"a":1,"e":"心属火，火气通于夏，夏季阳气最盛而心气相应，故心与夏气相通应，夏季当注意养心护神。"},{"q":"下列各项，属于发病有关的外环境因素，错误的是","o":["地域因素","气候因素","工作环境","生活环境","精神状态"],"a":4,"e":"精神状态属内在情志因素，地域、气候、工作与生活环境方为发病的外环境因素，二者不可混称。"},{"q":"下列属于火热证症状特征，错误的是","o":["热（发热，恶热，喜冷）","赤（面赤，目赤，舌红）","稠（痰、涕、白带粘稠）","燥（口渴，咽干，便燥）","虚（乏力，气短，懒言）"],"a":4,"e":"火热证以热、赤、稠、燥为特征，分别反映阳热亢盛、热迫血行、热灼津液成痰及热盛伤津。乏力、气短、懒言属气虚表现，不属火热之象。"},{"q":"精、气、血、津液之间相互转化依靠气的","o":["推动作用","温煦作用","防御作用","固摄作用","气化作用"],"a":4,"e":"气化指气的运动引起精、气、血、津液各自的新陈代谢及相互转化，故四者互化赖气化作用。推动、温煦、防御、固摄各司其职而不主转化。"},{"q":"下注于气街，并下行于足的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"宗气积于胸中，出于喉咙，贯注心肺之脉，其下者蓄于丹田，并注于气街而下行于足。元气发于肾，营卫各行脉内外。"},{"q":"可以概括精和血之间具有相互转化和相互滋生的关系的是","o":["精可化血","血可化精","精血同源","精血同根","血可养精"],"a":2,"e":"精与血同源于水谷精微和肾精，二者相互资生、相互转化，故概括为精血同源。精可化血、血可化精只是这一关系的一个方面。"},{"q":"内风与哪个脏关系最为密切","o":["心","肝","脾","肾","肺"],"a":1,"e":"肝为风木之脏，主疏泄、藏血，阴血不足则阳亢化风，故内风多责之于肝，称为肝风内动。心火、脾湿、肾虚亦可致风，但非最密切。"},{"q":"我国第一部脉学专著是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《脉经》","《濒湖脉学》"],"a":3,"e":"《脉经》为西晋王叔和所撰，集汉以前脉学之大成，确立二十四脉，是我国第一部脉学专著。《濒湖脉学》为明代李时珍所作。"},{"q":"下列除哪项外均属于养生的原则","o":["天人合一，顺应自然","因人而异，辨证施养","调理脏腑，脾肾为先","热者寒之，寒者热之","动静结合，形神共养"],"a":3,"e":"热者寒之、寒者热之属正治治法，用于纠正寒热偏盛，不属养生原则。养生强调顺应自然、辨证施养、调养脾肾、形神共养。"},{"q":"异气是指","o":["六淫邪气","异常气候","情志变化","气机失常","乖戾之气"],"a":4,"e":"异气即疠气，又称乖戾之气、疫毒，指具有强烈传染性和致病性的外邪。其非六淫、异常气候，亦非情志变化或气机失常。"},{"q":"脾之大络的分出位置是","o":["长强穴","大横穴","大包穴","渊腋穴","隐白穴"],"a":2,"e":"脾之大络名大包，从脾脏分出，出渊腋下三寸，散布于胸胁。长强为督脉络穴，隐白为脾经井穴。"},{"q":"《金匮要略心典》说“吐下之余，定无完气。”其理论依据是","o":["气能生津","气能行津","气能摄津","津能载气","津能养气"],"a":3,"e":"津能载气，津液大量丢失则气随津脱，故吐下之余定无完气。治宜益气生津，而非单纯补气、行气或摄津。"},{"q":"治疗前额头痛的病变，通常使用的引经药是","o":["白芷","柴胡","香附","羌活","苍术"],"a":0,"e":"白芷芳香上达，入阳明经，善治前额及眉棱骨痛，为阳明头痛引经药。柴胡入少阳，羌活治太阳，苍术治太阴。"},{"q":"“至虚有盛侯”描述的是","o":["真虚假实","真实假虚","因虚致实","因实致虚","虚实错杂"],"a":0,"e":"至虚有盛候指正气极虚而出现类似邪实的假象，即真虚假实。大实有羸状则为真实假虚，二者不可混淆。"},{"q":"根据五行学说，佐金平木是指","o":["补肺泻肝","双补肝肺","泻肺补肝","双泻肝肺","以上均非"],"a":0,"e":"佐金平木即泻肝木、补肺金，用于肝火偏亢、肺金受侮之证，属相克关系失调的治法。培土生金则属相生治法。"},{"q":"五行学说中“水”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":3,"e":"水曰润下，指水具有滋润、下行、闭藏的特性。曲直属木，炎上属火，从革属金，稼穑属土。"},{"q":"“上焦如雾”，实际是指何作用","o":["心主血脉","肺主气","胃的受纳","心、肺的输布气血","肺主治节"],"a":3,"e":"上焦如雾喻心肺输布气血津液如雾露弥漫，灌溉全身，故指心肺的输布功能。中焦如沤、下焦如渎各有所主。"},{"q":"根据五行学说，肝病传心属于","o":["母病及子","相乘","子病及母","相侮","制化"],"a":0,"e":"肝属木，心属火，木生火，故肝病传心为母病及子。相乘为相克太过，相侮为反向克制，均属病理传变。"},{"q":"麻疹是一种常见的儿科疾病，其发生发展主要分为三个时期，即初期、中期、晚期，医生在治疗时，初期常用解表透疹法，中期常用清肺热法，后期常用滋养肺阴胃阴等方法，麻疹疾病的分期及其对应的治疗方案体现了哪种中医思维","o":["因人制宜","同病异治","异病同治","审因论治","虚则补之"],"a":1,"e":"麻疹同一疾病在不同分期证候不同，故分别采用解表透疹、清肺泄热、滋养肺胃阴之法，属同病异治。"},{"q":"下列药物性能中，属于阳的是","o":["寒、辛、浮","温、甘、升","热、咸、升","热、辛、沉","温、酸、降"],"a":1,"e":"温热属阳，辛甘发散属阳，升浮属阳，故温、甘、升为阳；寒凉、酸苦咸及沉降均属阴。四气五味与升降浮沉须合参。"},{"q":"下列除哪项外均属于运动养生的内容","o":["太极拳","散步","冥想","气功","慢跑"],"a":2,"e":"运动养生以活动形体为特点，太极拳、散步、气功、慢跑均属之。冥想静坐调心，属精神情志调养。"},{"q":"从众多不同事物的形象、现象、表象中“去粗取精、去伪存真、由此及彼、由表及里”进行提炼，抽取事物的本质，舍弃非本质的特征，称为","o":["观物取象","立象尽意","得意忘形","取象比类","其象相应"],"a":1,"e":"立象尽意指对事物现象去粗取精、去伪存真，提炼本质并以象表达。观物取象重在观察摄取，取象比类重在类推。"},{"q":"称肝为“罢极之本”，主要是由于肝有下列哪种功能","o":["促进血行","调畅气机","贮藏血液","疏通水道","疏泄肾精"],"a":2,"e":"肝藏血，血养筋，筋得血养则运动有力、耐受疲劳，故称罢极之本。调畅气机为疏泄之能，非罢极之所本。"},{"q":"六淫中最易导致生风动血的邪气是","o":["风邪","寒邪","湿邪","火邪","燥邪"],"a":3,"e":"火为阳邪，其性燔灼急迫，易入营血、耗伤阴液，甚则生风动血、迫血妄行。风邪虽主动，动血之力不及火邪。"},{"q":"观察心主血脉的功能是否正常，与下列哪项关系较小","o":["面色","舌色","爪色","脉象","胸部的感觉"],"a":2,"e":"心主血脉，其华在面，开窍于舌，血脉充盈与否可察面色、舌色、脉象及胸部感觉。爪为筋之余，候肝之血气。"},{"q":"“中精之腑”是指","o":["胃","胆","膀胱","小肠","三焦"],"a":1,"e":"胆贮藏排泄精汁，中正不偏，故称中精之腑、中正之官。胃为水谷之海，膀胱为州都之官。"},{"q":"人体生、长、壮、老、已的生命过程体现为","o":["恒动变化","动静相召","天人合一","整体宏观","法于阴阳"],"a":0,"e":"人体生、长、壮、老、已的过程始终处于运动变化之中，体现恒动变化。天人合一言人与自然的统一。"},{"q":"根据五行学说，由相生关系确立的治法是","o":["培土生金","培土制水","抑木扶土","佐金平木","泻火补水"],"a":0,"e":"培土生金以补脾益肺治肺虚，依土生金之相生关系。培土制水、抑木扶土、佐金平木均属相克关系治法。"},{"q":"风邪伤人，导致病变部位游走不定的原因是","o":["风性数变","风性善行","风性主动","风性轻扬","风性开泄"],"a":1,"e":"风性善行而数变，善行指病位游走不定、行无定处；数变指发病急骤、变化迅速。二者所指不同。"},{"q":"心包络又称","o":["血府","膻中","奇恒之府","华盖","刚脏"],"a":1,"e":"心包络为心之外围，又称膻中，代心行令、代心受邪。血府指脉，华盖指肺，刚脏指肝，奇恒之腑别有归属。"},{"q":"肺气是由什么化生而成","o":["肺气","肺阴和肺阳","先天之精","水谷之精","肺精和肺津"],"a":4,"e":"肺气由肺精化生，肺津亦可化为肺气，故肺气源于肺精与肺津。先天之精、水谷之精为其化生的物质基础。"},{"q":"下列五行生克规律的表述，正确的是","o":["木为土之所胜","木为水之子","火为土之子","水为火之所胜","金为木之所胜"],"a":1,"e":"水生木，故木为水之子；木克土，故土为木之所胜。火为木之子、金为火之所胜，其余表述均颠倒。"},{"q":"治疗血瘀证，常酌配行气药物，其理论依据是","o":["气能行血","气能生血","气能摄血","血能载气","血能化气"],"a":0,"e":"气能行血，气行则血行，气滞则血瘀，故治血瘀常配行气药以助血运。气能生血、摄血各主其他病证。"},{"q":"下列哪项不属于病后防复的内容","o":["防止复感新邪","截断病传途径","防止劳复","防止药复","防止食复"],"a":1,"e":"病后防复包括防复感新邪及防劳复、食复、药复。截断病传途径属既病防变，为早期诊治、防止病邪深入之策。"},{"q":"任脉的别络散布的部位是","o":["上肢部","下肢部","背部","胸胁部","腹部"],"a":4,"e":"任脉之别络名鸠尾，散布于腹部。督脉别络散布头上，脾之大络布于胸胁，故腹部为任脉络所布。"},{"q":"攻补兼施治则适用于何证","o":["虚证","真实假虚证","实证","真虚假实证","虚实夹杂证"],"a":4,"e":"攻补兼施即祛邪与扶正并用，适用于邪实正虚、虚实夹杂之证。纯虚宜补，纯实宜攻，真假虚实当辨其本质。"},{"q":"根据五行学说，属于母病及子的是","o":["肺病及肾","肝病及肾","肺病及心","心病及肝","脾病及肾"],"a":0,"e":"肺属金，肾属水，金生水，故肺病及肾为母病及子。肝病及肾为子病及母，脾病及肾则属相乘。"},{"q":"绦虫病的形成多因","o":["嗜食肥甘","嗜酒过度","生食或食用未煮熟的猪、牛肉","脾胃虚弱","饮食不节"],"a":2,"e":"绦虫病因进食含囊尾蚴的生猪肉或未煮熟的猪、牛肉，囊尾蚴在肠内发育为成虫。肥甘、嗜酒多致湿热痰浊。"},{"q":"足厥阴肝经，过阴器，抵小腹，布胁肋，连目系，上出额，与督脉会与巅，故肝气郁结常见","o":["头晕胀痛","阴部湿疹","胸胁胀满","腰膝酸痛","面红耳赤"],"a":2,"e":"足厥阴肝经布胁肋，肝气郁结、经气不利则胸胁胀满。头晕胀痛、面红目赤多属肝阳上亢、肝火上炎。"},{"q":"根据五行学说，金气有余而致木气虚弱属","o":["母病及子","相侮","子病及母","相乘","制化"],"a":3,"e":"金克木，金气有余而乘木，致木气虚弱，属相乘传变。相侮为木气有余反侮金，二者传变方向相反。"},{"q":"在不同地区生活，感受六淫邪气有所不同，说明六淫致病具有何种特性","o":["外感性","季节性","地域性","相兼性","转化性"],"a":2,"e":"六淫致病与地域环境相关，不同地区气候、地势不同，常见邪气各异，此为地域性。季节性指与时令气候相应。"},{"q":"患者久病，纳少，乏力，腹胀，但时有减缓，腹痛喜按，舌胖嫩而苔润，脉细弱无力。其病机是","o":["真实假虚","真实病证","真虚假实","真虚病证","虚中夹实证"],"a":2,"e":"久病纳少、乏力、腹胀时减、腹痛喜按、舌胖嫩苔润、脉细弱，均属正虚之象；腹胀时减似实而实为虚，故属真虚假实。"},{"q":"五行学说中“木”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":0,"e":"木曰曲直，指木具有生长、升发、条达舒畅之性。炎上属火，从革属金，润下属水，稼穑属土。"},{"q":"一经证候未罢又出现另一经证候的情况是","o":["直中","合并","并病","循经传","越经传"],"a":2,"e":"并病指一经证候未罢又出现另一经证候，两经证候同时存在。合病为两经或三经同时受邪起病，二者不同。"},{"q":"可用阴阳互根互用解释的是","o":["寒极生热","阴病治阳","寒者热之","重阴必阳","阴中求阳"],"a":4,"e":"阴中求阳指补阳时佐以补阴，使阳得阴助而生化无穷，体现阴阳互根互用。寒极生热、重阴必阳属阴阳转化。"},{"q":"金元四大家中倡导以汗、吐、下三法攻邪祛病的是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":2,"e":"张从正号戴人，主张病由邪生、邪去正安，善用汗吐下三法攻邪，为攻邪派代表。刘完素主火热，朱丹溪主滋阴。"},{"q":"下列哪项除外，均属养形的养生方法","o":["调理饮食","起居有时","节制房事","修德养性","劳逸结合"],"a":3,"e":"养形重在调养形体，包括调理饮食、起居有时、节制房事、劳逸结合。修德养性属养神，为形神共养中调神之法。"},{"q":"下列病证与先天禀赋有密切关系的是","o":["五迟","五软","鸡胸","解颅","以上都是"],"a":4,"e":"五迟、五软、鸡胸、解颅均属小儿发育障碍，其发生与先天禀赋不足、肾精亏虚密切相关，故以上均是。"},{"q":"在疾病传变的过程中，少阳传太阴是","o":["循经传","越经传","表里传","合病","并病"],"a":0,"e":"六经传变按太阳、阳明、少阳、太阴、少阴、厥阴次序相传为循经传，少阳传太阴正合此序。"},{"q":"喜燥恶湿的脏是","o":["心","脾","肾","肺","肝"],"a":1,"e":"脾属土，主运化水湿，湿盛易困脾，故脾喜燥恶湿，治脾常佐燥湿之品。肾恶燥，肺喜润而恶燥。"},{"q":"根据五行学说，下列属“相乘”传变的是","o":["火传土","土传金","金传水","水传木","金传木"],"a":4,"e":"金克木，金气偏盛而乘木，属相乘传变。火传土、土传金、金传水、水传木均为相生关系，属母病及子。"},{"q":"下列不属于老年人体质特点的是","o":["脏腑功能衰退","精气神渐衰","虚多实少","代谢旺盛","多夹痰瘀"],"a":3,"e":"老年人脏腑功能衰退、精气神渐衰，虚多实少且多夹痰瘀，代谢趋于低下而非旺盛，故代谢旺盛为错误项。"},{"q":"感冒的治疗，可分别采用辛温解表或辛凉解表，此属于","o":["辨病论治","因人制宜","同病异治","异病同治","辨证论治"],"a":2,"e":"感冒病因相同而证候有风寒、风热之别，故分别辛温、辛凉解表，属同病异治。因人制宜强调个体差异。"},{"q":"下列属于吐法适应证以外的是","o":["食积停滞胃脘","顽痰留滞胸膈","痰涎阻塞于气道","误食毒物在胃中","积滞生热，腹胀而痛"],"a":4,"e":"吐法适用于食积停滞胃脘、顽痰留滞胸膈、痰涎阻塞气道及误食毒物尚在胃中者。积滞生热、腹胀而痛当用消导攻下。"},{"q":"下列各项中，属于相乘传变的是","o":["肺病及肾","肺病及心","心病及肝","肝病及肾","脾病及肾"],"a":4,"e":"脾属土，肾属水，土克水，脾病及肾为相乘传变。肺病及肾属母病及子，肺病及心属相侮。"},{"q":"藏象学说主要是研究","o":["脏腑生理","脏腑病理","脏腑生理、病理之间的关系","脏腑生理、病理及其相互关系","脏腑组织器官结构形态"],"a":3,"e":"藏象学说以脏腑为研究对象，阐述脏腑生理功能、病理变化、相互关系及与形体官窍的联系，故包括生理、病理及其相互关系。"},{"q":"关于温法，下列说法错误的是","o":["形不足者，温之以气","清者温之","劳者温之","仅适用于寒实证","消除沉寒痼冷"],"a":3,"e":"温法温散里寒、消除沉寒痼冷，适用于寒证，含寒实证与虚寒证，故“仅适用于寒实证”有误。形不足者温之以气、劳者温之均属之。"},{"q":"经络系统中，具有加强十二经脉在体表联系的是","o":["正经","经别","经筋","别络","奇经"],"a":3,"e":"别络为经脉分出的支脉，十二经别络加任督及脾之大络，加强十二经脉在体表的联系。经别主加强表里两经深部联系。"},{"q":"关于内生五邪，论述错误的是","o":["是由于内在脏腑和气血津液等生理功能异常引起","也有一定的六淫所伤","暑邪纯属外邪，并无“内暑”之说","津伤化燥属于内生五邪之一","阳气不足可致寒从内生"],"a":1,"e":"内生五邪由脏腑气血津液功能异常而内生，与外感六淫不同，故“也有一定的六淫所伤”表述错误。暑纯属外邪，无内暑之说。"},{"q":"手三阴经的走向是","o":["从胸走手","从手走头","从头走足","从足走头","从足走腹"],"a":0,"e":"手三阴经从胸走手，手三阳经从手走头，足三阳经从头走足，足三阴经从足走腹胸，此即经脉走向的基本规律。"},{"q":"六淫既可单独伤人，又可两种及以上同时侵犯人体，说明六淫致病具有何种特性","o":["外感性","季节性","地域性","相兼性","转化性"],"a":3,"e":"六淫可单独或两种以上同时侵犯人体，如风寒、湿热相兼为病，故为相兼性。外感性指多从肌表口鼻而入。"},{"q":"“阴损及阳”、“阳损及阴”、“阴阳俱损”，是根据","o":["阴阳互根","阴阳对立","阴阳消长","阴阳转化","阴阳制约"],"a":0,"e":"阴损及阳、阳损及阴、阴阳俱损，均因阴阳双方互根互用，一方虚损日久必累及另一方，故依据阴阳互根。"},{"q":"属于五脏功能的表现的是","o":["五志","五气","五味","五臭","五音"],"a":0,"e":"五脏藏神，心藏神、肺藏魄、肝藏魂、脾藏意、肾藏志，五志分属五脏，为脏腑功能活动的外在表现。"},{"q":"牙龈红肿，口臭，多见于","o":["心火上炎","肺热灼盛","肝火上炎","胃火上冲","胆经郁热"],"a":3,"e":"足阳明胃经入上齿，胃火循经上炎则牙龈红肿疼痛、口气臭秽。心火多口舌生疮，肝火多目赤易怒。"},{"q":"关于防止食复，以下说法错误的是","o":["饮食宜有营养","饮食宜清淡","饮食宜消化","饮食宜以温热性的食品为主","饮食应注意护养胃气"],"a":3,"e":"防止食复宜饮食清淡、易消化、有营养并护养胃气。病后脾胃虚弱，过食温热燥烈之品易助热伤津，故不宜以温热食品为主。"},{"q":"导致食复的原因，错误的是","o":["多食","强食","不注意“忌口”","滥服补剂","不注重饮食卫生"],"a":3,"e":"食复因多食、强食、不注意忌口及饮食不洁而致，使脾胃受损、余邪复燃。滥服补剂致旧病复发称药复，不属食复范畴。"},{"q":"膀胱的主要病机特点是","o":["受纳功能失常","传导功能失常","气化作用失常","腐熟功能失常","藏精功能失常"],"a":2,"e":"膀胱主贮尿排尿，赖肾阳之气化，其病机特点为气化失常，见尿频、尿闭、遗尿。受纳腐熟属胃，传导属大肠。"},{"q":"中医学描述肺“虚如蜂巢”所体现的思维方式是","o":["形象思维","意象思维","应象思维","抽象思维","逻辑思维"],"a":0,"e":"肺虚如蜂巢系取肺体虚空如蜂窝之形态直接比附，属形象思维。意象思维、应象思维重在以象类推。"},{"q":"体阴而用阳的脏是","o":["心","脾","肾","肺","肝"],"a":4,"e":"肝藏血，以血为体，故体阴；肝主疏泄，内寄相火，其气主升主动，故用阳。体阴用阳概括肝的生理特性。"},{"q":"肾中精气的主要生理功能是","o":["促进机体的生长发育","促进生殖功能的成熟","主生长发育和生殖","化生血液的物质基础","人体生命活动的根本"],"a":2,"e":"肾藏精，精能化气，主生长发育与生殖，为人体生长壮老已的根本。化生血液、推动脏腑活动为其部分作用。"},{"q":"统摄运动功能的是","o":["脾意","肾志","心神","肺魄","肝魂"],"a":2,"e":"心藏神，为五脏六腑之大主，神能统驭形体、主宰运动，故统摄运动功能属心神。魂魄意志各有所主而不统运动。"},{"q":"能主二便的脏腑是","o":["脾","三焦","膀胱","小肠","肾"],"a":4,"e":"肾开窍于二阴，主司二便，肾气固摄与气化正常则二便调畅。大肠传导、膀胱贮尿均受肾气所主。"},{"q":"在下列阴阳失调病机中，最易出现虚阳外越的是","o":["阴损及阳","阳损及阴","阴盛格阳","阳盛格阴","阴虚阳亢"],"a":2,"e":"阴寒内盛，格阳于外，虚阳浮越，故见身热面赤、脉大无根，即阴盛格阳。阳盛格阴则热深厥深，二者相反。"},{"q":"下列属于养生内容的是","o":["治疗、防病、益寿","强身、康复、益寿","强身、防病、治疗","康复、防病、益寿","强身、防病、益寿"],"a":4,"e":"养生以强身健体、预防疾病、延年益寿为目的，不含治疗疾病，故强身、防病、益寿为确切表述。"},{"q":"以调节气机升降为主要关系的两脏","o":["肺与肾","肺与肝","肺与脾","肝与脾","心与肝"],"a":1,"e":"肝气主升发，肺气主肃降，二者协调维持气机升降平衡，故调节气机升降以肺与肝关系最密切。"},{"q":"关于邪正虚实，以下说法不正确的是","o":["正邪斗争影响着疾病的发展和转归","正邪的力量在疾病发展中不是一成不变的","一般来说，正盛则邪退","正邪相搏，斗争剧烈，是实证的特点","正邪相搏，斗争剧烈，是虚证的特点"],"a":4,"e":"正邪相搏、斗争剧烈、反应亢盛是实证的特点；虚证为正不胜邪、反应低下。故该项表述错误。"},{"q":"聚于胸中之气指的是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"宗气由肺吸入之清气与脾胃水谷之气结合而成，聚于胸中，故称聚于胸中之气。元气发于肾，营卫行于脉内外。"},{"q":"邪郁化火的机制是","o":["邪气阻遏气机，导致阳气郁滞，生热化火","邪气亢盛自行化火","阳邪有余，导致人身阳盛化火","阳邪阻遏人身水道，耗伤津液化火","阴邪阻遏人身水道，津液流行不畅，导致局部阴虚化火"],"a":0,"e":"邪郁化火指外邪或痰饮瘀血等阻滞气机，阳气郁滞不通，郁久生热化火，其基本机制为阳气郁滞。"},{"q":"称为“封藏之本”的脏是","o":["心","肝","脾","肾","肺"],"a":3,"e":"肾主藏精，为封藏之本，精宜藏而不宜妄泄。肝为罢极之本，肺为气之本，脾为后天之本。"},{"q":"五脏中，下列各项均与女子胞关系最为密切，错误的是","o":["心","肝","脾","肺","肾"],"a":3,"e":"女子胞的月经、孕育赖心血下注、肝血疏泄、脾生化气血、肾精充盛，故与心肝脾肾最密切，肺关系最小。"},{"q":"阴偏衰的治疗原则是","o":["滋阴壮水","寒者热之","损其有余","扶阳益火","热者寒之"],"a":0,"e":"阴偏衰为阴虚不能制阳而虚热内生，治宜滋阴壮水以制阳光。扶阳益火疗阳虚，损其有余疗实盛。"},{"q":"在五行学说中，五季中的“长夏”归属于","o":["木","火","土","金","水"],"a":2,"e":"五季配五行，春属木、夏属火、长夏属土、秋属金、冬属水。长夏湿热最盛，与脾土相应，故脾在时为长夏。"},{"q":"寒主收引是指","o":["寒邪阻滞气机","寒邪损伤阳气","寒邪耗气伤津","寒邪重浊黏滞","使气机收敛，筋脉挛急"],"a":4,"e":"寒性收引，指寒邪侵袭使气机收敛、筋脉挛急、关节屈伸不利。寒伤阳气、寒性凝滞各为寒邪另一特性。"},{"q":"“昼不精，夜不暝”这一临床现象是由阴阳的何种关系失调导致的","o":["阴阳对立制约","阴阳交感互藏","阴阳消长转化","阴阳自和平衡","阴阳互根互用"],"a":4,"e":"昼日精力不济、夜间不能安寐，为阳不入阴、阴不敛阳，责之阴阳互根互用失常，二者互济关系被破坏。"},{"q":"以下属于基本病机的是","o":["阴阳失调","邪正盛衰","气血失调","津液代谢失调","以上均是"],"a":4,"e":"基本病机包括邪正盛衰、阴阳失调、气血失调及津液代谢失常，贯穿于各种病证之中，故以上均是。"},{"q":"心与肝的关系主要表现在","o":["血行方面","气血的生成","精神、思维、意识活动","血行和精神、思维、意识活动","气血的生成和精神、思维、意识活动"],"a":3,"e":"心主血、肝藏血，共同维持血行；心藏神、肝主疏泄以调畅情志，共主精神思维活动，故两方面均是。"},{"q":"下列各项均属于津液的排泄途径，错误的是","o":["汗","尿","呼气","呕吐物","粪"],"a":3,"e":"津液排泄途径为汗、呼气、尿、粪。呕吐物为胃内容物上逆而出，属病理表现，不属津液的正常排泄途径。"},{"q":"易损伤脾胃阳气，导致寒湿内生的病因是","o":["嗜酒","嗜烟草","嗜辛辣","嗜生冷寒凉","嗜酸"],"a":3,"e":"生冷寒凉之品直伤脾胃阳气，脾阳受损则运化失职、寒湿内生，故嗜食生冷寒凉易致寒湿困脾。"},{"q":"根据五行学说，金之子是","o":["木","水","金","火","土"],"a":1,"e":"金生水，故水为金之子，金之母为土。五行相生次序为木生火、火生土、土生金、金生水、水生木。"},{"q":"养生的基本原则中，重在调养的内脏是","o":["心、肾","心、脾","肝、肾","肝、心","肾、脾"],"a":4,"e":"养生以调养脾肾为要，肾为先天之本、脾为后天之本，脾肾充盛则精气充足、体质强健，故重在脾肾。"},{"q":"津液输布失常所导致的痰饮水肿等病证与哪个脏腑有关","o":["肝","心","胃","肺","肾"],"a":3,"e":"肺主通调水道，为水之上源，肺失宣降则津液输布失常，水停而为痰饮水肿，故与肺的关系最直接。"},{"q":"肾主藏","o":["魂","神","魄","志","意"],"a":3,"e":"五脏藏神，心藏神、肺藏魄、肝藏魂、脾藏意、肾藏志，五志分属五脏，故肾所藏者为志。"},{"q":"具有“壅遏营气，令无所避”功能的是","o":["脾","心","脉","气","三焦"],"a":2,"e":"脉为血之府，能约束营血使其循行脉中而不外溢，故壅遏营气、令无所避。气为血帅，主推动与固摄。"},{"q":"关于“阴虚火旺”的论述错误的是","o":["此“火”属于虚火","是人体阴阳失调的一种表现","多由精亏血少、阴液大伤引起","阴虚阳亢是其基本病机","治疗宜以苦寒清热为主"],"a":4,"e":"阴虚火旺属虚火，因精亏血少、阴不制阳而虚热内扰，治宜滋阴降火；苦寒直折更伤阴液，故该项错误。"},{"q":"在经络系统中，承载大部分气血输送任务的是","o":["十二皮部","十二经筋","十二别络","十二经脉","十二经别"],"a":3,"e":"十二经脉为经络系统主体，是气血运行的主要通道，承载大部分气血输送任务。经别、别络、经筋主联络与濡养。"},{"q":"属于养生基本原则，错误的是","o":["“治未病”的预防思想","人与自然环境和谐统一","突出精神心理健康","“节阴阳而调刚柔”的守中思想","辨证论治"],"a":4,"e":"养生基本原则包括治未病、顺应自然、形神共养、调和阴阳、调养脾肾等。辨证论治为诊治疾病的原则，不属养生。"},{"q":"水火之宅是指","o":["脾","胃","肾","肝","肺"],"a":2,"e":"肾藏精寓元阴元阳，为水火之宅、阴阳之根本，五脏之阴非此不能滋，五脏之阳非此不能发。"},{"q":"脏腑关系中，“水火既济”指的是","o":["肝与肾","心与肾","肝与脾","肺与脾","肺与肝"],"a":1,"e":"心属火居上，肾属水居下，心火下温肾水，肾水上济心火，水火既济、心肾相交，故指心与肾。"},{"q":"“阴脉之海”指的是","o":["督脉","冲脉","任脉","带脉","跷脉"],"a":2,"e":"任脉行于胸腹正中，总任一身之阴经，称阴脉之海。督脉总督阳经为阳脉之海，冲脉为十二经之海。"},{"q":"下列除哪项外均是中医饮食养生所提倡的","o":["药膳保健","克服饮食偏嗜","注意饮食卫生","强调高营养饮食","提倡饮食有节"],"a":3,"e":"中医饮食养生主张饮食有节、注意卫生、克服偏嗜、药膳保健。强调高营养饮食有悖平衡膳食之旨。"},{"q":"关于补法，下列说法错误的是","o":["精不足者，补之以味","“大实有羸状”者，可以补","分峻补、平补、缓补","补血须不忘补气","常根据其虚在何脏，直接补其脏"],"a":1,"e":"大实有羸状属真实假虚，治当祛邪，误用补法反助其邪。补法分峻补、平补、缓补，补血不忘补气，精不足者补之以味。"},{"q":"针刺腧穴时，局部有酸、麻、重、胀等感觉及沿经脉走向传导的现象称为","o":["守气","得气","气脱","行气","补气"],"a":1,"e":"针刺得气指针刺部位产生酸、麻、重、胀并沿经脉传导的现象，为取效的关键。守气、行气属后续手法。"},{"q":"《灵枢·经水》所提及的：“脏之坚脆，腑之大小，谷之多少，脉之长短”与下列哪项关系最为密切","o":["环境基础","解剖基础","医药基础","自然科学基础","人文哲学基础"],"a":1,"e":"《灵枢·经水》所载脏之坚脆、腑之大小、脉之长短等均属形态结构描述，说明中医学具有解剖基础。"},{"q":"经络分阴阳，被称为“阳脉之海”的是","o":["督脉","任脉","阴维脉","阳维脉","带脉"],"a":0,"e":"督脉行于脊背正中，总督一身之阳经，故称阳脉之海。任脉总任阴经，冲脉为血海、十二经之海。"},{"q":"具有“通行诸气和运化水液”生理功能的腑是","o":["胆","膀胱","胃","三焦","小肠"],"a":3,"e":"三焦主持诸气、通行诸气，又为水液运行之道路，总司气化，故通行诸气与运化水液为其生理功能。"},{"q":"区分五脏、六腑、奇恒之腑三类的最主要依据是","o":["解剖形态的差异","分布部位的不同","功能特点的不同","经脉阴阳属性的不同","病理表现的不同"],"a":2,"e":"五脏藏精气而不泻，六腑传化物而不藏，奇恒之腑形似六腑而功能似五脏，故以功能特点为分类的最主要依据。"},{"q":"“天癸”的产生取决于","o":["先天禀赋的强弱","元气的充沛","肾阴肾阳的协调平衡","肾中精气的充盈","后天之精的充养"],"a":3,"e":"天癸为肾精充盛到一定阶段所化生的促进生殖功能成熟的物质，其产生取决于肾中精气的充盈。"},{"q":"瘀血的脉象可表现为","o":["浮缓","浮紧","细涩","濡细","滑数"],"a":2,"e":"瘀血内阻，脉道不畅，血行迟滞，故脉见细涩。浮缓主表虚湿盛，浮紧主表寒，滑数主痰热。"},{"q":"下列各项，除哪项外均属于中医基础理论课程的主要内容","o":["中医学的哲学基础","中医学对人体生理活动的认识","中医学对疾病基本规律的认识","中医学对疾病防治原则的认识","中医学对宇宙变化的认识"],"a":4,"e":"中医基础理论包括哲学基础、对人体生理活动的认识、疾病基本规律及防治原则等，宇宙变化属古代哲学背景，非本课程主要内容。"},{"q":"津液在体内得不到正常的转输和布散，在体内环流迟缓，困阻于内的病理状态，称之为","o":["阳不化气","湿浊困阻","阳虚水泛","水气凌心","湿遏热伏"],"a":1,"e":"津液转输布散迟缓、停聚困阻于内，称湿浊困阻，属津液代谢失常的病理状态。阳虚水泛、水气凌心各有定位。"},{"q":"五脏主五液，肾之液为","o":["汗","唾","涕","泪","涎"],"a":1,"e":"五脏化五液，心为汗、肺为涕、肝为泪、脾为涎、肾为唾，故肾之液为唾。涎为脾液，主助消化。"},{"q":"衄家不可发汗，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","血能载气"],"a":0,"e":"血与津液同源，血可化津；衄家阴血已伤、津液不足，若再发汗则更伤津血，故有夺血者无汗之戒。"},{"q":"关于津伤化燥的形成原因论述错误的是","o":["可起于久病伤阴耗液","可发生于大汗、大吐、大下之后","可发生于亡血失精之后","可发生于热性病过程中","必须有内热因素参与才能形成"],"a":4,"e":"津伤化燥可由久病耗阴、大汗大吐大下、亡血失精及热病伤津等引起，不必有内热参与，故该项错误。"},{"q":"五脏分阴阳，其中属于阳中之阴的是","o":["肝","心","脾","肺","肾"],"a":3,"e":"五脏分阴阳，心肺居上属阳，肝脾肾居下属阴；心为阳中之阳，肺为阳中之阴，肾为阴中之阴。"},{"q":"肝在液为","o":["涎","泪","汗","涕","唾"],"a":1,"e":"肝开窍于目，目得肝血而能视，泪由肝血化生，故肝在液为泪。涎属脾，汗属心，涕属肺，唾属肾。"},{"q":"肾藏（ ），为先天之本，水火之宅，是元气、阴精的生发之源","o":["气","血","阴","精","阳"],"a":3,"e":"肾藏精，主生长发育与生殖，为先天之本、水火之宅，元气由肾精化生，故为元气、阴精的生发之源。"},{"q":"中医学理论体系形成于","o":["隋唐时期","金元时期","明清时期","战国至两汉时期","春秋战国时期"],"a":3,"e":"中医学理论体系形成于战国至两汉时期，以《黄帝内经》《难经》《伤寒杂病论》《神农本草经》为形成标志。"},{"q":"气的运动受阻，不畅通，称为","o":["气机不畅","气结","气闭","气逆","气虚"],"a":0,"e":"气机不畅指气的运动受阻、流行不畅，郁滞程度较轻；气结、气闭为郁滞加重，气逆为升降失常。"},{"q":"“阴阳离决，精气乃绝”是指","o":["阴阳平衡关系的破坏","阴阳对立关系的破坏","阴阳互根关系的破坏","阴阳消长关系的破坏","阴阳转化关系的破坏"],"a":2,"e":"阴阳双方互根互用、彼此依存，若离决则孤阴不生、独阳不长，精气随之竭绝，故为互根关系的破坏。"},{"q":"肾主纳气的主要生理功能作用是","o":["使肺之呼吸保持一定的深度","有助于元气的固摄","有助于精液的固摄","有助于元气的生成","有助于肺气的宣发"],"a":0,"e":"肾主纳气，摄纳肺所吸入之清气，使呼吸保持一定深度，防止呼吸表浅。肾不纳气则见呼多吸少、动则喘甚。"},{"q":"下列关于五脏外合五体的叙述，错误的是","o":["心合脉","肝合爪","脾合肉","肺合皮","肾合骨"],"a":1,"e":"肝在体合筋，其华在爪，爪为筋之余，故称肝合筋而非肝合爪。心合脉、脾合肉、肺合皮、肾合骨。"},{"q":"下列不属于肝的主要生理功能的是","o":["调节全身水液代谢","调节全身血量","调节全身阴阳","调畅全身气机","调节一切情志活动"],"a":2,"e":"肝主疏泄以调畅气机、情志，主藏血以调节血量；调节全身阴阳为肾之功能，不属肝的生理功能。"},{"q":"“中焦如沤”主要是描述","o":["胃的受纳","脾的散精","小肠泌别清浊","胃的腐熟水谷","大肠传化糟粕"],"a":3,"e":"中焦如沤喻脾胃腐熟水谷、泌糟粕蒸津液的作用，其中以胃的腐熟水谷为核心。上焦如雾，下焦如渎。"},{"q":"《素问·天元纪大论》:“太虚寥廓，肇基化元，万物资始，五运终天，布气真灵，摁统坤元……生生化化，品物咸章。”体现的中医学思维方式是","o":["象思维","系统思维","变易思维","意象思维","应象思维"],"a":1,"e":"该段论述太虚化生元气、五运布化、万物生化，强调人与天地万物是协调统一的整体，体现系统思维。"},{"q":"贯注于心肺之脉的气是","o":["元气","宗气","营气","卫气","脏腑精气"],"a":1,"e":"宗气积于胸中，贯注于心肺之脉，推动气血运行、主司呼吸。元气发于肾，营行脉中，卫行脉外。"},{"q":"治疗血瘀证时，常酌配补气、行气药物的依据是","o":["气能生血","气能行血","气能摄血","血能载气","血能化气"],"a":1,"e":"气为血帅，气行则血行，气虚推动无力或气滞不行均可致瘀，故治瘀配补气、行气药，依据为气能行血。"},{"q":"关于阴盛格阳下列论述错误的是","o":["也叫真寒假热","阴寒之邪壅盛于内，逼迫衰极之阳浮越于外","多见于虚寒形病变的严重阶段","常有身热、面颊泛红等热性症状","也有感受热邪的因素影响，故见假热症状"],"a":4,"e":"阴盛格阳为阴寒内盛、格阳于外，属真寒假热，见于虚寒重证；其身热面赤由格阳所致，与外感热邪无关。"},{"q":"曾提出“土气为万物之源，胃气为养生之主。胃强则强，胃弱则弱，有胃则生，无胃则死，是以养生家当以脾胃为先”的医家是","o":["张景岳","李东垣","朱丹溪","孙思邈","张仲景"],"a":0,"e":"张景岳重视脾肾，提出土气为万物之源、胃气为养生之主，有胃则生、无胃则死，强调养生家当以脾胃为先。"},{"q":"“筋之余”是指","o":["面","爪","毛","唇","发"],"a":1,"e":"肝在体合筋，其华在爪，爪为筋之余，故称筋之余。发为血之余，面、唇、毛亦各有五脏所属。"},{"q":"下列关于实的叙述，错误的是","o":["外感邪盛","肌肤经络闭塞","气机升降失调","脏腑功能亢进","气血壅滞瘀结"],"a":2,"e":"实指邪气亢盛，见肌肤经络闭塞、脏腑功能亢进、气血壅滞瘀结。气机升降失调属气机失常，非虚实之实。"},{"q":"胃下垂、肾下垂、子宫脱垂、脱肛等症的病机，可能性最大的是","o":["气逆","气陷","气闭","气脱","气滞"],"a":1,"e":"气陷为气虚升举无力，清阳不升、内脏失于维系，故见胃、肾、子宫下垂及脱肛。气逆主上升太过。"},{"q":"可用阴阳相互转化解释的是","o":["寒极生热","阴损及阳","寒者热之","阴病治阳","阴中求阳"],"a":0,"e":"寒极生热指寒证发展到极点可转化为热证，属阴阳相互转化。阴损及阳、阴病治阳、阴中求阳均本于互根。"},{"q":"根据五行学说，“肝火犯肺”属于","o":["子病犯母","相克","相乘","相侮","母病及子"],"a":3,"e":"肝属木，肺属金，金克木，肝火亢盛反侮肺金，故肝火犯肺属相侮。相乘为金气过盛而乘木。"},{"q":"金元时期，提出“病由邪生”、“邪去则正安”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":2,"e":"张从正主张病由邪生、邪去则正安，治以汗吐下攻邪，为攻邪派代表。刘完素主火热论，李东垣主脾胃论。"},{"q":"《素问·生气通天论》所谓：“阴平阳秘，精神乃治”，是指","o":["阴阳的对立制约关系正常","阴阳的依存互根关系正常","阴阳的消长平衡关系正常","阴阳的相互转化关系正常","阴阳的交感互藏关系正常"],"a":2,"e":"阴平阳秘指阴阳消长处于相对平衡协调的状态，精神活动由此正常，故属消长平衡关系正常。"},{"q":"关于邪郁化火论述错误的是","o":["可由风、寒、燥、湿等外邪引起","可由痰饮、瘀血等病理产物引起","因为人身有阳气，所以邪郁必然化火","其基本机制是人体阳气郁滞","邪郁化火可致疮疡"],"a":2,"e":"邪郁化火以阳气郁滞为基本机制，须邪阻气机、郁久化热方成，并非人身有阳气则邪郁必然化火，故该项错误。"},{"q":"人的生命源于","o":["阴阳交感","阴阳互根","阴阳对立","阴阳转化","阴阳消长"],"a":0,"e":"阴阳交感指阴阳二气在运动中相互感应交合，是万物化生及生命起源的根本，故人的生命源于阴阳交感。"},{"q":"体型中最有代表性的差异是","o":["肥瘦","皮肉之厚薄","肤色","身高","腠理之坚松"],"a":0,"e":"体质差异中，肥瘦最能反映形体的强弱与阴阳的偏盛偏衰，故为体型最有代表性的差异。肤色、身高居次。"},{"q":"人体之精分藏于五脏，但主要藏于","o":["肝","心","脾","肺","肾"],"a":4,"e":"精分藏于五脏，而肾受五脏六腑之精而藏之，故人体之精主要藏于肾，肾为封藏之本、先天之本。"},{"q":"五脏六腑之大主是","o":["心","肺","脾","肝","肾"],"a":0,"e":"心藏神，为君主之官，主宰五脏六腑的生理活动与精神意识，故称五脏六腑之大主。肺为相傅之官。"},{"q":"《小儿药证直诀》的作者是","o":["王叔和","皇甫谧","孙思邈","钱乙","陈无择"],"a":3,"e":"《小儿药证直诀》为北宋钱乙所著，创立小儿五脏辨证，是现存最早的系统儿科专著。王叔和著《脉经》。"},{"q":"虚实病机中“虚”的内涵是","o":["邪气微弱","邪气亢盛","正气不足","正气郁闭","正邪相持"],"a":2,"e":"虚指正气不足、抗病能力低下，见神疲乏力、气短、脉弱等。邪气亢盛为实，正邪相持为实证病机。"},{"q":"疾病的发生、发展与转归主要取决于","o":["邪正的盛衰","合理的饮食","禀赋的强弱","邪气的性质","感邪的轻重"],"a":0,"e":"疾病的发生、发展与转归取决于邪正双方力量的消长盛衰，正胜邪却则病退，邪胜正衰则病进。"},{"q":"卫气虚弱，与下列哪一项关系最密切","o":["肺气虚","脾气虚","心气虚","肾气虚","肝气虚"],"a":0,"e":"卫气由脾胃水谷之气化生，赖肺宣发敷布于肌表，肺气虚则宣发无力、卫表不固，故与肺气虚关系最密切。"},{"q":"易于感冒，是气的什么功能减弱的表现","o":["推动作用","温煦作用","防御作用","固摄作用","气化作用"],"a":2,"e":"气能防御外邪入侵，卫气充盛则肌表固密、邪不可干；防御功能减弱则易感外邪而反复感冒。"},{"q":"属于“实则泻其子”治则的治疗是","o":["肝火旺泻心火","脾火旺泻胆火","肝火旺泻脾","肝火旺泻肺","肺热泻大肠"],"a":0,"e":"实则泻其子指本脏邪实而泻其子脏，肝属木、心属火，木生火，故肝火旺泻心火。泻脾、泻肺属乘侮论治。"},{"q":"清气与水谷之气结合关系到","o":["元气的生成","宗气的生成","营气的生成","卫气的生成","全身之气的生成"],"a":1,"e":"宗气由肺吸入的自然清气与脾胃化生的水谷之气相合而成，聚于胸中，故二者结合关系宗气的生成。"},{"q":"生命形成的根本在于","o":["阴阳互根","父母之精交合","阴阳对立","阴阳转化","阴阳消长"],"a":1,"e":"父母之精交合、阴阳二气交感而构胎成形，故生命形成的根本在于父母之精交合。阴阳互根言其依存关系。"},{"q":"在疾病传变的过程中，从太阳传至太阴是","o":["循经传","越经传","表里传","逆传","顺传"],"a":1,"e":"六经传变中不按循经次序而越经相传为越经传，太阳直传太阴跨越阳明、少阳，故属越经传。"},{"q":"对全身络脉起主导作用的是","o":["正经","奇经","阳跷脉、阴跷脉","阳维脉、阴维脉","别络"],"a":4,"e":"别络为从经脉分出之支脉，十二经及任督各一支，加脾之大络，网络全身，对全身络脉起主导作用。"},{"q":"临床上治疗瘀血病证时，在使用活血化瘀药物的同时会加入行气的药物，其理论依据是","o":["气能生血","气能行血","气能摄血","血能载气","血能养气"],"a":1,"e":"气能行血，气行则血行，气滞或气虚均致血行迟滞，故活血化瘀方中配行气药以助血运，即气能行血。"},{"q":"脾在时为","o":["春","长夏","秋","冬","夏"],"a":1,"e":"脾属土，五季配属中长夏湿热最盛，与脾土相应，故脾在时为长夏。春属肝木，夏属心火，秋属肺金，冬属肾水。"},{"q":"肝在时为","o":["春","长夏","秋","冬","夏"],"a":0,"e":"肝属木，与春季相通应，春气主升发，与肝主升发条达之性相合，故肝气旺于春，肝在时为春。"},{"q":"人体根本之气是","o":["元气","卫气","营气","宗气","经络之气"],"a":0,"e":"元气由肾所藏之精化生，是人体最根本、最重要的气，能推动和调控人体生长发育及脏腑经络的生理活动。"},{"q":"“壮水之主，以制阳光”是指","o":["阴中求阳","阳中求阴","阳病治阴","阴病治阳","治寒以热"],"a":2,"e":"壮水之主，以制阳光即滋阴以制阳，适用于阴虚不能制阳所致的虚热证，属阳病治阴，而非阴病治阳。"},{"q":"肾精化为生殖之精以施泄，依靠于","o":["肾阳推动","肾阴滋润","天癸促发","脾胃运化","肝气疏泄"],"a":2,"e":"肾精充盛到一定程度则产生天癸，天癸促发生殖之精的化生与施泄，故肾精化为生殖之精依靠天癸促发。"},{"q":"在疾病传变过程中，由太阴传至阳明是","o":["循经传","越经传","表里传","直中","合病"],"a":2,"e":"太阴与阳明互为表里之经，病邪由太阴传入阳明，是循表里相合之序相传，故称表里传，与越经传不同。"},{"q":"下列哪项是对肺的主要生理机能的高度概括","o":["肺主气司呼吸","肺主行水","肺气宣降","肺朝百脉","肺主治节"],"a":4,"e":"肺主治节是对肺主气司呼吸、主宣发肃降、通调水道、朝百脉等全部生理功能的高度概括，为肺功能的总括。"},{"q":"阴阳学说是研究阴阳的内涵及其","o":["运动状态","静止状态","标示的事物现象","运动变化规律","辨证法"],"a":3,"e":"阴阳学说是研究阴阳的内涵及其运动变化规律，并用以解释自然界和人体生命活动变化规律的学说。"},{"q":"血之余为","o":["骨","发","齿","血海","唇"],"a":1,"e":"发为血之余，发的生长与荣枯有赖血的濡养，血盛则发荣，血衰则发枯脱落；齿为骨之余，爪为筋之余。"},{"q":"呼吸与五脏密切相关，特别是","o":["肝","心","脾","肺","肾"],"a":3,"e":"肺主气司呼吸，为体内外气体交换的场所，肺气宣降有序则呼吸调匀，故呼吸与肺的关系最为直接密切。"},{"q":"临床上，小儿常易感受外邪或因饮食所伤而发病，其主要因素是","o":["地域因素","气候因素","体质因素","生活、工作环境","精神状态"],"a":2,"e":"小儿脏腑娇嫩、形气未充，体质状态决定其对病邪的易感性，故易感受外邪或为饮食所伤而发病。"},{"q":"“痰阻于胃”可见的临床症状是","o":["喘咳咯痰","胸闷心悸","恶心呕吐","半身不遂","眩晕昏冒"],"a":2,"e":"痰浊阻滞于胃，胃失和降、气机上逆，故见恶心呕吐；喘咳咯痰为痰阻于肺，胸闷心悸为痰阻于心。"},{"q":"明清时期，首创“戾气”说的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":4,"e":"吴又可在《温疫论》中首创戾气学说，认为温疫由戾气自口鼻而入所致，而非一般六淫外邪。"},{"q":"用于阳盛格阴的治则是","o":["寒因寒用","热因热用","通因通用","热者寒之","寒者热之"],"a":0,"e":"阳盛格阴为真热假寒，治当寒因寒用，即以寒凉药治其假寒之象，而直折其内盛之热。，与阴病治阳相对"},{"q":"心在窍为","o":["爪","唇","鼻","口","舌"],"a":4,"e":"心在窍为舌，舌为心之苗，心经别络上系舌本，心血充盈则舌体红活荣润，故舌的色泽形态可反映心之功能。"},{"q":"天人合一的思维方式属于","o":["象思维","系统思维","变易思维","逻辑思维","辨证思维"],"a":1,"e":"天人合一强调人与自然环境、社会环境是一个整体，人与天地相应，属中医学系统思维方式的体现。"},{"q":"下列除哪项外均属于影响体质的先天因素","o":["父母的体质","父母的生育年龄","母体孕期调养","家庭居住地","母体妊娠期疾病"],"a":3,"e":"父母体质、生育年龄、孕期调养与妊娠期疾病均属影响体质的先天因素，家庭居住地则属后天环境因素。"},{"q":"容易导致人体阴阳失调的饮食因素有","o":["饮食不洁","饮食过饱","五味偏嗜","饮食过饥","寒热偏嗜"],"a":4,"e":"饮食寒热偏嗜易损伤阴阳，过食生冷伤阳、过食辛热耗阴，日久则致阴阳失调而为病。，故当饮食有节、寒温适中"},{"q":"明清时期，改正了古籍中的某些解剖错误，并发展了瘀血理论的医家是","o":["吴又可","赵献可","叶天士","薛雪","王清任"],"a":4,"e":"王清任著《医林改错》，改正古籍中某些解剖错误，并创瘀血理论，重视气血辨治，为清代著名医家。"},{"q":"在肺的生理功能中与尿液生成关系密切的是","o":["肺朝百脉","肺气宣发","肺气肃降","肺为娇脏","肺主气司呼吸"],"a":2,"e":"肺气肃降能通调水道、下输膀胱，使水液下趋于肾与膀胱，为尿液生成提供来源，故与尿生成关系最密切。"},{"q":"以下可用阴阳互相转化来解释的是","o":["阳虚则寒","重阴必阳","寒者热之","阴损及阳","阴盛则阳病"],"a":1,"e":"重阴必阳指阴发展到极点可转化为阳，属阴阳相互转化；阴损及阳、阴盛则阳病则分属互根与制约失常。"},{"q":"下列事物中属阳的是","o":["左","右","北","浊","寒"],"a":0,"e":"阳的属性为向上、向外、运动、明亮、温热，方位之中左、上、南属阳，右、下、北属阴，故左属阳。"},{"q":"“内风”与何脏关系最为密切","o":["心","肝","脾","肺","肾"],"a":1,"e":"肝为风木之脏，主升主动，内风多由肝阳化风、热极生风、阴虚风动所致，故与肝关系最为密切。"},{"q":"脏腑病机理论的指导思想是","o":["阴阳失调","五行失常","整体观念","邪正盛衰","标本缓急"],"a":2,"e":"脏腑病机以整体观念为指导思想，重视脏腑之间以及脏腑与形体官窍之间的整体联系与相互影响。"},{"q":"下列哪项不属于烧烫伤","o":["沸水烫伤","雷电击伤","高温灼伤","蒸汽灼伤","烈火烧伤"],"a":1,"e":"烧烫伤指沸水、蒸汽、烈火、高温等所致的损伤；雷电击伤属电击伤，不属烧烫伤范畴。，当属意外伤害"},{"q":"精血同源可归属于","o":["心与肾的关系","脾与肾的关系","肺与肾的关系","肝与肾的关系","心与肝的关系"],"a":3,"e":"肝肾同居下焦，肝藏血、肾藏精，精血相互资生转化，故精血同源归属肝与肾的关系。，故称肝肾同源"},{"q":"《素问•六节藏象论》中，“封藏之本”所指的是","o":["心","肺","脾","肝","肾"],"a":4,"e":"肾主封藏，藏精而不妄泻，为精气所藏之处，故《素问·六节藏象论》称肾为封藏之本。，为五脏六腑精气所聚"},{"q":"下列选项中，属于药邪形成原因错误的是","o":["用药过量","炮制不当","配伍不当","用法不当","言语不当"],"a":4,"e":"药邪成因包括用药过量、炮制不当、配伍不当、用法不当；言语不当属情志致病因素。，与药邪无关"},{"q":"阳偏衰则会出现","o":["虚热证","实热证","实寒证","寒热错杂","虚寒证"],"a":4,"e":"阳偏衰即阳虚，阳气不足则温煦推动无力，阴相对偏盛，故见畏寒肢冷、喜温之虚寒证。，治宜温补阳气"},{"q":"下列哪项不属于瘀血致病的临床表现","o":["肌肤甲错","出血紫黯","刺痛拒按","唇甲色淡","肿块固定"],"a":3,"e":"瘀血可见刺痛拒按、肿块固定、出血紫黯、肌肤甲错；唇甲色淡为血虚失于濡养之象。，为瘀血内阻之征"},{"q":"明清时期，认为温病的病因是戾气，而非一般六淫的医学家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":4,"e":"吴又可提出温病病因是戾气而非六淫，强调戾气从口鼻而入，其说见于《温疫论》。，强调疫气有别于六淫"},{"q":"经络系统中，有加强经脉在体表联系和渗灌气血等作用的是","o":["经脉","络脉","浮络","孙络","别络"],"a":1,"e":"络脉由经脉分出，纵横交错网络全身，具有加强经脉在体表联系和渗灌气血的作用。，故络脉细小而众多"},{"q":"疾病发生的内在根据是","o":["邪气盛","正气虚","阴阳失调","寒热偏胜","邪正盛衰"],"a":1,"e":"正气不足是疾病发生的内在根据，邪气是发病的重要条件，故有正气存内、邪不可干之说。"},{"q":"使用催吐剂，正确的调理方法是","o":["糜粥自养","食辛辣食物","硬性食物","寒凉食物","热性食物"],"a":0,"e":"服催吐剂后胃气受损、胃中空虚，宜糜粥自养以渐复胃气，忌辛辣、寒凉、硬食及热性食物。"},{"q":"“水火既济”是属于","o":["心肾关系","肝肾关系","脾肾关系","肺肾关系","心肺关系"],"a":0,"e":"水火既济指心火下降于肾、肾水上济于心，心肾水火相交为用，属心与肾的关系。，为心肾相交之要"},{"q":"下列各项在五行中属“土”的是","o":["收","苦","肉","风","鼻"],"a":2,"e":"五行属土者为肉、甘味、黄色、宫音、思、湿；收属金，苦属火，风属木，鼻属金。，此为五行归类之常"},{"q":"肺主气的功能取决于","o":["司呼吸","宗气的生成","全身气机的调节","朝百脉","主治节"],"a":0,"e":"肺主气包括主呼吸之气与主一身之气，其功能取决于司呼吸，呼吸调匀则气的生成与运行正常。"},{"q":"下列哪项在心主血脉中起关键作用","o":["心血充盈","心气充沛","心神安宁","心搏如常","脉道通利"],"a":1,"e":"心主血脉有赖心气推动，心气充沛则心搏有力、血行不息，为心主血脉中的关键环节。，为血行的动力"},{"q":"十二经脉，内属于腑脏，外络的组织是","o":["肢节","下肢部","背部","胸胁部","腹部"],"a":0,"e":"十二经脉内属于脏腑，外络于肢节，沟通内外表里，使人体成为有机整体，故外络的组织为肢节。"},{"q":"能够辅助心行血于周身的是肺的哪项生理机能","o":["肺朝百脉","肺为华盖","肺主气司呼吸","肺主行水","肺气肃降"],"a":0,"e":"肺朝百脉，即全身血液经百脉汇聚于肺，行气体交换后再布散周身，故能助心行血。，即肺助心行血"},{"q":"心为“君主之官”的理论依据是","o":["心总统意志","心主血脉","心主神志","心主情志","心总统魂魄"],"a":2,"e":"心主神志，为五脏六腑之大主，人体生命活动与精神意识皆由心主宰，故称君主之官。，主不明则十二官危"},{"q":"脏腑中“主津”作用的是","o":["脾","肾","大肠","小肠","三焦"],"a":2,"e":"大肠主津，能吸收糟粕中的水分使其成形为粪便；小肠主液，吸收水谷精微中稠厚部分，二者不可混淆。"},{"q":"金元四大家中，在治疗中善用寒凉清热的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素主张六气皆从火化，治病善用寒凉清热，为金元四大家中寒凉派的代表人物。，为寒凉派之宗"},{"q":"“吐下之余，定无完气”病机理论依据是","o":["气能生津","气能行津","津能载气","血能载气","津血同源"],"a":2,"e":"津液是气的载体，吐下太过则津液大量丢失，气随津脱，故有吐下之余、定无完气之说。，故气随液脱"},{"q":"经络系统中的主干线，数量较少者是","o":["经脉","络脉","浮络","孙络","别络"],"a":0,"e":"经脉是经络系统的主干线，纵行分布而数量较少；络脉分支细小，纵横交错，数量众多。，故称经脉为干"},{"q":"既属于“五体”，又属奇恒之腑的是","o":["脑","脉","女子胞","髓","胆"],"a":1,"e":"脉为气血运行的通道，既属五体之一，又因其形态中空、似腑非腑而列为奇恒之腑。，故脉兼属两者"},{"q":"创立“引经报使”理论的医家是","o":["刘完素","张元素","孙思邈","张子和","张介宾"],"a":1,"e":"张元素创立引经报使理论，阐明药物对脏腑经络的选择性作用，著《脏腑标本寒热虚实用药式》。"},{"q":"生气之主指的是","o":["肝","心","脾、胃","肺","肾"],"a":3,"e":"肺主一身之气，吸入自然界清气并与水谷精气结合生成宗气而布散全身，故称生气之主。，为气之主"},{"q":"下列各项，与肺主通调水道功能关系最密切的是","o":["气机的调节","朝百脉","主宣发与肃降","司呼吸","宗气的生成"],"a":2,"e":"肺主通调水道依赖宣发与肃降，宣发使水液外达皮毛化为汗，肃降使水液下输肾与膀胱。，故称肺为水之上源"},{"q":"胃的主要病机特点是","o":["受纳腐熟功能失常","贮藏排泄功能失常","消化吸收功能失常","传导功能失常","气化功能失常"],"a":0,"e":"胃主受纳腐熟水谷，其病机特点为受纳腐熟功能失常，可见胃脘胀痛、纳呆、嗳腐吞酸。，治当和胃降逆"},{"q":"与防止出血密切相关的两脏是","o":["心与肝","肝与脾","心与脾","肝与肾","肺与肝"],"a":1,"e":"肝藏血、脾统血，肝气条达则血不妄行，脾气健运则血循常道，故两脏与防止出血密切相关。"},{"q":"在气的生成过程中，尤为重要的是","o":["肺的呼吸功能","脾胃的运化功能","肾的闭藏功能","肺肾的协调功能","心的主血功能"],"a":1,"e":"气的生成源于水谷精气与吸入清气，脾胃运化水谷为气血生化之源，故在气的生成中尤为重要。"},{"q":"六淫中最易伤肺的邪气是","o":["风邪","寒邪","燥邪","暑邪","热邪"],"a":2,"e":"燥为秋令主气，其性干涩易伤津液，肺喜润恶燥且外合皮毛，故六淫之中燥邪最易伤肺。，故秋燥多犯肺卫"},{"q":"六淫中致病后可出现各种秽浊症状的邪气是","o":["风邪","寒邪","燥邪","湿邪","热邪"],"a":3,"e":"湿性重浊黏滞，致病多见头身困重、面垢眵多、分泌物秽浊、舌苔腻等秽浊症状。，其性类水而属阴邪"},{"q":"患者，男，40岁。素有高血压病史，现症见眩晕耳鸣，面红头胀，腰膝酸软，失眠多梦，时有遗精或性欲亢进，舌红，脉沉弦细。其病机是","o":["阴虚内热","阴损及阳","阴虚阳亢","阳损及阴","阴虚火旺"],"a":2,"e":"眩晕耳鸣、面红头胀、腰膝酸软、舌红脉沉弦细，为阴亏于下、阳亢于上之阴虚阳亢。，治宜滋阴潜阳"},{"q":"横骨压痛，提示","o":["月经不调","肠痈","高血压","肺脏疾病","脾虚"],"a":0,"e":"横骨位于耻骨联合处，为冲任二脉所过之处，按之压痛多提示月经不调等胞宫病变。，属下焦按诊之要"},{"q":"真实假虚证的治疗原则应是","o":["祛邪兼扶正","扶正兼祛邪","先祛邪，后扶正","单独祛邪","先扶正，后祛邪"],"a":3,"e":"真实假虚为邪气盛实而反见假虚之象，治当单独祛邪，邪去则正安，不可误用补益。，即所谓邪去正安"},{"q":"八纲辨证的总纲是","o":["虚实","阴阳","表里","寒热","真假"],"a":1,"e":"八纲中表里、寒热、虚实皆可分属阴阳，阴阳可概括其余六纲，故为八纲辨证的总纲。，故称其为总纲"},{"q":"下列各组经脉中，从胸腔走向手指末端的是","o":["心肝肾经","心肺心包经","胆胃三焦经","心胆小肠经","肺脾胆经"],"a":1,"e":"手三阴经从胸走手、止于手指末端，即手太阴肺经、手少阴心经、手厥阴心包经。，与手三阳经相交接"},{"q":"气在中医学理论体系中比较完整的概念是","o":["泛指机体的生理功能","构成世界的基本物质","构成人体和维持人体生命活动的最基本物质","指人体抗病能力","维持人体生命活动的基本物质"],"a":2,"e":"气是构成人体和维持人体生命活动的最基本物质，兼具物质与功能双重含义，为生命活动的动力。"},{"q":"属于六经病机中三阳病的病机特征的是","o":["多属热、属实","多属虚、属寒","多属寒、属实","多属热、属虚","多正虚、邪盛"],"a":0,"e":"三阳病多属热、属实，正气尚充而抗邪有力；三阴病多属虚、属寒，为六经病机的基本特征。"},{"q":"根据五行学说，水火既济是指","o":["心肾相交","肝脾调和","肝肾同源","肺肾相生","脾肾互济"],"a":0,"e":"五行中心属火、肾属水，水火既济即心火下降以温肾、肾水上济以制心火，故指心肾相交。"},{"q":"称为“髓海”的是","o":["太阳经","脑","肾","脉","肝"],"a":1,"e":"脑由髓汇聚而成，居于颅内，肾精生髓上充于脑，髓充则脑健，故《灵枢》称脑为髓海。，为元神之府"},{"q":"在影响疾病传变的因素中起决定作用的是","o":["邪正斗争","环境因素","生活因素","诊治因素","心理因素"],"a":0,"e":"邪正斗争贯穿疾病始终，决定其发展与传变，在影响传变的诸因素中起决定作用。，故为传变之枢"},{"q":"推动人体生长发育及脏腑生理活动的气是","o":["元气","宗气","营气","卫气","动气"],"a":0,"e":"元气发于肾，由肾精化生，推动人体生长发育、温煦激发脏腑生理活动，为生命活动的原动力。"},{"q":"脏腑之中，被称为“孤府”的是","o":["胆","胃","三焦","脾","脑"],"a":2,"e":"三焦为六腑之一，主持诸气、通调水道，遍及胸腹腔，因无表里配偶之脏，故称孤府。，故有孤府之称"},{"q":"属于奇恒之腑，下列错误的是","o":["脑","三焦","胆","脉","骨"],"a":1,"e":"奇恒之腑包括脑、髓、骨、脉、胆、女子胞六者，形态似腑而功能似脏，三焦则属六腑。，当予鉴别"},{"q":"下列哪项是胃的生理功能","o":["水谷精微的转输","水谷的受纳和腐熟","水液的吸收和转输","脏器位置的维系","血液的统摄"],"a":1,"e":"胃主受纳、腐熟水谷，故其生理功能为水谷的受纳和腐熟，与脾主运化相合而为后天之本。"},{"q":"中医饮食养生所提倡的，下列错误的是","o":["药膳保健","注意饮食卫生","提倡饮食有节","克服饮食偏嗜","强调高营养饮食"],"a":4,"e":"中医饮食养生主张饮食有节、克服偏嗜、注意卫生并用药膳保健，不强调高营养饮食。，此为中医食养之要"},{"q":"嗜酒可引起的是","o":["寒从中生","聚湿生痰","耗伤肺津","食滞胃肠","心火亢盛"],"a":1,"e":"嗜酒助湿生热，损伤脾胃运化之职，水湿不化而聚而成痰，故嗜酒易致聚湿生痰。，故当少饮为宜"},{"q":"五行学说中“火”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":1,"e":"五行中火曰炎上，其性温热升腾；木曰曲直，金曰从革，水曰润下，土爰稼穑。，此五者各具其性"},{"q":"心主血脉与哪一项机能密切相关","o":["心藏神","心脉畅通","心神清明","心气充盈","心血充足"],"a":0,"e":"心主血脉与心藏神密切相关，血脉为神志活动的物质基础，心神又驭气以推动血行。，二者相互为用"},{"q":"具有“泻而不藏”特点的是","o":["五脏","六腑","脏腑","奇恒之腑","以上均非"],"a":1,"e":"六腑传化物而不藏，实而不满，故具泻而不藏之性；五脏藏精气而不泻，满而不实。，此脏腑功能之别"},{"q":"下列除哪项外，均属于疾病的复发诱因","o":["重感致复","食复","过逸","药物","情志致复"],"a":2,"e":"疾病复发诱因包括重感致复、食复、劳复、药复、情志致复等，过逸属致病因素而非复发诱因。"},{"q":"下列各项，不属肝主疏泄功能的是","o":["调畅气机","调畅情志","促进骨骼发育","促进脾胃的运化","促进血液运行"],"a":2,"e":"肝主疏泄能调畅气机与情志、促进脾胃运化及血液运行；促进骨骼发育为肾藏精生髓之功。"},{"q":"金元四大家中“寒凉派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素力倡火热致病，认为六气皆从火化、五志过极皆能化火，用药偏于寒凉，后世称寒凉派。"},{"q":"心的主要生理功能是","o":["主藏血","主神志","主运化","主统血","主疏泄"],"a":1,"e":"心主血脉、主藏神，二者中尤以主神志为要，主宰全身生命活动，故为君主之官。，故为五脏六腑之大主"},{"q":"“见肝之病，知肝传脾，当先实脾”的治法属于","o":["控制疾病传变","提高抗邪能力","避免病邪侵入","早期诊断治疗","防止疾病发生"],"a":0,"e":"见肝之病知肝传脾而先实其脾，属已病之后先安未受邪之地、防止病邪深入传变，即控制疾病传变。"},{"q":"在一定条件下，“五志过极”和“五气”皆可化","o":["风","寒","湿","燥","火"],"a":4,"e":"五志过极与风寒暑湿燥五气在一定条件下皆可化火，故有五气化火、五志化火之说。，故火热内生"},{"q":"根据五行学说，水之“所胜”是","o":["木","水","金","火","土"],"a":3,"e":"五行相克中水克火，克我者为所不胜，我克者为所胜，故水之所胜为火，所不胜为土。，此五行生克之序"},{"q":"肾在时为","o":["春","长夏","秋","冬","夏"],"a":3,"e":"肾属水，与冬季相通应，冬气闭藏，与肾主藏精之性相合，故肾气旺于冬，肾在时为冬。，故冬宜养肾"},{"q":"称为“水谷气血之海”的是","o":["脾","大肠","小肠","胃","三焦"],"a":3,"e":"胃受纳腐熟水谷，化生水谷精微以养周身，为气血化生之源，故称水谷气血之海，又称太仓。"},{"q":"金元四大家中“补土派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":4,"e":"李东垣重视脾胃，强调脾胃为元气之本、升降之枢，创补中益气汤等方，为补土派代表。，后世尊为补土宗师"},{"q":"中医学构建经脉“子午流注”理论，所体现的思维方式是","o":["整体宏观","天人合一","恒动变化","动静相召","辨证唯物"],"a":1,"e":"子午流注按昼夜时辰推算经气盛衰流注，体现人与天地相应，属天人合一的思维方式。，为时间医学之肇端"},{"q":"小肠的主要生理功能是","o":["主运化","主通调水道","主受纳","主腐熟水谷","主泌别清浊"],"a":4,"e":"小肠受盛化物、泌别清浊，清者上输于脾，浊者下传大肠，故其主要生理功能为泌别清浊。"},{"q":"能调节十二经气血的经脉是","o":["阳维脉","阳跷脉","阴跷脉","冲脉","督脉"],"a":3,"e":"冲脉上至于头、下至于足，贯穿全身，为十二经脉之海，能蓄溢和调节十二经气血的盛衰。"},{"q":"提出“五志过极，皆为热甚”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素提出五志过极皆为热甚，认为情志所伤多从火化，强调火热为病之要，治多寒凉。，其说本于火热论"},{"q":"人体热量来源，主要是","o":["气","血","精","液","津"],"a":0,"e":"气属阳而主温煦，能温暖机体，人体热量主要来源于气的温煦作用，故热量来源主要是气。"},{"q":"阴胜则阳病指的是","o":["阳有余耗伤阴精","阴不足阳相对亢胜","阳不足阴相对亢胜","阴有余损伤阳气","阴虚损阳无所依"],"a":3,"e":"阴胜则阳病指阴气偏盛，制约并损伤阳气，致阳气相对不足而为病，属阴阳对立制约失常。"},{"q":"肝气逆是指","o":["肝气升发太过","肝气应升反降","肝气郁遏不达","肝气横犯脾胃","肺金乘克肝木"],"a":0,"e":"肝气逆即肝气升发太过、气机上逆而不降，可见头痛面红、目赤、急躁易怒，甚则呕血。，治当平肝降逆"},{"q":"夺汗者无血，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","气能行血"],"a":1,"e":"汗为津液所化，津能生血，汗出过多则津液耗伤而血源不足，故有夺汗者无血之说。，二者同源而异名"},{"q":"后天之本指","o":["脾","肝","心","肾","肺"],"a":0,"e":"脾主运化水谷精微，为气血生化之源，人出生后所需营养皆赖脾胃化生，故称后天之本。，与先天之本相对"},{"q":"能够导致“心无所倚，神无所归，虑无所定”情绪的是","o":["惊","怒","思","喜","悲"],"a":0,"e":"惊则气乱，心气紊乱而神不守舍，故见心无所倚、神无所归、虑无所定，治当安神定志。，故情志之伤首责于心"},{"q":"气滞宜","o":["益气","活血","降逆","行气","补气"],"a":3,"e":"气滞当行气解郁，气逆宜降逆，气陷宜升提，气虚宜益气，故气滞之治法为行气。，此治法之常"},{"q":"血虚引起气虚病变的理论根据是","o":["血能养气","气能行血","气能摄血","气能生血","血能载气"],"a":0,"e":"血为气之母，能养气载气，血虚则气失濡养而随之亦虚，故血虚可引起气虚病变。，故气血互为其根"},{"q":"不属于调摄情绪法的是哪一项","o":["节制法","疏泄法","转移法","清静养神","情志制约法"],"a":3,"e":"调摄情绪法包括节制法、疏泄法、转移法、情志制约法；清静养神属修身养性之法，不属调摄情绪。"},{"q":"与肺主一身之气关系最密切的是","o":["元气","心气","营气","卫气","宗气"],"a":4,"e":"宗气聚于胸中，走息道以行呼吸，贯心脉以行气血，其生成与肺密切相关，故肺主一身之气最赖宗气。"},{"q":"肝在体合","o":["筋","脉","肉","皮","骨"],"a":0,"e":"肝藏血以濡养筋膜，肝血充盈则筋力强健、屈伸灵活，故肝在体合筋，其华在爪。，其华在爪"},{"q":"“用寒远寒，用热远热”，属于","o":["因病制宜","因地制宜","因人制宜","因时制宜","因证制宜"],"a":3,"e":"用寒远寒、用热远热指用寒药应避寒冷时令，用热药应避炎热时令，属因时制宜。，此即因时用药之法"},{"q":"火热邪气致病，症见头痛、耳鸣、咽喉红肿疼痛、唇口糜烂等症状，是由于","o":["热邪扰乱心神","热邪易致动血","火热之邪燔灼趋上","热邪伤津耗气","热邪易致生风"],"a":2,"e":"火热之性燔灼趋上，易上攻头面清窍，故见头痛、耳鸣、咽喉红肿疼痛、唇口糜烂。，故火热之病多见面部症状"},{"q":"与呼吸功能关系最密切的两脏是","o":["肺与肾","肺与肝","肺与脾","肝与脾","心与肝"],"a":0,"e":"肺主呼气、肾主纳气，肺为气之主、肾为气之根，二者协调则呼吸调匀，故与呼吸关系最密切。"},{"q":"阴阳的转化过程是","o":["量变过程","质变过程","两者都是","平衡过程","两者都不是"],"a":1,"e":"阴阳转化是阴阳属性向其对立面发生根本改变，属质变过程；阴阳消长则属量变。，故转化以质变为要"},{"q":"心脏精气的盛衰可以通过面部色泽来辨别主要是因为","o":["心在液为汗","心在志为喜","心在体合脉","心其华在面","心主通明"],"a":3,"e":"心其华在面，面部血脉最为丰富，心气心血之盛衰可外现于面色泽，故望面色可知心力。，故望色可察心之盛衰"},{"q":"六淫中具有病程长，难以速愈的邪气是","o":["寒邪","火邪","风邪","暑邪","湿邪"],"a":4,"e":"湿性黏滞重浊，易阻遏气机、胶着难解，故湿邪致病病程较长，缠绵难愈而反复发作。，治当化湿运脾"},{"q":"以下各项属于五脏之外的是","o":["心","肺","脾","肝","女子胞"],"a":4,"e":"五脏为心、肺、脾、肝、肾，女子胞虽位于下焦，然属奇恒之腑，不属五脏之列。，故当别于五脏"},{"q":"属于“七冲门”，下列错误的那项是","o":["吸门","飞门","户门","气门","阑门"],"a":3,"e":"七冲门为飞门、户门、吸门、贲门、幽门、阑门、魄门，气门指汗孔，不属七冲门。，故当识其名实"},{"q":"根据五行学说，“木亢侮金”是指","o":["相生","相克","相乘","相侮","制化"],"a":3,"e":"木亢侮金指木气过盛，反侮其所不胜之金，属五行相侮，与木乘土之相乘不同。，故属相侮之列"},{"q":"下列适用于“阴盛格阳证”的治则是","o":["寒因寒用","热因热用","通因通用","热者寒之","寒者热之"],"a":0,"e":"官方答案为【寒因寒用】，但依据教材，正确答案为【热因热用】。阴盛格阳属真寒假热，治当以热治热，即热因热用；寒因寒用适用于阳盛格阴。"},{"q":"首先提及七情可以致病的典籍是","o":["《伤寒论》","《三因极一病证方论》","《难经》","《内经》","《诸病源候论》"],"a":3,"e":"《内经》最早记载七情致病，如怒伤肝、喜伤心等，奠定情志致病理论的基础。，为情志学说之源"},{"q":"下列属于正治法则的是","o":["标本兼治","塞因塞用","寒者热之","因人制宜","寒因寒用"],"a":2,"e":"正治即逆证候性质而治，寒者热之、热者寒之属正治；寒因寒用、塞因塞用则属反治。，二者治法相反"},{"q":"“见肝之病，先实其脾气”，这种治疗属","o":["治病求本","既病防变","早期治疗","扶正祛邪","审因论治"],"a":1,"e":"见肝之病先实其脾气，即已病之后先安未受邪之脏以杜其传变，属既病防变而非早期治疗。"},{"q":"脏与脏之间主要表现为阴阳水火互济互制关系的是","o":["心与肺","心与肾","肝与肾","脾与肾","肺与脾"],"a":1,"e":"心属火在上、肾属水在下，心火下降、肾水上济，故表现为阴阳水火互济互制的关系。，故为上下相济之脏"},{"q":"在藏象、脉学和针灸等方面对《黄帝内经》进行了补充的著作是","o":["《脉经》","《针灸甲乙经》","《难经》","《伤寒杂病论》","《神农本草经》"],"a":2,"e":"《难经》在藏象、脉学、针灸等方面补充发挥《黄帝内经》，尤以脉诊独取寸口著称。，为后世脉学之宗"},{"q":"胆属于","o":["脏","腑","奇恒之腑","既是腑，又是奇恒之腑","既是脏，又是奇恒之腑"],"a":3,"e":"胆属六腑，因其藏精汁而不传化糟粕，形态似腑、功能似脏，故又列于奇恒之腑。，故当分而识之"},{"q":"据五行学说，佐金平木法的适应证是","o":["肝脾不调证","肝火犯肺证","肝肾阴虚证","肝火上炎证","肝胆湿热证"],"a":1,"e":"按五行相克，佐金平木即清肃肺金以抑制偏亢之肝木，适用于肝火犯肺之证。，与滋水涵木不同"},{"q":"预防的基本原则源于以下哪种理论","o":["治未病","未病先防","既病防变","病后防复","先安未受邪之地"],"a":0,"e":"中医预防以治未病为基本原则，包括未病先防与既病防变两个方面，为防治疾病之首务。，故为养生之首务"},{"q":"七情内伤最容易伤及的脏腑是:","o":["心、肝、脾","心、肺、脾","肝、脾、肾","肺、脾、肾","心、肺、肾"],"a":0,"e":"七情内伤以心、肝、脾受伤最多，心主神志、肝主疏泄、脾主运化皆与情志活动相关。，故情志病多涉三脏"},{"q":"“无阴则阳无以化”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":1,"e":"无阴则阳无以化说明阴阳互为存在前提，一方亏虚则另一方无以化生，属阴阳互根。，故治当阴阳并补"},{"q":"同名手足阳经交接的部位是","o":["腹","足","胸","头","手"],"a":3,"e":"同名手足阳经在头面部交接，如手阳明大肠经与足阳明胃经交于鼻翼旁，故交接部位为头。"},{"q":"《素问·金匮真言论》所说“善病洞泄寒中”的季节是","o":["春季","仲夏","长夏","秋季","冬季"],"a":2,"e":"长夏湿气盛，脾土易受湿困而运化失职，故《素问·金匮真言论》称长夏善病洞泄寒中。，故长夏宜健脾化湿"},{"q":"根据五行学说，脾虚病人面见青色是","o":["水克土","木乘土","土侮木","土生金","土克水"],"a":1,"e":"脾虚而面见青色，为肝木亢盛乘其虚衰之脾土，属五行相乘中的木乘土，非土侮木。，故色诊可察相乘"},{"q":"既属六腑，又属奇恒之腑的是","o":["三焦","女子胞","胆","胃","脑"],"a":2,"e":"胆既属六腑，又因藏精汁而不传化糟粕，形腑而功脏，被列为奇恒之腑，故二者兼属。，故当明其两属"},{"q":"运行在脉外并散行于全身的气是","o":["元气","宗气","营气","卫气","心气"],"a":3,"e":"卫气行于脉外，散布全身，具有温养脏腑、防御外邪和调节汗孔开合的作用，故属卫外之气。"},{"q":"阴损及阳的病机主要是指","o":["阴虚而阳相对亢盛","阴虚而导致阳气无以化生","阴寒病证转化为阳热病证","感受寒邪而伤及阳气","感受热邪而伤及阴津"],"a":1,"e":"阴损及阳指阴液亏虚日久，阳气化生无源而不足，即阴虚导致阳气无以化生之证。，治当阴阳双补"},{"q":"下列各脏中，其生理特性以升为主的是","o":["肺与脾","肺与肝","肝与肾","心与肾","肝与脾"],"a":4,"e":"肝主升发、脾主升清，二者生理特性均以升为主；肺主肃降、胃主降浊，其性主降。，故有升举之能"},{"q":"脾主运化是指","o":["运化水湿","运化水液","运化水谷和水液","运化水谷","化生血液"],"a":2,"e":"脾主运化包括运化水谷与运化水液两方面，为气血生化之源与人体水液代谢的枢纽。，故为后天之本"},{"q":"人体元气和水液运行的通道是指","o":["膀胱","肾","三焦","肝","脾"],"a":2,"e":"三焦为元气通行和水液运行的通道，故称决渎之官，总司全身气化与水道通利。，故为水道之枢"},{"q":"循行于头顶及后头部的经脉是","o":["足少阳胆经","足阳明胃经","足太阳膀胱经","足少阴肾经","足太阴脾经"],"a":2,"e":"足太阳膀胱经起于目内眦，上额交巅，循行头顶及后头部，再下项背而行于体表。，故头项痛多责膀胱经"},{"q":"下列哪项属于六淫致病特点以外的","o":["季节性","地域性","外感性","相兼性","强烈传染性"],"a":4,"e":"六淫致病具季节性、地域性、外感性与相兼性；强烈传染性为疠气的致病特点。，故当与疠气相别"},{"q":"“无阳则阴无以生”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":1,"e":"无阳则阴无以生，说明阳为阴化生之动力，阴阳互为根本依托，故属阴阳互根关系。，故阴阳不可偏废"},{"q":"下列选项中，属于瘀血所致疼痛特点，错误的是","o":["刺痛","固定不移","夜间加重","拒按","胀痛"],"a":4,"e":"瘀血疼痛多为刺痛、固定不移、拒按、夜间加重；胀痛游走不定则为气滞疼痛的特点。，故当细辨痛之性质"},{"q":"魄门位于","o":["大小肠连接处","胃与小肠连接处","胃上口","会厌","大肠末端"],"a":4,"e":"魄门即肛门，位于大肠末端，为七冲门中最后一道门户，主排泄糟粕，又名下极。，故为七冲门之末"},{"q":"脏与脏之间主要表现为气血关系的是","o":["心与肺","肺与肝","脾与肾","肝与肾","肺与肾"],"a":0,"e":"心主血、肺主气，心肺同居上焦，气血相互为用、相互依存，故主要表现为气血关系。，故称气血相关之脏"},{"q":"根据五行学说，“亢则害，承乃制”是","o":["相克关系","相生关系","相乘关系","制化关系","相侮关系"],"a":3,"e":"亢则害、承乃制指五行亢盛为害时随之有制以约束之，维持协调平衡，属五行制化关系。，故五行得以协调"},{"q":"易导致烦躁不安，失眠多梦，甚至神昏谵语的邪气是","o":["风邪","寒邪","湿邪","暑邪","燥邪"],"a":3,"e":"暑为阳邪，其性炎热升散，内扰心神则烦躁不安、失眠多梦，甚则神昏谵语、昏迷。，故暑病多见心神之扰"},{"q":"五脏的生理特点是","o":["贮藏精气","传化水谷","排泄糟粕","受盛水谷","主持诸气"],"a":0,"e":"五脏藏精气而不泻，满而不实，故其生理特点为贮藏精气；六腑传化物而不藏，泻而不藏。"},{"q":"人的生长发育取决于","o":["心气盈亏","脾胃健运","肾精盛衰","肝气调达","肺气宣降"],"a":2,"e":"肾藏精，精化气而生骨生髓，主生长发育与生殖，肾精盛衰决定生长壮老已全过程。，故为先天之本"},{"q":"“热极生寒”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":4,"e":"热极生寒指热发展到极点可向其对立面寒转化，属阴阳相互转化，与阴阳消长不同。，故寒热可极而变"},{"q":"与内脏位置恒定密切相关的脏是","o":["肝","肾","肺","脾","三焦"],"a":3,"e":"脾气主升，能升举清阳、托举内脏以维系其位置恒定，脾气下陷则见内脏下垂。，故有升举之职"},{"q":"“重阴必阳，重阳必阴”是指","o":["阴阳的对立制约","阴阳的互根互用","阴阳的消长平衡","阴阳的相互转化","阴阳的平衡关系失调"],"a":3,"e":"重阴必阳、重阳必阴指阴阳发展到极点时各自向其对立面转化，即阴阳相互转化。，故寒热之极则变"},{"q":"下列各项中不宜区分阴阳属性的是","o":["寒与热","邪与正","上与下","左与右","动与静"],"a":1,"e":"阴阳属性划分适用于相互关联的对立事物，寒热、上下、左右、动静皆可分阴阳，邪正不属此类。"},{"q":"“阳病治阴”适用于下列何证","o":["实热证","实寒证","阴阳两虚","虚寒证","虚热证"],"a":4,"e":"阳病治阴即滋阴以制阳，适用于阴虚不能制阳所致的虚热证，又称壮水之主以制阳光。，故与阴病治阳相对"},{"q":"阴阳平和质的体质特征为","o":["身体强壮，胖瘦适度；性格开朗随和，精力充沛，反应灵活","形体适中或偏瘦，但较结实；面色多略偏红或微苍黑，或呈油性皮肤","食量较大，消化吸收功能健旺；大便易干燥，小便易黄赤","形体适中或偏胖，但较弱，容易疲劳，面色偏白而欠华","食量较小，消化吸收功能一般；平时畏寒喜热，或体温偏低；精力偏弱，动作迟缓"],"a":0,"e":"阴阳平和质表现为身体强壮、胖瘦适度，性格开朗随和，精力充沛，反应灵活。，为体质之最佳状态"},{"q":"以下不属于狭义之神的是","o":["思维","意识","情感","生命活动","情绪"],"a":3,"e":"狭义之神指人的意识、思维、情感、情绪等精神活动；生命活动属广义之神。，故当分狭义广义"},{"q":"《素问·上古天真论》认为男性开始走向衰老的年龄段是","o":["五七","五八","四八","七七","八八"],"a":1,"e":"《素问·上古天真论》称男子五八肾气衰，发堕齿槁，故四十岁开始走向衰老。，故当知养生之节"},{"q":"属于病后防复的内容，下列错误的是","o":["防止复感新邪","防止传变","防止劳复","防止药复","防止食复"],"a":1,"e":"病后防复包括防复感新邪、防劳复、食复、药复等；防止传变则属既病防变。，故当辨其所属"},{"q":"下列属于阴的属性是","o":["向上的","温暖的","无形的","下降的","明亮的"],"a":3,"e":"阴的属性为向下、向内、静止、晦暗、寒冷、有形，故下降的属阴而上升的属阳。，此阴阳属性之常"},{"q":"患者胃肠热盛，大便秘结，腹满硬痛而拒按，潮热，神昏谵语，但又兼见面色苍白，四肢厥冷，精神委顿。其病机是","o":["虚中夹实","真实假虚","由实转虚","真虚假实","实中夹虚"],"a":1,"e":"胃肠热盛、腹满硬痛拒按为实，面色苍白、四肢厥冷、精神委顿为假虚之象，属真实假虚。"},{"q":"骨和髓之病变，论治的脏一般是","o":["心","肺","脾","肝","肾"],"a":4,"e":"肾主骨生髓，髓藏于骨中而充养骨骼，故骨与髓之病变论治多从肾入手，治以补肾填精。，故治骨先治肾"},{"q":"精的本始含义是指","o":["脏腑之精","津液","生殖之精","水谷之精","血液"],"a":2,"e":"精的本始含义指生殖之精，即男女媾精之精，后世延伸为构成人体的精微物质。，故当别于脏腑之精"},{"q":"六淫中最易导致疼痛的外邪是","o":["风邪","寒邪","湿邪","暑邪","热邪"],"a":1,"e":"寒性凝滞收引，易使经脉气血阻滞不通，不通则痛，故六淫之中寒邪最易导致疼痛。，故痛证多从寒治"},{"q":"共同调节情志活动的是","o":["心和肝","心和肺","脾和胃","肺和脾","脾和肾"],"a":0,"e":"心主神明，为五脏六腑之大主；肝主疏泄而调畅情志。二者一主神志、一主气机，共同调节情志活动。"},{"q":"健康人体的阴阳关系可以概括为","o":["阴阳互根互用","阴阳相互制约","阴平阳秘","阴阳消长","阴阳转化"],"a":2,"e":"阴阳双方在对立制约、互根互用中维持动态平衡，即“阴平阳秘，精神乃治”，为健康人体的总概括。"},{"q":"可以概括津和血之间可以相互转化、相互滋生的关系的是","o":["津可化血","血可化津","津血同源","津可养血","血可养津"],"a":2,"e":"津液与血液同由水谷精微化生，津可化血、血可化津，二者相互转化、相互滋生，故称津血同源。"},{"q":"下列哪项属于五行之“水”的归类","o":["肝","思","膀胱","长","辛"],"a":2,"e":"五行之水配属肾与膀胱，应冬、主寒、味咸、色黑、志恐。膀胱为贮尿排尿之腑，同归水行。"},{"q":"根据“脉应四时”的理论，夏季的主脉是","o":["弦","洪","毛","石","代"],"a":1,"e":"脉应四时，春弦、夏洪、秋毛、冬石。夏季阳气隆盛，气血充盈于外，脉来盛去衰，故主洪脉。"},{"q":"喜乐过度首先伤及","o":["肺气","肝血","肾精","脾气","心神"],"a":4,"e":"喜为心之志，喜则气缓；喜乐过度使心气弛缓涣散、神不守舍，故首先伤及心神，甚则狂乱。"},{"q":"别络分出的最小络脉是","o":["浮络","孙络","太阴别络","厥阴别络","少阳别络"],"a":1,"e":"经脉分出络脉，络脉再逐级细分，其最细小的分支为孙络，遍布全身，是气血输布的最小通路。"},{"q":"某些药物不仅自身对某脏某腑某经有天然的亲近性，还能够引导其他药物的药力到达该病处，起“向导”的作用，此即","o":["引经报使","药物归经","臣药","佐药","使药"],"a":0,"e":"药性对某脏腑经络有选择性亲和作用，并能引导他药直达病所、起向导之效者，称为引经报使。"},{"q":"具有调节生殖功能的两脏是","o":["心与肾","肺与肾","脾与肾","肝与肾","肝与脾"],"a":3,"e":"肾藏精而主生殖，肝藏血而主疏泄；精血同源、肝肾相生，天癸至而生殖功能成熟，故两脏共司生殖。"},{"q":"根据五行学说，“水气凌心”属于","o":["母病及子","相乘","子病犯母","相侮","制化"],"a":1,"e":"水气凌心为肾水泛滥上凌心火，属水行偏盛对其所胜之行的过度克制，即相乘；相侮则是反向克制。"},{"q":"中医学的预防思想称之为","o":["治未病","未病先防","既病防变","病后防复","先安未受邪之地"],"a":0,"e":"中医学将预防思想统称“治未病”，包括未病先防与既病防变，涵盖防病于先与早治防传。"},{"q":"过食咸味可致","o":["心盛乘肺","肝盛乘脾","脾盛乘肾","肺盛乘肝","肾盛乘心"],"a":4,"e":"咸味入肾，过食咸则肾气偏盛，水盛乘火，故见肾盛乘心，可见血脉凝涩、心悸胸闷。"},{"q":"机体精神活动的物质基础是","o":["精","气","血","津","液"],"a":2,"e":"血为神志活动的物质基础，血充则神旺、血虚则神衰，“血者，神气也”，故精神活动以血为本。"},{"q":"后天因素中，对禀赋影响最大的因素是","o":["情志变化","外伤疾病","生活起居","饮食劳逸","药邪医过"],"a":3,"e":"饮食劳逸直接关乎脾胃运化与气血化生，后天调摄失宜则禀赋难充，故其对禀赋影响最大。"},{"q":"将肺称为“娇脏”的主要依据是","o":["肺主一身之气","肺外合皮毛","肺通天气，不耐寒热","肺为水之上源","肺朝百脉"],"a":2,"e":"肺位最高，外合皮毛，直接通于天气，不耐寒热燥湿之邪，易受外邪损伤而发病，故称娇脏。"},{"q":"有加强表里两条经脉在体表联系作用者为","o":["浮络","络脉","十五别络","孙络","十二经别"],"a":2,"e":"十二经与任督二脉各别出一络，加脾之大络，合为十五别络，能加强表里两经在体表的联系。"},{"q":"五脏分阴阳，其中属于阴中之阴的是","o":["肝","心","脾","肺","肾"],"a":4,"e":"五脏分阴阳，心肺居上属阳，肝脾肾居下属阴；肾位于最下，又为阴脏，故属阴中之阴。"},{"q":"阳偏盛的治疗原则是","o":["滋阴壮水","寒者热之","补其不足","扶阳益火","热者寒之"],"a":4,"e":"阳偏盛则热，治当“热者寒之”，以寒凉清其亢阳；滋阴壮水针对阴虚阳亢，与实热治法不同。"},{"q":"脾阳虚衰，运化无权，水湿内停，肢体浮肿，下列哪一种病机描述更准确","o":["虚中夹实","实中夹虚","虚证","真虚假实","真实假虚"],"a":0,"e":"脾阳亏虚为本，运化无权而水湿内停为标，以虚为主兼夹实邪，故属虚中夹实之证。"},{"q":"以形神合一为理论基础的养生原则是","o":["顺应自然","形神兼养","保精护肾","调养脾胃","既病防变"],"a":1,"e":"形与神俱、形神合一，养生既须养形，又须调神，二者兼顾不偏，故其原则为形神兼养。"},{"q":"“既病防变”不仅是指对疾病进行早期治疗，还包括对疾病","o":["早期用药","早期预防","早期诊断","早期宣教","早期隔离"],"a":2,"e":"既病防变指疾病已成之后，及早诊断、及早治疗，截断病邪传变途径，防止其由浅入深。"},{"q":"手太阴肺经起始点是","o":["胸中","肺","胃口","腋窝","中焦"],"a":4,"e":"手太阴肺经起于中焦，下络大肠，还循胃口，上膈属肺，故其起始点为中焦；胸中为宗气所聚之处。"},{"q":"《黄帝内经》所说“大怒则形气绝，而血菀于上，使人薄厥”的病机，是指","o":["气不摄血","气机逆乱","血随气脱","血随气逆","血随气结"],"a":3,"e":"大怒则气上，血随气逆而上壅于头面，清窍被蒙而致薄厥，其病机为血随气逆，非血随气脱。"},{"q":"治疗大出血时，用益气固脱之法，其理论依据是","o":["气能生血","气能行血","气能摄血","血能载气","血能生气"],"a":2,"e":"气为血之帅，气能摄血；气虚则统摄无权而血溢脉外，故补气固脱以复其统摄之能，血自止。"},{"q":"适用于“土壅木郁”证的治则是","o":["抑强为主","扶弱为主","补母为主","泻子为主","母子同补"],"a":0,"e":"土壅木郁为脾土壅滞、反制肝木，属相乘为病，治当抑强为主，重在运脾化湿以复肝之疏泄。"},{"q":"肝藏血的生理功能是指肝","o":["贮藏血液","调节血量","统摄血液","贮藏血液、调节血量和防止出血","化生血液与统摄血液"],"a":3,"e":"肝藏血包括贮藏血液、调节血量与防止出血三方面，肝气收摄则血循常道而不妄溢于脉外。"},{"q":"与人体防御外邪能力关系最直接的脏是","o":["肝","心","脾","肺","肾"],"a":3,"e":"肺主气属卫，宣发卫气于肌表，卫外而为固；皮毛为其屏障，故肺与防御外邪关系最直接。"},{"q":"下列何项属于胃的生理特性","o":["喜燥","喜满","喜润","喜运","喜升"],"a":2,"e":"胃为阳腑，喜润恶燥，赖胃阴濡润方能受纳腐熟水谷、下传小肠，故其生理特性为喜润。"},{"q":"七情刺激，易导致心气涣散的是","o":["喜","怒","悲","恐","惊"],"a":0,"e":"喜为心之志，喜则气缓；过喜使心气弛缓不收、神不守舍，故轻则心悸，重则心神涣散。"},{"q":"元气运行的道路是","o":["心脉","胸腔","全身","脉外","三焦"],"a":4,"e":"元气根于肾，赖三焦为通道布散全身，内至脏腑、外达肌肤；三焦通行元气，亦为气化之所。"},{"q":"形成虚实错杂的病机是","o":["邪盛正衰","邪盛正未衰","正虚邪不盛","邪去正衰","正胜邪退"],"a":0,"e":"邪气亢盛而正气已衰，正虚与邪实同时存在，故形成虚实错杂的病机，治当攻补兼施。"},{"q":"运用姜汤治疗风寒感冒，说明了阴阳间的何种关系","o":["阴阳互根","阴阳对立制约","阴阳交感互藏","阴阳自和","阴阳转化"],"a":1,"e":"生姜辛温，能发散风寒，以温热之性制约寒邪之阴，寒去则阴阳复衡，体现阴阳对立制约。"},{"q":"在头面部，分布于侧头部的经脉是","o":["太阴经","阳明经","厥阴经","太阳经","少阳经"],"a":4,"e":"手足少阳经循行于头侧部，阳明行于前、太阳行于后，故侧头部为少阳经所主，头痛多取少阳。"},{"q":"下列不属于气的固摄作用的是","o":["控制血液运行于脉中","防止汗出过多","固摄精液","固摄内脏的位置","控制尿液的排泄"],"a":3,"e":"气的固摄作用主要统摄血液、控制汗液尿液、固摄精液，防止液态物质无故流失；内脏位置的稳定靠气的升举之力，不属固摄。"},{"q":"哪一项体现肺的肃降功能","o":["宣发卫气至皮毛腠理","治理调节呼吸运动","辅助心行血于周身","呼出体内浊气","吸入自然界清气"],"a":4,"e":"肃降是肺气向下向内布散，包括吸入自然界清气、下输津液并肃清异物；宣发卫气与呼出浊气则属宣发。"},{"q":"下列选项中，属于《金匮要略》记载的四饮，错误的是","o":["留饮","痰饮","悬饮","溢饮","支饮"],"a":0,"e":"《金匮要略》四饮为痰饮、悬饮、溢饮、支饮，按水饮停留部位划分；留饮指水饮留而不行，不属四饮。"},{"q":"肾在体合","o":["筋","脉","肉","皮","骨"],"a":4,"e":"肾藏精，精生髓，髓居骨中而充养于骨，故肾在体合骨；其华在发，齿为骨之余，骨之坚脆取决于肾精盛衰。"},{"q":"“利小便所以实大便”治法的依据是","o":["小肠泌别清浊","脾运化水液","肺宣发肃降","肾阳气化","肾主水液"],"a":0,"e":"小肠泌别清浊，水液经三焦下渗膀胱而为尿，糟粕传于大肠；利小便则水从前阴去而大便自实。"},{"q":"七情内伤致病最易损伤哪几脏","o":["心肺脾","心肺肝","肺脾肾","心肝脾","肝脾肾"],"a":3,"e":"七情皆从心而发，郁怒伤肝，思虑伤脾，故七情内伤以心、肝、脾三脏受累最多，心神先伤。"},{"q":"“治未病”包括","o":["防止疾病的发生和发展","外避病邪和既病防变","未病先防和早期诊治","未病先防和既病防变","调养正气和控制病传"],"a":3,"e":"治未病包括未病先防与既病防变：前者养生御邪，后者早诊早治以防传变，二者相辅相成。"},{"q":"以下除哪项外均属于奇恒之腑","o":["三焦","脑","女子胞","骨","脉"],"a":0,"e":"奇恒之腑为脑、髓、骨、脉、胆、女子胞，形态似腑而功能似脏；三焦属六腑，不在此列。"},{"q":"具有“阳脉之海”之称的是","o":["督脉","冲脉","任脉","带脉","跷脉"],"a":0,"e":"督脉行于背正中，总督一身之阳经，故称阳脉之海；任脉总任阴经为阴脉之海，冲脉为十二经之海。"},{"q":"肝在志为","o":["喜","思","怒","恐","悲"],"a":2,"e":"肝在志为怒，肝气升发条达而恶抑郁；怒则气上，过怒伤肝，甚则血随气逆、阳升风动而昏厥。"},{"q":"“阴病治阳”适用于下列何证","o":["实热证","实寒证","阴阳两虚","虚寒证","虚热证"],"a":3,"e":"阴病治阳指阳虚不能温煦而现虚寒之证，治当温补阳气，即益火之源以消阴翳，不可误作滋阴。"},{"q":"心在志为","o":["怒","思","悲","喜","恐"],"a":3,"e":"心在志为喜，心藏神；喜则气和志达、营卫通利，过喜则心气弛缓涣散而神不守舍，可见心悸失眠。"},{"q":"肺为“水之上源”的主要依据是","o":["肺位最高，通调水道","肺具有布散津液的功能","肺具有输精于皮毛的功能","肺为脏腑之华盖","饮入于胃，上归于肺"],"a":0,"e":"肺居脏腑最高之位，主通调水道，使水液下输膀胱、外达皮毛，故有“水之上源”之称。"},{"q":"某退休干部因注重养生，而气色红润。下列属于“调神养生”错误的是","o":["清静养神","立志养德","开朗乐观","心细如发","心态平衡"],"a":3,"e":"调神养生重在清静养神、立志养德、开朗乐观、心态平衡；心细如发属思虑琐细，反耗神伤脾。"},{"q":"六淫中，感受湿邪后，有的患者双膝关节沉重，伴下肢麻木不仁，阴雨天加剧，可称为","o":["痛风","寒痹","痛痹","着痹","行痹"],"a":3,"e":"湿性重浊黏滞，湿邪偏盛则关节沉重、下肢麻木不仁，阴雨湿盛而加剧，是为着痹，治宜除湿。"},{"q":"以下哪项属于五脏之一","o":["胆","胃","心","三焦","脑"],"a":2,"e":"五脏指心、肝、脾、肺、肾，主藏精气而不泻；胆、胃、三焦均属六腑，脑为奇恒之腑。"},{"q":"根据阴阳虚实对体质进行分类的医家是","o":["岐伯","张仲景","张景岳","章虚谷","叶天士"],"a":3,"e":"章虚谷以阴阳虚实为纲，将体质分为阳旺阴虚、阴阳俱盛、阴盛阳虚与阴阳两虚四类。"},{"q":"对疾病力求早期诊断、早期治疗的目的","o":["提高正气抗邪能力","尽早确立治疗方法","提高诊断的正确率","中止其病情的发展变化","延缓疾病的恶化"],"a":3,"e":"早期诊断、早期治疗旨在截断病邪传变途径，中止病情的发展变化，而非仅缓解一时症状。"},{"q":"猝受惊恐之人，面色煞白，是由于","o":["气结","气消","气缓","气下","气上"],"a":3,"e":"恐则气下，惊恐使肾气不固、气陷于下，气血不能上荣头面，故面色煞白、二便失禁。"},{"q":"五志与五脏对应关系，肺在志为","o":["喜","怒","思","悲","恐"],"a":3,"e":"肺在志为悲，悲忧同类，悲则气消；过悲则肺气耗伤，见气短乏力、精神不振、声低懒言。"},{"q":"与津液输布关系最密切的脏腑组是","o":["脾、肾、小肠、三焦","脾、肝、肾、三焦","肺、肾、三焦、小肠","肝、肺、脾、肾、三焦","心、肾、小肠、膀胱"],"a":3,"e":"津液输布由脾之运化、肺之宣降、肾之主水、肝之疏泄与三焦之通调共同完成，故涉五脏三焦。"},{"q":"关于心肾相交，以下哪种说法是正确的","o":["水火相克","心肾间病理关系","肾阳上济于心， 心阴下降于肾","肾水上济于心， 心火下降于肾","心气不降及肾， 肾阴不上承于心"],"a":3,"e":"心肾相交指肾水上升以济心阴、使心火不亢，心火下降以温肾水、使肾水不寒，水火既济。"},{"q":"根据五行学说，下列情志相胜中错误的是","o":["喜胜恐","恐胜喜","怒胜思","喜胜悲","思胜恐"],"a":0,"e":"五行相胜为怒胜思、思胜恐、恐胜喜、喜胜悲、悲胜怒。喜属火、恐属水，水克火故恐胜喜，喜胜恐相悖。"},{"q":"下列除哪项外均属于顺应自然养生","o":["晨练","春夏养阳，秋冬养阴","顺应四时调摄","昼夜晨昏调养","起居有常"],"a":0,"e":"顺应自然指顺应四时阴阳与昼夜晨昏调摄起居，如春夏养阳、秋冬养阴；晨练属运动养生，不在其列。"},{"q":"理想的体质应是","o":["偏阴质","偏阳质","特禀质","痰湿质","阴阳平和质"],"a":4,"e":"阴阳平和质阴阳气血协调、脏腑功能旺盛、对外适应力强，少患病而易康复，为理想体质。"},{"q":"疾病病势缠绵，其邪正关系一般是","o":["邪胜正虚","邪正相持","邪去正虚","正虚邪恋","正胜邪退"],"a":3,"e":"正虚邪恋指正气已虚而余邪未尽，邪正相持不下，故病势缠绵、迁延难愈，多见于病之后期。"},{"q":"六淫中其性干涩，易伤津液的邪气是","o":["风邪","寒邪","湿邪","暑邪","燥邪"],"a":4,"e":"燥邪其性干涩，易伤津液，症见口鼻干燥、皮肤皲裂、干咳少痰；燥易伤肺，故先犯肺卫。"},{"q":"关于实火和虚火的对比，论述错误的是","o":["实火病势急速，病程较短，虚火病势缓慢，病程较长","实火缘于阳热有余，虚火缘于阴液不足","实火可见壮热面赤，虚火可见潮热盗汗","实火多见于男性，虚火多见于女性","实火属于实证，虚火属于虚证"],"a":3,"e":"实火与虚火依病性、病势及阴阳盛衰区分，与性别无对应关系，故按男女划分之说错误。"},{"q":"六淫邪气中，具有“阻遏气机”特点的是","o":["风","暑","湿","寒","火"],"a":2,"e":"湿性重浊黏滞，易阻遏气机，困阻脾胃而升降失常，故见胸闷脘痞、身重困倦、大便不爽。"},{"q":"下列各项，适合用清法的是","o":["阳气被郁而发热者","气虚致热证者","血虚致热证者","肺热咳嗽","脏腑本寒者"],"a":3,"e":"清法以寒凉之品清解热邪，适用于肺热咳嗽等实热证；阳虚、气虚、血虚所致发热当温补，非清法所宜。"},{"q":"下列哪项不是瘀血的别名","o":["恶血","败血","蓄血","衃血","离经之血"],"a":4,"e":"瘀血又称恶血、败血、蓄血、衃血；离经之血指血溢脉外，是瘀血形成的前提，不属其别名。"},{"q":"维持呼吸深度需下列哪一脏的功能","o":["肝","肺","心","肾","脾"],"a":3,"e":"肾主纳气，能摄纳肺吸入之清气，使呼吸保持一定深度；肾虚不纳则呼吸表浅、动则气喘。"},{"q":"适用“热因热用”治则的是","o":["热病见热象","寒病见热象","阴虚见热象","热病见寒象","寒病见寒象"],"a":1,"e":"热因热用指以温热药治假热之证，适用于阴寒内盛、格阳于外而反见身热面赤者，属反治之法。"}];
